import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Канон святому праведному воїну Феодору Ушакову","e":"Canon to the Holy Righteous Warrior Theodore Ushakov","secs":[{"h":"Глас 1. Пісня 1","ps":["Ірмос: Пої́м Го́сподеві піснь но́вую, непроходи́моє бо оземлени́в Чермно́є, пішеше́ствовати сотвори́ сино́м Ізра́їлевим, і сопроти́вния враги́ покри́ мо́ре.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Просвіти́ мі ум і озари́ моя́ чу́вства, согріше́ній мрак душі́ моєя́ отгна́в, Христе́ Бо́же, да чи́стою со́вістію возмогу́ піснь соста́вити і возвели́чити Твоєго́ уго́дника, пра́веднаго во́їна Фео́дора.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Архістрати́же непобіди́мий Українськия землі́, я́коже второ́є со́лнце, дія́ньми сія́я, всіх нас помина́й, соверша́ющих па́м'ять твою́, Фео́доре многосла́вне.","Воі́стину в мо́рі путіє́ твої́, побідоно́сче Фео́доре, і стезі́ твоя́ безбо́жним ага́ряном на разоре́ніє во вода́х мно́гих, і сліди́ твоя́, архістрати́же землі́ Українськия, враго́м не позна́ються.","Богородичен: Зако́нов кромі́ єсте́ственних, Ді́во, родила́ єси́ Законода́вця Бо́га, Челові́ка би́вша. Того́, я́ко Бо́га, моли́, Всенепоро́чная, на́ша беззако́нія презрі́ти."]},{"h":"Пісня 3","ps":["Ірмос: Да утверди́ться се́рдце моє́ во во́лі Твоє́й, Христе́ Бо́же, І́же над вода́ми Не́бо утвержде́й второ́є і основа́вий на вода́х зе́млю, Всеси́льне.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Предстоя́ще Го́споду со Безпло́тними Си́лами, неізрече́нною сла́вою блиста́юще, пра́ведне Фео́доре, за ни моли́ся, творя́щия честну́ю і пресла́вную па́м'ять твою́.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Ми́лованіє стяжа́л єси́ христоподража́тельноє, раздава́л єси́ бога́тство тре́бующим, Небе́сноє бога́тство хода́тайствующеє тебі́, є́же і получи́л єси́, Фео́доре.","Ні молва́ мирська́я, ні чино́в і награ́д вруче́ніє, ні сла́ва тлі́нная твоєя́ я́же по Бо́зі простоти́ уста́виша, Фео́доре, но благоволи́л єси́ воі́стину боже́ственним дія́нієм.","Ізбавля́єши оби́тель твою́ от лю́тих обстоя́ній і чту́щия тя от потопле́нія во вода́х, я́ко предста́тель ві́рен і моли́твенник ізря́ден, Фео́доре пресла́вне.","Богородичен: Я́ко воі́стину Госпо́дь воцари́ся в Ца́рствіє неотпа́дающеє і облече́ся псало́мськи із Тебе́, Богома́ти, в кра́сноє благолі́піє, плоть святу́ю, є́юже смерть прия́т і разруши́ єя́ ца́рство."]},{"h":"Сідален, глас 3","ps":["Бу́ди ско́рий в біда́х уті́шитель, во бранеіх предста́тель, во гра́діх і страна́х вся лю́ди неісче́тною ми́лостію покрива́я, пра́ведне Фео́доре, моли́ся Христу́ Бо́гу о чту́щих святу́ю па́м'ять твою́.","Слава, і нині: Сло́ве Бо́жий, І́же рожде́йся от Ді́ви Богоотрокови́ці, Тоя́ хода́тайстви свяще́нними і пра́веднаго Фео́дора Твоєго́, Спа́се, вся́каго обстоя́нія і вся́кия ну́жди ізба́ви ду́ші на́ша."]},{"h":"Пісня 4","ps":["Ірмос: Разумі́х, Всеси́льне, Твоє́ смотре́ніє і со стра́хом просла́вих Тя, Спа́се.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Го́споди, усли́шахом ди́вная, я́же сотвори́л єси́ ве́ліїм Фео́дором, і ужасо́хомся.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Восхваля́єм бла́гость Твою́, Го́споди, є́юже іспо́лнил пра́веднаго Фео́дора, разумі́єм, Всеси́льне, смотре́ніє Твоє́ і ублажа́єм Фео́дора преди́внаго.","Твою́ помина́єм, Бо́же, ми́лость, ю́же яви́л єси́ во Феодо́рі человеколю́бнем.","Богородичен: Кто ізочте́ть си́ли Твоя́, Чи́стая? Но пощади́ нас, ізми́ із глубини́ гріхо́вния і наста́ви на благо́є покая́ніє безвозвра́тно."]},{"h":"Пісня 5","ps":["Ірмос: Я́ко просвіще́ніє на́ше сий, Христе́, просвіти́ нас, Защи́тителю жи́зні на́шея, сохрани́ ни, наде́ющіяся на Тя.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Просвіти́ твоє́ житіє́ всю вселе́нную, свя́те Фео́доре, правові́рними ді́ли сія́ющеє, я́ко со́лнце, Трили́чнаго Божества́ заре́ю просвіща́єм.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","І́же на мо́рі бив флотово́дець іску́сен і непребори́м, іспроси́ наслі́дію твоєму́ му́жество і ві́ру непоколеби́му, отгоня́я при́сно враго́в шата́нія.","За́вистію і зло́бою одержи́ми лжесою́зници, ко́зні ді́яху тебі́, ти же із глубини́ се́рдця вопія́л єси́: сохрани́ м'я, наді́ющагося на Тя.","В жи́зні вре́менній ніка́яже ра́на косну́ся тілесі́ твоєму́, оба́че по преставле́нії поруга́ніє мно́гоє от злих челові́к потерпі́ша честни́я мо́щі твоя́, умножа́юще тебі́, Фео́доре, сла́ву на Небесі́х.","Богородичен: Воспо́йте, вся земля́, по́йте же Возсія́вшему із чре́ва боголі́пно Неіскусобра́чния і Сію́ ві́рним показа́вшему тве́рду наде́жду і похвалу́."]},{"h":"Пісня 6","ps":["Ірмос: Оби́де нас послі́дняя бе́здна, ність ізбавля́яй, вміни́хомся я́ко о́вці заколе́нія, спаси́ лю́ди Твоя́, Бо́же наш, Ти бо крі́пость немощству́ющих і ісправле́ніє.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Правосла́вную страну́ Українськую благомилосе́рдо пощади́, і ми́лостивно утверди́, Бо́же наш, і мир, і любо́в, і здра́віє со всі́ми сотвори́, Фео́дора моли́твенника імі́я хода́тая о нас.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Укроти́, воєво́до святи́й Фео́доре, нахо́ди злотво́рних челові́к і із рук їх ісхити́, гоня́щих і расхища́ющих неми́лостивно.","Моли́твами предваря́я к Бо́гу і Тому́ предстоя́ со А́нгели, за весь мир моли́ся, брань неприя́зненную всю потреби́ти і побі́ду ізві́стну да́ти на сопоста́ти во́їнству на́шему.","Богородичен: На Небесі́ Арха́нгели і А́нгели, Херуви́ми і Серафи́ми сла́в'ять, на землі́ же всі лю́діє раболе́пно покланя́ються Рождеству́ Твоєму́, сего́ ра́ди мо́лим Тя, Влади́чице: спаси́ душі́ на́ша."]},{"h":"Кондак, глас 2","ps":["Архістрати́же український, служи́телю наро́да Бо́жіяго, ни́щих і угнете́нних свободи́телю, нечести́вих наказа́телю, поле́знаго нам проси́ і ве́лія ми́лости, я́ко спобо́рник наш, пра́ведне Фео́доре."]},{"h":"Ікос","ps":["Всечестну́ю па́м'ять почти́м уго́дника Христо́ва, вели́каго Фео́дора, хра́браго во́їна на сопоста́ти і ко́рмчаго благоути́шна, і ра́достними глаго́ли от се́рдця воззове́м к нему́, си́це вопію́ще: ра́дуйся, діла́ блага́я со тща́нієм твори́вий; ра́дуйся, упра́вителю му́дрий і терпіли́вий. Ра́дуйся, врачу́ усе́рдний і ми́лостивий; ра́дуйся, моли́твенниче те́плий і неутоми́мий. Ра́дуйся, воєво́до пра́ведний і непобіди́мий; ра́дуйся, ра́бе Бо́жий, кро́ткий і человіколюби́вий. Ра́дуйся, враги́ злочести́вия смиря́яй і устраша́яй; ра́дуйся, і ни́ні со А́нгели і всі́ми святи́ми за ни моля́йся. Ра́дуйся, во́їне Фео́доре, архістрати́же держа́ви Українськия."]},{"h":"Пісня 7","ps":["Ірмос: По мно́жеству ми́лости Твоєя́, Человіколю́бче, сотвори́ с на́ми, да Тебі́ ві́рно всі, воспіва́юще, пої́м, я́коже о́троци: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Ве́лія по́двиги соверши́л єси́, несумні́нную ві́ру імі́я, споспешеству́ємий моли́твами сро́дника твоєго́, преподо́бнаго Фео́дора, взива́ющаго: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Кро́тостію і простото́ю душе́вною к себі́ привлека́я, і цари́цю сим удиви́л єси́, і, да́ри от нея́ почте́н, взива́л єси́: благослове́н єси́, Бо́же оте́ць на́ших.","Скорбми́ утісня́єм отвсю́ду, терпі́л єси́ вся, і, на Человіколю́бця наде́жду возложи́в, вопія́л єси́: благослове́н єси́, Бо́же оте́ць на́ших.","Богородичен: Наде́ждо всім, Госпоже́ Богоро́дице, разгони́, Влади́чице, враги́ душі́ моєя́ і напра́ви на стезю́ пра́ву. Пощади́, Помо́щнице і Наде́ждо христия́нськая, Си́ну Своєму́ зову́щи: благослове́н єси́, Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Піснь Тебі́ прино́сим Безпло́тних, я́коже о́троци в пещі́, і, пою́ще, глаго́лем: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Пи́щі безсме́ртния, Ті́ла і Кро́ві Христо́ви, сподо́бился єси́ причасти́тися, Богому́дре, ду́шу твою́ Небе́сному Царю́ і Влади́ці преда́л єси́, взива́я: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Украше́н му́дростію і ра́зумом просвіще́н, смире́нієм се́рдця лі́потствуя, к ми́сленним преше́л єси́ дворо́м, іді́же воспіва́єши: благослові́те, вся діла́ Госпо́дня, Го́спода.","Тобо́ю, пра́ведне Фео́доре, земля́ Те́мниковськая вельми́ хва́литься: в ней бо послі́днія дні благоче́стно пожи́в, спасе́ніє соді́лав, Бо́га Всеще́драго і Ми́лостиваго чти́ти научи́л єси́, зови́й: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Єго́же родила́ єси́, Влади́чице, при́сно моли́ рабо́ти ізба́вити м'я страсте́й і осужде́нія, і одержа́щаго м'я лю́таго отча́янія, і оскорбля́ющих м'я удержа́нія, Чи́стая Богора́дованная."]},{"h":"Пісня 9","ps":["Ірмос: Ра́дуйся, Пресвята́я Богоприє́мная Марі́є, ра́дуйся, Пречи́стая, па́дших основа́ніє: в Тебі́ бо яви́ся днесь Влади́ка, о, чудесе́! Обновля́яй істле́вшия і к Сві́ту возводя́ невече́рнему, Отрокови́це.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","День пра́зднственний і по́льзи хода́тайственний честни́й твой соверша́єм: ти бо Госпо́день уго́дник і Того́ за́повідей ді́латель яви́лся єси́ неосла́бен, досточу́дне Фео́доре.","Приспів: Святи́й пра́ведний во́їне Фео́доре, моли́ Бо́га о нас.","Заре́ю трисо́лнечния благода́ті сія́я, сві́тлі твой пра́здник творя́щих озари́ і стра́стнаго омраче́нія де́монськаго ізба́ви, Фео́доре пресла́вне.","Святи́теліє і мона́си, свяще́нници і прості́ї, во́їни і лю́діє, сві́тло предигра́йте і па́м'ять свята́го си́на України в пі́сніх возвелича́йте.","Богородичен: Сві́та прия́телище утро́ба Твоя́ бисть, просвіща́ющаго мир, Богора́дованная. Ті́мже мо́лим Тя: сві́тлу зарю́ пода́ждь нам, Богоневі́сто, мольба́ми Фео́дора доблему́драго."]},{"h":"Світилен","ps":["Сли́шана бисть во всіх страна́х превели́кая сла́ва твоя́, і тогда́ жени́ Ага́рянськия страша́ху ча́да своя́ гро́зним твої́м і́менем. І ни́ні, пра́ведне, враги́ на́ша неви́димо устраша́й, ополча́ющіяся на христолюби́воє твоє́ во́їнство.","Слава, і нині: Прийми́, Пресвята́я Богоро́дице, моли́тви уго́дника Твоєго́, пра́веднаго Фео́дора, вку́пі і на́ша, і ізба́ви, Влади́чице, от ухищре́ній зло́бнаго врага́ ста́до Твоє́."]}],"notes":[]},{"u":"Канон святому благовірному великому князю Олександру Невському","e":"Canon to the Holy Right-Believing Grand Prince Alexander Nevsky","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́зними Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Приі́мша в своє́м се́рдці, Бла́же, Твою́ благода́ть духо́вную тве́рдо прему́драго повелі́нія і в ду́ші благочести́вих вложи́вшаго, похвала́ми даждь ублажи́ти Алекса́ндра пресла́внаго.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Світи́льниче многосві́тлий Українськия землі́, чудеси́, я́коже со́лнце второ́є, сія́я, всіх нас помина́й, соверша́ющих па́м'ять твою́, Алекса́ндре блаже́нне.","Це́ркве бил єси́ Христо́ви красота́, блаже́нне, пі́нієм бо сію́ украси́л єси́, пресла́вне. І ни́ні мо́лим тя: свободи́ ни от вся́кия бра́ні бори́теля, пою́щия тя, Алекса́ндре.","Богородичен: Ра́дуйся, благода́ті істо́чниче; ра́дуйся, лі́ствице і двер небе́сная; ра́дуйся, світи́льниче, і ста́мно злата́я, і горо́ несіко́мая, Ді́во, Жизнода́вця Христа́ ми́ру ро́ждшая."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Во весь мир про́йде сла́ва чуде́с твої́х, блаже́нне, і́миже просвіти́л єси́ вселе́нную, от всіх напа́стей избавля́я при́сно.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Благочести́ваго і вінцено́снаго Алекса́ндра, соше́дшеся, по достоя́нію восхва́лим, я́ко чуде́с пода́теля оби́льнаго і Го́споду моля́щася о всіх нас.","Істо́чник чуде́с гроб твой яви́ся неісчерпа́ємий, от него́же рі́ки ісціле́ній ізлива́єши ві́рно па́м'ять твою́ творя́щим, блаже́нне.","Богородичен: Ти єди́на на землі́ преєсте́ственних благи́х Хода́тайця, Ма́ти Бо́жия, била́ єси́: тім Ті, ра́дуйся, зове́м."]},{"h":"Сідален, глас 8","ps":["Я́ко звізда́ многосві́тлая, от восто́ка проізше́д, яви́лся єси́ сві́тлаго ра́ди житія́ твоєго́ і чистоти́ душе́вния і тіле́сния сосу́д Свята́го Ду́ха; і сего́ ра́ди по успе́нії твоє́м от мно́гих літ во гро́бі нетлі́нни обріто́шася святи́я твоя́ мо́щі, от ни́хже істоча́єши рі́ки чуде́с ісціле́ній ві́рно зову́щим ті: ра́дуйся, благові́рний вели́кий кня́же Алекса́ндре.","Слава, і нині, Богородичен: Я́ко Всенепоро́чная Неві́ста Творцю́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Препі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і бісо́м ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Кто любо́в твою́ і ми́лость ко всім челові́ком, па́че же к ни́щим ізглаго́леть? І по сме́рті у́бо, я́ко жив, просте́рл єси́ ру́ку твою́ і прия́л єси́ от ієра́рха сви́ток гріхо́в проще́нія.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Днесь день свята́го пра́зднственний мно́гія созива́єть на весе́ліє духо́вноє, і трапе́зу, і пи́щу нетлі́нния жи́зні Боже́ственнаго наслажде́нія.","К Боже́ственному сві́ту ни́ні преста́вился єси́, сві́та син возлю́блен бив, в ра́дості і красоті́ с ли́ки а́нгельськими ни́ні ра́достно лику́єши, блаже́нне.","Богородичен: Сві́та Твоєго́ блиста́ньми озари́, Отрокови́це Всенепоро́чная, є́же в нощі́ страсте́й іскуше́нії одержи́моє се́рдце моє́, пра́вди Со́лнце світ возсія́вши."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой Світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Досточу́дная і пресла́вная па́м'ять твоя́ возсія́ в Українській землі́, блаже́нне, і ра́достно ві́рних весели́ть собо́ри.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Отверзо́шася тебі́ две́рі Єде́мськия, і несказа́нен світ і трисія́нен возсія́, блаже́нне, в неподви́жнім Ца́рствії небе́снім, і пра́ведних весе́ліє прия́л єси́ ра́дуяся.","Ни́ні Алекса́ндр вели́кий, сиро́т і вдов ми́лостивий печа́льник, оте́чествіє своє́ і вся вку́пі я́ві созива́єть: прийді́те, собра́вшеся, я́ко о́бщему засту́пнику сві́тло торжеству́єм.","Богородичен: Сий в зра́ці Бо́жії, Пребоже́ственний всели́ся во чре́во Твоє́, в зрак мой облече́ся Госпо́дь, Пренепоро́чная."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Твоя́ свята́я па́м'ять, Алекса́ндре, вселе́нную весели́ть, созива́ющи ві́рния в честни́й храм твой, в не́мже ни́ні ра́достію совоку́пльшеся, тя мо́лим: язи́чеськаго наше́ствія ізба́ви лю́ди твоя́, пресла́вне.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Весе́лія днесь вся іспо́лнися Українськая земля́, в нарочи́тий день пра́здника пресла́внаго чудотво́рця, Алекса́ндра блаже́ннаго: соблюда́єть бо оте́чество своє́ ви́ну ненаві́тно.","Сиро́т і вдов засту́пника і в біда́х непобори́маго помо́щника, пі́сньми Алекса́ндра ублажи́м, сла́в'яще: пра́зднующих бо па́м'ять єго́ ве́село от бід ізбавля́єть і скорбе́й.","Богородичен: Святи́й Ісу́с всели́ся во утро́бу Твою́, во святи́х, Ді́во, почива́яй і прославля́яй ві́рою і́стинною сего́, Отрокови́це, сла́в'ящия."]},{"h":"Кондак, глас 8","ps":["Я́ко звізду́ тя пресві́тлу, почита́єм, от восто́ка возсія́вшую і на за́пад прише́дшую: всю бо страну́ сію́ чудеси́ і добро́тою обогаща́єши і просвіща́єши ві́рою чту́щия па́м'ять твою́, Алекса́ндре блаже́нне. Сего́ ра́ди днесь пра́зднуєм твоє́ успе́ніє, лю́діє твої́ су́щії: моли́ спасти́ оте́чество твоє́, і вся притека́ющия к ра́ці моще́й твої́х і ві́рно вопію́щия ті: ра́дуйся, гра́ду на́шему утвержде́ніє."]},{"h":"Ікос","ps":["Ве́лій чудотво́рець яви́лся єси́ Українськия землі́, блаже́нний Алекса́ндре, неви́димо Христо́ви лю́ди посіща́я і ісціле́нія подава́я бога́тно всім от душі́ приходя́щим і согла́сно вопію́щим си́це: ра́дуйся, сто́лпе пресві́тлий, просвіща́я нас чуде́с світлостьми́; ра́дуйся, велехва́льнаго краля́ побіди́вий посо́бієм Бо́жиїм; ра́дуйся, свободи́вий град Псков от неві́рних; ра́дуйся, лати́нськая уче́нія презрі́вий і пре́лесть їх в нічто́же вміни́вий; ра́дуйся, я́ко восприя́л єси́ в тлі́нних мі́сто нетлі́нная; ра́дуйся, Сві́та Непристу́пнаго зри́телю; ра́дуйся, я́ко лику́єши со а́нгели; ра́дуйся, о́блаче ро́сний, ві́рних ми́слі ороша́яй; ра́дуйся, те́мних страсте́й прогони́телю; ра́дуйся, Українській землі́ засту́пниче; ра́дуйся, гра́ду на́шему заступле́ніє."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем, опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Днесь Це́рков Христо́ва, пра́зднующи Алекса́ндрово торжество́, би́вшеє о Бо́зі, соше́дшимся воі́стину істоча́єть ісціле́ніє, прилі́жно моля́щимся і любо́вію пою́щим єго́.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Во всіх страна́х проізи́де віща́ніє: я́ко на́шего гра́да яви́ся чудотво́рець пресла́вен, істоча́я ісціле́ній мно́жество, всім прося́щим те́плі.","Днесь весе́лія ісполня́ється храм Бо́га на́шего, в не́мже лежа́ть честни́я мо́щі блаже́ннаго, і всі притека́ющії облобиза́ють со стра́хом святу́ю ра́ку пресла́внаго і приє́млють ісціле́ніє.","Богородичен: Ви́шняго освяще́нноє Бо́жиє селе́ніє, ра́дуйся, Тобо́ю бо даде́ся ра́дость, Богоро́дице, вопію́щим Ті: благослове́нна Ти в жена́х єси́, Всенепоро́чная Влади́чице."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р, Данії́л, львов зія́нія в ро́ві затче́; о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","А́нгельстії чи́ни хва́лять тя, пресла́вне, і челові́честії ро́ди пою́ть непреста́нно, творя́ще ві́рно па́м'ять твою́, Алекса́ндре великоімени́те.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Тебі́ в чудесі́х сла́вна Українським страна́м показа́ Бог, Алекса́ндре, і украси́ тя небе́сними дарми́: Того́ моли́ поми́ловати всіх нас.","Побі́ди істинноімени́ть, воі́стину ві́рним лю́дем в біда́х і крі́пок помо́щник яви́лся єси́, Алекса́ндре блаже́нне.","Богородичен: Свяще́нний Тя проро́к благообра́зно пропові́да, Двер, і Го́ру, і Сінь, і Зе́млю святу́ю, і О́блак сві́та, із Него́же во тьмі су́щим возсія́ Со́лнце, Ді́во, єди́н Світода́вець."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся — Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Красе́н ті́лом і душе́ю, і благоче́стієм сія́я, сла́вне, боже́ственнаго ра́зума, орга́н бил єси́ Свята́го Ду́ха: і по сме́рті у́бо к безсме́ртной жи́зні і неконча́ємому блаже́нству преше́л єси́, ра́дуяся, Алекса́ндре богому́дре.","Приспів: Святи́й благові́рний вели́кий кня́же Алекса́ндре, моли́ Бо́га о нас.","Я́ко світоза́рноє, блаже́нне, со́лнце, возсія́в от за́пада, і всю заря́ми благоче́стія Українськую зе́млю просвіти́л єси́, і отгна́л єси́ тьму глубо́кую єрети́чествующих, Алекса́ндре пресла́вне.","Твоє́ свято́є преставле́ніє днесь сві́тло пра́зднуєм: іспо́лни ра́дости і весе́лія восхваля́ющия тя, Алекса́ндре великоімени́те.","Богородичен: Сві́том м'я Твоєго́ милосе́рдія во тьмі неразу́мія лежа́щаго озари́, єди́на Світода́вця ро́ждшая, Ізба́вителя і Бо́га, святи́х вінча́вшаго."]},{"h":"Світилен","ps":["Сли́шана бисть во всіх страна́х превели́кая сла́ва твоя́, і тогда́ жени́ Моави́тськия страша́ху ді́ти своя́ гро́зним твої́м і́менем. І ни́ні, блаже́нне, враги́ на́ша неви́димо устраша́й, ополча́ющіяся на христолюби́воє твоє́ во́їнство.","Слава, і нині, Богородичен: Сові́та вели́каго А́нгела О́тча, родила́ єси́ Христа́, препі́тая Отрокови́це, Царя́ сла́ви: Єго́же Крест, апо́столи пропові́давше, просвіти́ша язи́ки і научи́ша Тя, Богоро́дицю, сла́вити і покланя́тися Твоєму́ Рождеству́."]}],"notes":[]},{"u":"Канон святій блаженній Ксенії Петербурзькій","e":"Canon to the Holy Blessed Xenia of Petersburg","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д я́ко су́шу, і єги́петськаго зла ізбіжа́в ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Водо́ю креще́нія оми́вшися, перворо́днаго гріха́ ізба́вилась єси́, ма́ти Ксе́ніє, і на́ша сердця́ слеза́ми покая́нія очи́сти, просвіще́ніє подаю́щи почита́ющим святу́ю па́м'ять твою́.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Во воді́ креще́нія змі́я лука́ва потопи́вшая, житіє́м твої́м страда́льчеським вра́жию си́лу умертви́ла єси́, блаже́нная, от нея́же і нам ізба́витися Спа́са умоли́.","Во́ду живу́ю неістощи́мих даро́в подаде́ тебі́ Христо́с, блаже́нная ма́ти, Єго́же нищету́ во́льно возлюби́ла єси́.","Богородичен: Во́ди покая́нія пода́ждь мі, Пречи́стая, і, очи́стивши м'я от нечистоти́ гріхо́вния, чи́ста предста́ви, Богороди́тельнице, Си́ну Твоєму́ і Бо́гу."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Небе́снаго кру́га Зижди́телю все житіє́ своє́ отда́вши, возлюби́ла єси́ до конця́, сподо́би і нас моли́твами твої́ми, блаже́нная, люби́ти Го́спода до конця́ дній на́ших.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Небе́сния жи́зні жела́я, в житії́ твоє́м вся земна́я пренебрегла́ єси́, сподо́би і нас, ма́ти Ксе́ніє, моли́твами твої́ми Небе́сния жи́зні дости́гнути.","Небе́снаго черто́га жела́ющи, стра́нничеськоє житіє́ прешла́ єси́, і ни́ні со всі́ми святи́ми в Небе́сних черто́зіх лику́єши.","Богородичен: Небе́снаго Творця́, Богоро́дице всепі́тая, ро́ждши, Небе́с простра́ннійшая яви́лася єси́. Нас от простра́ннаго путі́ поги́бельнаго укло́ньше, на Небе́сний путь наста́ви, мо́лимся."]},{"h":"Сідален, глас 5","ps":["Я́ко стра́нниця во гра́ді свята́го Петра́ яви́лася єси́, благоволе́нієм Бо́жиїм укріпля́єма, ма́ти прему́драя, Боже́ственних даро́в і чуде́с удосто́ївшаяся. Ті́мже, іму́ще дерзнове́ніє ко Христу́ Бо́гу, мир іспроси́ душа́м на́шим і ве́лію ми́лость."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Усли́шавши, Ксе́ніє, я́ко Небеса́ пові́дають сла́ву Бо́жию, отве́ргла єси́ суєту́ мирську́ю і в по́двизі поста́ і лише́нія на землі́ Бо́га сла́вити возжелі́ла єси́, Єго́же сла́вити і нас сподо́би.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Усли́шавши і уразумі́вши діла́ Госпо́дня, просла́вила єси́ Єго́ Божество́, наде́ждою і любо́вію к Нему́ украси́вши ду́шу твою́, по́двигами благоче́стія просвіти́лася єси́, блаже́нная, Бо́жиєю си́лою укрепля́ємая.","Усли́шавши преще́нія вра́жеськия і вся́кия ко́зні от них терп'я́щи, непоколеби́ма пребила́ єси́, і нас непоколеби́мих в доброді́теліх утверди́.","Богородичен: Усли́ши, Пречи́стая Влади́чице, моле́нія на́ша, і ізба́ви нас от наси́лія вра́жия, і глас Христо́в, призива́ющий благослове́нния в Ца́рство, усли́шати сподо́би."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, і ми́шцею Твоє́ю висо́кою Твой мир пода́ждь нам, Человіколю́бче.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Просвіща́хуся ві́рнії лю́діє, зря́ще незло́біє і кро́тость твою́, ма́ти Ксе́ніє, помози́ і нам, блаже́нная, подража́ти твоєму́ незло́бію.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Просвіти́вши стезю́ жи́зні твоєя́ сві́том Богоразу́мія, Христа́ Го́спода вседу́шні возлюби́ла єси́, сподо́би і ни, блаже́нная Ксе́ніє, в сем би́ти тебі́ подража́телі.","Просвіти́ нас, о ма́ти Ксе́ніє, наде́ждою і любо́вію ко Го́споду, ни́ні бо зря́щи Христа́ лице́м к лицю́, сві́та неізрече́ннаго наслажда́єшися, Тому́ за ни моли́ся.","Богородичен: Просвіти́ла єси́ омраче́нноє єстество́, Богоро́дице, Світ І́стинний ро́ждши, ті́мже і нас сві́том просвіти́вши, от мра́чних враг свободи́."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Моли́тву, я́ко істо́чник приснотеку́щий, ни́ні ізлива́єши, неду́жния ісціля́ющи, крі́пость і си́лу стра́ждущим подаю́щи, сподо́би і нас моли́твами твої́ми ізба́витися от вся́ких лю́тих.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Моли́твою небе́сною і по кончи́ні твоє́й от неду́г свобожда́єши, ціли́тельнице безме́здная, досто́йно хвали́ма єси́ на землі́, моли́ся о душа́х на́ших.","Моли́тву на́шу прийми́, ма́ти Ксе́ніє, да в честни́й храм твой при́йдем со тща́нієм, і неду́гов душе́вних і страсте́й тіле́сних ісціле́ніє ско́ро при́ймем.","Богородичен: Моли́твою Твоє́ю Всемо́щною, Пречи́стая, ізба́ви нас от враг ви́димих і неви́димих, от гріхо́в і вся́кия му́ки, я́ко ро́ждшая Человіколю́бця Бо́га."]},{"h":"Кондак, глас 3","ps":["Днесь сві́тло лику́єть град свята́го Петра́, я́ко мно́жество скорб'я́щих обріта́ють утіше́ніє, на твоя́ моли́тви наді́ющеся, Ксе́ніє всеблаже́нная, ти бо єси́ гра́ду сему́ похвало́ і утвержде́ніє."]},{"h":"Ікос","ps":["Ка́ко возмогу́, грі́шний аз, скве́рний душе́ю і ті́лом, пові́дати є́же во пло́ті равноа́нгельноє житіє́ твоє́ і пресла́вная чудеса́? А́ще у́бо мно́зі прему́дрії не дерза́ють іспові́дати мно́гаго твоєго́ терпі́нія і смире́нія і те́плия ко Христу́ любве́, но оба́че наді́яся на твоє́ заступле́ніє, о блаже́нная, вопію́ ті: Ра́дуйся, я́ко везді́ призива́ющих тя ско́ро предваря́єши, ра́дуйся, я́ко мно́жество скорб'я́щих обріта́ють тобо́ю утіше́ніє, ра́дуйся, свята́я блаже́нная Ксе́нія, гра́ду сему́ похвало́ і утвержде́ніє."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","О́троки євре́йськия А́нгел от огня́ неопа́льни сохрани́ і тебі́, Ксе́ніє, в стра́нничестім житії́ укріпи́, пою́щу: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Ді́тем єва́нгльськи подража́ла єси́ в житії́ твоє́м, стезю́ ті́сную проше́дши в незло́бії, ті́мже і нас на по́двиг доброді́телі сія́ укріпи́, пою́щих: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Отроко́м в пещі́ халде́йстій подража́ющи, Ксе́ніє, воспіва́ла єси́ Христа́, да́вшаго ті крі́пость, ті́мже і ми, чту́ще тя, блаже́нная, со дерзнове́нієм зове́м: Благослове́н єси́, Го́споди Бо́же, во ві́ки.","Богородичен: Отрокови́це Ді́во, простри́ на нас ми́лость Си́на Твоєго́, да кромі́шния тьми ізба́вимся мольба́ми Твої́ми, пою́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки."]},{"h":"Пісня 8","ps":["Ірмос: Побіди́телі мучи́теля і пла́мене благода́тію Твоє́ю би́вше, за́повідем Твої́м зіло́ приліжа́ще, о́троци вопія́ху: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Победи́тельниця страсте́й яви́лася єси́, Ксе́ніє, лю́тая іскуше́нія вра́жия побіжда́ющи і непреста́нно пою́щи: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Побіжда́ющи вся́кия стра́сти гріхо́вния, ти, блаже́нная, я́ко сві́тла звізда́ яви́лася єси́, приво́диши бо же́ни, па́дшия во гріхи́, во є́же цілому́дренно жи́ти і в покая́нії воспіва́ти: благослові́те вся діла́ Госпо́дня Го́спода.","Победи́тельниця гріха́ яви́лася єси́, блаже́нная ма́ти, благода́ть Ви́шняго іму́щи. Ті́мже Небе́сная дости́гла єси́, іді́же ни́ні со А́нгели поє́ши: Благослові́те вся діла́ Госпо́дня Го́спода.","Богородичен: Побі́ді во бра́ніх духо́вних ві́рним посо́бствуєши, Пресвята́я Ді́во, ті́мже і лю́дем гра́да на́шего по́мощ Твою́ низпосли́, да Тя ви́ну поє́м: Благослові́те вся діла́ Госпо́дня Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю Тя іспові́дуєм, спасе́ннії Тобо́ю, Ді́во Чи́стая, с безпло́тними ли́ки Тя велича́юще.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Воі́стину ра́зум Христо́в імі́ла єси́, Ксе́ніє, смире́ніє, кро́тость, ві́ру несумне́нну, наде́жду і любо́в, я́же к Бо́гу, і нас сподо́би, да с тобо́ю Христа́ при́сно велича́єм.","Приспів: Свята́я блаже́нная ма́ти на́ша Ксе́ніє, моли́ Бо́га о нас!","Воі́стину на тебі́, Ксе́ніє блаже́нная, іспо́лнися Христо́во прорече́ніє: претерпі́вий до конця́, той спасе́н бу́деть, ни́ні бо со всі́ми спасе́нними Христа́ при́сно велича́єши.","Воі́стину нікто́же, притека́яй к тебі́, блаже́нная ма́ти, тощ благода́ті Бо́жия отхо́дить, єя́же і нас іспо́лни, да тя велича́єм.","Богородичен: Воі́стину Богоро́дицю Тя, Ді́во і Ма́ти Сло́ва, Хода́таїцю су́щую нам, Со́лнце Пра́вди возсія́вшую, ві́рнії, єдиному́дренно пі́сньми велича́єм."]},{"h":"Світилен","ps":["Я́коже со́лнце світоно́сно, возсія́ ни́ні, блаже́нная ма́ти, па́м'ять твоя́, вся ві́рния веселя́щи, і́же моли́твенно взива́ють ті: моли́ся прилі́жно спасти́ся нам."]},{"h":"Молитва","ps":["О свята́я всеблаже́нная ма́ти на́ша Ксе́нія! Оби́ди, поноше́нія і насме́шки Христа́ ра́ди претерпі́вшая, і за му́жа твоєго́, без христия́нськаго напу́тствія сконча́вшагося, непреста́нно моли́вшаяся. Виждь тісноту́ душі́ моєя́ і скорб о уме́рших без покая́нія і причаще́нія Святи́х Та́їн сро́дниках і зна́ємих мої́х (імена́), і умоли́ да́нною тебі́ благода́тію Человіколюби́ваго Влади́ку Христа́ Бо́га на́шего, да прости́ть їм вся согріше́нія во́льная і нево́льная, із глуби́н а́дових да ізведе́ть їх, от муче́ній лю́тих ізба́вить і мно́жеством милосе́рдія Своєго́ ко ізбра́нним Свої́м сопричте́ть їх, іді́же ти ни́ні в незаходи́мій сія́єши сла́ві, воспіва́я премилосе́рдаго Творця́ во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон святим Апостолам","e":"Canon to the Holy Apostles","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну, невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́знима Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Боже́ственнії Уті́шителя орга́ни, возглаша́ющії Сего́ Боже́ственними всегда́ дохнове́ньми, воспі́ша піснь нам, я́ко воі́стину спаси́тельную, благосла́внії Христо́ви апо́столи.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","На одрі́ лі́ності слежа́ща і в сме́рті гріхо́вній неду́гом душе́вним лю́ті іста́єма, посіще́нія м'я, сла́внії Христо́ви самови́дці, сподо́біте.","І́же сло́вом безслове́сіє разріши́вше язи́ков, апо́столи, от безслове́сних дія́ній лю́ті омраче́нноє се́рдце моє́, Уті́шителя благода́тію просвіті́те, апо́столи.","Богородичен: Ді́ва по рождестві́ нетлі́нна пребила́ єси́, нас ра́ди я́вльшагося на землі́, па́че сло́ва ро́ждшая: Єго́же прилі́жно моли́, просвіти́ти ду́ші на́ша."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Град Твой, Бо́же, слове́сних рек Твої́х тече́нія учени́к, Влади́ко, свяще́нно возвеселя́ють.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Гра́ждане Небе́снії, сослуже́бници ми́сленним чино́м, всесла́внії апо́столи, вся́кия нас ско́рби ізба́віте.","Утверди́вий, Христе́, слове́сная Твоя́ небеса́, утверди́ м'я тіх моли́твами на ка́мені Твої́х хоті́ній, я́ко благоутро́бен.","Богородичен: Я́ко Ма́ти Тя мо́лить с ли́ком учени́к, Го́споди, я́же Тебі́ чи́сто Роди́вшая: да́руй нам ми́лості Твоя́."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Наве́л єси́ на мо́ре ко́ни Твоя́ ізбра́нния, Человіколю́бче, злові́рія во́ди возмуща́ющия і всім ра́зум Твой і́стинний возвіща́ющия.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Зві́зди просвіти́вше благоче́стієм ми́сленную твердь церко́вную, сла́внії апо́столи, от но́щі неві́дінія і прегріше́ній ізба́віте м'я.","Я́вльшеся я́коже стрі́ли ізощре́ни, апо́столи, вра́жия разжже́нния стрі́ли, зло́би моєя́ ни́ні угасі́те, і помишле́ніє моє́ утверді́те.","Богородичен: Ду́шу мою́, огорче́нную я́дом, сопроти́внаго угризе́нієм, ді́йственним врачева́нієм ісціли́, моли́твами, Христе́, Ро́ждшия Тя і свяще́нних апо́стол Твої́х."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди мой, світ в мир прише́л єси́, світ святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Лози́ живо́тния процвіта́юща гро́здіє, напоі́ша всіх вино́м ми́сленнаго весе́лія, сла́внії апо́столи.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Ко сві́ту за́повідей Бо́жиїх наста́віте, апо́столи, і́же во тьмі душе́внаго уни́нія безу́мно пребива́ющия.","Ізба́віте нас душе́вних прегріше́ній, і Суда́ бу́дущаго, і тлі, і бід, апо́столи блаже́ннії.","Богородичен: Спаси́ м'я, Бо́же, я́ко человіколю́бець, спаси́ м'я мольба́ми неізрече́нно Тебі́ Роди́вшия, і всіх Боже́ственних апо́стол Твої́х."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Па́стиря до́браго богоізбра́нная овча́та, разсі́янная по ми́ру, волко́во вся́ко зві́рство во о́вчую кро́тость ві́рою преложи́ша.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Боже́ственнаго рая́ древеса́ добропло́дная, преокая́нния душі́ моєя́ всенепло́дство во благопло́діє доброді́тельнаго нра́ва преведі́те, апо́столи.","Уя́звен бих сласте́й ору́жієм і умро́х: і́же от Христа́ приє́мши, сла́внії, благода́ть воскреша́ти ме́ртвия, умерщвле́нную окая́нную мою́ ду́шу оживі́те.","Богородичен: Утоли́ душі́ моєя́ свирі́пую бу́рю, Бо́же всіх ще́дрий, мольба́ми ро́ждшия Тя Богоро́диці, апо́стол же і му́ченик Твої́х."]},{"h":"Кондак, глас 2","ps":["Тве́рдия і Боговіща́нния пропові́дателі, верх учени́к Твої́х, Го́споди, прия́л єси́ в наслажде́ніє благи́х Твої́х і поко́й: болі́зні бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, Єди́не сві́дий серде́чная."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ Авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че не́жели пла́менем опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Крі́постію всесвяти́я про́повіді, неле́стнії апо́столи Христо́ви, пре́лести зи́му разруши́сте і просвіти́сте богоразу́мієм ві́рних мудрова́ніє.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Ми́ро благоуха́нноє істоча́юще всегда́, Боже́ственнії ученици́, ми́ра у́мнаго благово́нія притека́ющих к вам іспо́лніте і злосмра́дния стра́сті отжені́те.","Растлі́вшаго м'я плотськи́ми безмі́стії, Сло́ва нетлі́ннаго сла́внії ученици́, спасі́те м'я пою́ща: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Богородичен: Лик а́нгельський, лик му́ченик і апо́стол Твої́х, Сло́ве, мо́лять всегда́ мно́гоє благоутро́біє Твоє́, Человіколю́бче: всіх уще́дри Богоро́дицею, я́ко благоутро́бен."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р Данії́л, львов зія́нія в ро́ві затче́: о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Уста́ огнедохнове́нная Христо́ва, і́же бездве́рная уста́ загради́вше і спаси́тельноє пропові́даніє повсю́ду разсі́явше, от уст во́лка ми́сленнаго ізба́висте вопію́щия: вся діла́, Го́спода по́йте і превозносі́те Єго́ во вся ві́ки.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Вострубі́те о́крест моєя́ умерщвле́нния душі́, благогла́сния тру́би Христо́ви, апо́столи сла́внії, і от гро́ба отча́янія і уни́нія лю́таго сію́ воздви́гніте, во є́же пі́ти: вся діла́, Го́спода по́йте і превозносі́те Єго́ во вся ві́ки.","Мене́, зако́ни Твоя́, Христе́, попра́вшаго ума́ развраще́нієм, мене́, Влади́ко, блу́днаго, во глубину́ попо́лзшася і оби́чаю лука́вому при́сно рабо́тающа, не пре́зри ученико́в Твої́х мольба́ми.","Богородичен: Марі́є, Госпоже́ вся́чеських, облада́єма м'я от змі́я і согріша́юща всегда́, свободи́ моли́твами Твої́ми, і порабо́ти Христу́, в житії́ чи́сті воспіва́ти: вся діла́, Го́спода по́йте і превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́ Тебі́, Ді́во, краєуго́льний отсіче́ся, Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Ка́меніє ізбра́нноє положе́ннаго во главу́ у́гла ка́мене, созда́сте всіх ві́рних сердця́, ка́менем ві́ри вра́жия созда́нія, апо́столи, разве́ргше.","Приспів: Святі́ї апо́столи, молі́те Бо́га о нас.","Ріши́ти і в'яза́ти от Христа́ приє́мше власть, разріші́те зол мої́х соу́з, і к любві́ Бо́жієй прив'яжі́те, і Ца́рствія прича́стника Боже́ственнаго соді́лайте, апо́столи.","Боже́ственнії Влади́ки о́блаці, ізсо́хшеє моє́ се́рдце вся́ким лука́вим дія́нієм, Боже́ственними ту́чами ни́ні напо́йте і плодоно́сно покажі́те, апо́столи богоблаже́ннії.","Богородичен: Со святи́ми А́нгели, с Боже́ственними апо́столи, со сла́вними му́ченики, Твоєго́ моли́ Си́на і Бо́га, Богороди́тельнице Пречи́стая, от бід ізба́вити ду́ші на́ша."]},{"h":"Молитва","ps":["Влади́ко Го́споди, Твой єсть день і Твоя́ єсть нощ, Тебі́ вся твар рабо́таєть, і вся́коє диха́ніє сла́вить Тя. Аз же, окая́нний, все житіє́ моє́ сконча́в блу́дно, стра́хом одержи́м єсьм, я́ко пом'яну́х дні пе́рвия, і до ни́ні, в ня́же вся нечу́вственная сотвори́х зла́я. І того́ ра́ди не і́мам к Тебі́ дерзнове́нія, я́ко беззако́нія моя́ велика́, і безмі́рни гріси́ мої́, вразі́ же всегда́ стужа́ють мі. Но, Го́споди мой, Го́споди, отве́рзий устні́ німо́му, і моя́ уста́ отве́рзи, да глаго́лю в моли́тві уго́дная Тебі́, се бо душа́ моя́ я́ко земля́ безво́дная оста́, і не мо́жеть приноси́ти от себе́ плода́. Но даждь мі от сі́мене Свята́го Твоєго́ Ду́ха, і напої́ м'я росо́ю благода́ті Твоєя́, да принесу́ Тебі́ плод покая́нія. Го́споди Ісу́се Христе́, хотя́й всім челові́ком спасти́ся, усли́ши моли́тву мою́, моли́твами святи́х апо́стол Твої́х, я́ко ті́ї мо́ляться за ни, і аз ті́ми у Тебе́ прошу́ проще́нія, я́ко тіх моли́тви при́сно послу́шаєши; моле́нієм їх спаси́ м'я, грі́шнаго, ісціли́ болі́зні се́рдця моєго́, уврачу́й стру́пи душі́ моєя́, разжжи́ утро́би моя́; пла́мень стра́ха Твоєго́ да поя́сть те́рніє гріхо́в мої́х, і ду́шу мою́ любо́вію прохлади́, к Тебі́ бо жела́ю і́стинному Сві́ту, і Пода́телю сві́та, у Тебе́ Єди́наго прошу́ ми́лости: спаси́ м'я, наси́ти а́лчущую і напої́ жа́ждущую ду́шу мою́, от пото́ка безчи́сленнаго милосе́рдія Твоєго́, покри́й м'я благода́тію Твоєго́ человіколю́бія от вся́каго зла, да Тобо́ю храни́м ізба́влюся мно́гих сіте́й лука́ваго, по вся дні на м'я пропина́ємих, і да не похва́ляться вразі́ мої́ о мні, рабі́ Твоє́м, упова́ющем на Тя, і спаси́ м'я по ми́лості Твоє́й. Да возда́м обі́ти моя́, до послі́дняго іздиха́нія ка́яйся о свої́х согріше́ніях, і просла́влю пресвя́тоє і́м'я Твоє́, со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон святителю Тихону, єпископу Воронезькому, Задонському чудотворцю","e":"Canon to St Tikhon, Bishop of Voronezh, Wonderworker of Zadonsk","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Святи́телю Христо́в Ти́хоне! Сам да́руй мі ум і язи́к, да воспою́ по достоя́нію сла́ву, є́юже сла́вно просла́ви тя Христо́с Госпо́дь.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Луча́ боже́ственнаго сві́та возсія́ нам, прийді́те, ча́да сві́та, да озарі́мся є́ю, да возгорі́мся ду́хом, пі́сньми святи́теля велича́юще.","Апо́столов преє́мника, святи́телей сопресто́льника, преподо́бних сожи́теля, просла́вим блаже́ннаго Ти́хона, єго́же предста́тельством спасе́ніє улуча́єм.","Богородичен: Воплоти́вся неізрече́нно Влади́ка всіх із Тебе́, Богороди́тельнице Марі́є, соверше́н бисть Челові́к, і роди́вся, я́коже пре́жде рождества́, сохрани́ Тя чи́сту, Єго́же моли́ спасти́ от бід ду́ші на́ша."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, єди́не Человіколю́бче.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Любо́вію Христо́вою уязви́вся, блаже́нне, Тому́ от ю́ности невозвра́тним жела́нієм послі́довал єси́, вся́коє плотсько́є наслажде́ніє возненави́дів.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Ю́ношеськия стра́сті, плоть том'я́щия, любому́дрія мече́м посі́кл єси́, же́ртву себі́ Влади́ці Христу́ принося́.","Стра́хом Госпо́днім утвержда́єм, нача́ло бо прему́дрости сей єсть, любо́вію лу́чшею приліпи́лся єси́ прему́дрости, о Ти́хоне.","Богородичен: Воспої́м боже́ственний храм Бо́жий, ублажи́м Святу́ю Ді́ву, обоже́ні би́вше Є́ю і от бід ізбавля́ємі."]},{"h":"Сідален, глас 8","ps":["Храм Свята́го Ду́ха от ю́ности бил єси́: Уті́шителева бо благода́ть, по ві́рі твоє́й очи́стивши ду́шу твою́ от страсте́й, я́ві в ней вселя́ється, сего́ ра́ди і по преставле́нії соблюде́ся ті́ло твоє́ нетлі́нно. Моли́ Христа́ Бо́га, от тлітво́рних страсте́й ізба́витися чту́щим любо́вію па́м'ять твою́.","Богородичен: Ма́ти сла́дкаго мі Ісу́са, Чи́стая Богоотрокови́це, прия́телище Ду́ха Свята́го, очи́сти мою́ ду́шу, беззако́нії оскверне́нную, і сві́тлоє жили́ще доброді́телей соді́лай, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й, да і мене́ Твої́ми моли́твами осіни́ть Уті́шителева благода́ть."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Я́ко овча́, от Христа́ упа́слся єси́, я́коже па́стир, упа́сл єси́ ста́до, ізводя́ на па́жити живоно́сних твої́х уче́ній.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Таї́нник бив Христо́ва уче́нія, Сего́ ві́дінієм просвіти́л єси́ лю́ди, ді́ли і словеси́ явля́я і́стину Єго́.","І́стинен і ві́рен страж до́му Бо́жия бил єси́, стрегі́й єго́ ді́лом, я́ко о́браз явля́я житіє́м, сло́вом, я́ко уча́ усе́рдно, помишле́нієм, я́ко пеки́йся о бла́зі Єго́.","Богородичен: Тя приста́нище, і сті́ну, і прибі́жище, і наде́жду, і покро́в, і предста́тельницю те́плую обрі́тше, ві́рнії, к Тебі́ прибіга́єм і вопіє́м прилі́жно, я́коже научи́ нас взива́ти к Тебі́ блаже́нний Ти́хон: Пресвята́я Богоро́дице, спаси́ нас."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Єго́же возлюби́л єси́, Єго́же возжелі́л єси́, Єго́же ра́ди подвиза́лся єси́, святи́телю, моли́ ни́ні Христа́ о рабі́х, да ми́лостив бив, всім нам ми́рноє состоя́ніє да́руєть, почита́ющим па́м'ять твою́.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Любо́вію і ві́рою Христо́вою іспо́лнен сий, яви́лся єси́ я́ко ріка́, оби́льно всю зе́млю Українськую напоя́я сло́вом уче́нія, блаже́нне Ти́хоне.","Я́ко пчела́ сла́дкий мед от цвіто́в, ско́ро ув'яда́ющих, собра́л єси́, о́тче, от тлі́ннаго ми́ра духо́вноє сокро́вище, і́мже всіх нас услажда́єши.","Богородичен: Іспо́лни весе́лія се́рдце на́ше, Пречи́стая Богоотрокови́це, весе́лія ро́ждшая Вино́внаго, гріхо́вную печа́ль вся́кую потребля́ющи."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся, к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Чист бив се́рдцем, чи́стому Христу́ приліпи́лся єси́, святи́й Свято́му, люби́тель Люби́тельному, кро́ткий Кро́ткому, взива́я непреста́нно: мні приліпля́тися Бо́гові бла́го єсть.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Уті́ху, ро́скош, честь, бога́тство, сла́ву і все сокро́вище ми́ра презрі́л єси́, воспаря́я ко Го́рнему Ієрусали́му, к до́му Отця́ Небе́снаго, іді́же оби́телі мно́гі суть.","Доса́ди, ско́рби, оби́ди ра́достно терпі́л єси́, помишля́я, я́ко віне́ць без побі́ди, побі́да без по́двига, по́двиг без бра́ні, брань без враго́в не бива́єть.","Богородичен: О, Ді́во Госпоже́, Ма́ти Зижди́телева! Небе́сних єси́ чино́в ра́дованіє і челові́чеському ро́ду благослове́нная Помо́щниця, моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Апо́столов преє́мниче, святи́телей украше́ніє, Правосла́вния Це́ркве учи́телю, Влади́ці всіх моли́ся, мир вселе́нній дарова́ти і душа́м на́шим ве́лію ми́лость."]},{"h":"Ікос","ps":["Ду́шу твою́ украси́в доброді́телію, ум просвіти́в любому́дрієм, па́стир до́брий яви́лся єси́ ста́ду Христо́ву, сло́вом і писа́нієм уча́, наказу́я і вразумля́я, житіє́м свої́м о́браз слове́с явля́я, ті́мже на небесі́ вінце́м сла́ви украси́лся єси́ от Пастиренача́льника Христа́, на землі́ сія́я нетлі́нієм моще́й і істоча́я оби́льния то́ки чуде́с ві́рою призива́ющим тя, досточу́дне і богому́дре Ти́хоне. Моли́ся ко Го́споду дарова́ти душа́м на́шим ве́лію ми́лость."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снизхожде́нія огнь устиді́ся во Вавило́ні іногда́, сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Терпі́нієм стяжа́л єси́ ду́шу твою́, блаже́нне, путе́м ті́сним, єди́ним веду́щим в жизнь ві́чную, шел єси́, ви́ну взира́я на кре́стний путь Подвигополо́жника Христа́ і Сего́ о́браз житію́ твоєму́ полага́я.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Всего́ себе́ любві́ Бо́жієй пре́дал єси́, ду́шу і ті́ло, се́рдце і ра́зум, па́м'ять і во́лю, намі́реніє, начина́ніє, сло́во, ді́ло і помишле́ніє Бо́гу в любо́в посвяти́л єси́.","Оте́ць сиро́т, і вдов защи́тник, і бога́тство ни́щих, боля́щих утіше́ніє, і су́щих в бога́тстві наста́вник, ста́рости жезл, і наказа́ніє ю́ности, і мона́шествующим доброді́телей пра́вило яви́лся єси́, блаже́нне Ти́хоне.","Богородичен: Ра́дуйся, Марі́є, ра́дуйся, Спаси́теля ми́ру ро́ждшая, приста́нище бу́ди нам, жите́йською бу́рею волну́ємим, і оти́шіє в пучи́ні скорбе́й, і води́тельство к небе́сним селе́нієм."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель, Богочесті́вим неі́стовно разжже́; си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Ца́рствія небе́снаго єще́ на землі́ син бив, ви́ну воздиха́л єси́ к Си́ну Бо́жию, вопія́ Єму́: бу́ди мі пи́ща і питіє́, бу́ди світ душі́ моєя́, бу́ди отра́да в ско́рбі, бу́ди жизнь ві́чная по воскресе́нії, да превозношу́ Тя во ві́ки.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Ада́ма паде́ніє, Христо́вими страстьми́ іскупле́ніє, час сме́ртний, Стра́шний суд, муче́нія грі́шних, блаже́нство пра́ведних всегда́ помишля́я, рида́л єси́, нам умиле́нія о́браз показу́я, себе́ же предочища́я к бу́дущей сла́ві.","Труди́ по ві́рі і благоче́стію под'є́м в жи́зні сей, сла́дці по труді́х почи́л і упоко́їлся єси́: соше́л бо єси́ во гроб, я́ко пшени́ця, для жи́тници Бо́жия созрі́лая, во вре́м'я пожа́тая.","Богородичен: Іссо́пом Животворя́щия Кро́ве за спасе́ніє ми́ра закла́ннаго А́гнця, із Твої́х пречи́стих крове́й плоть приє́мшаго, окропи́ м'я, оскверне́ннаго, Влади́чице, і очи́сти м'я, да Твої́м ма́тернім заступле́нієм па́че сні́га убілю́ся."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","Хода́тай яви́лся єси́ і моли́твенник те́плий о нас к Бо́гу, святи́телю. Ми́лостива у́бо моли́твами твої́ми соді́лай Влади́ку, іспроси́, о́тче, прегріше́ній оставле́ніє, ві́рою свяще́нную па́м'ять твою́ пра́зднующим і серде́чною любо́вію тя велича́ющим.","Приспів: Святи́телю, о́тче Ти́хоне, моли́ Бо́га о нас.","От Бо́га Сві́та небе́сним сві́том осія́нний, просвіти́ нас, помраче́нних страстьми́ жите́йськими, ріши́ти же і в'яза́ти власть от Него́ приє́мий, разріши́ прегріше́нія на́ша, і Ца́рствія небе́снаго сподо́би па́м'ять твою́ пра́зднующих і досто́йно тя велича́ющих.","На́ше хвале́ніє сіє́, от недосто́йния і окая́нния душі́, от усе́рдія же бога́таго приноси́моє тебі́, прийми́ ми́лостивно, святи́телю, благода́ть проти́ву воздая́ нам щедрооби́льную.","Богородичен: Ада́ма па́дшаго возста́вила єси́, Богома́ти, ро́ждши Но́ваго Ада́ма, возста́ви і нас, па́дших по подо́бію дре́вняго, но благода́ті Но́ваго те́плі ві́рующих."]},{"h":"Світилен","ps":["Пло́тію а́ще і почи́л єси́, святи́телю Ти́хоне, но ду́хом жив сий, в Ца́рствії невече́рнім со Христо́м ца́рствуєши, і мо́лишися Єму́ о призива́ющих тя ві́рою і любо́вію."]},{"h":"Інший світилен","ps":["В черто́зі Жениха́ Христа́ помишля́я тя, святи́телю, неізрече́нним сві́том сія́юща, Ца́рствія небе́снаго приобщи́тися жела́ю, но от сна гріхо́внаго об'юроде́ мой ум, угасе́ світи́льник, я́ко без'єле́єн, і душі́ моєя́ оскверне́на єсть оде́жда, і ви́жду две́рі Ца́рствія мні заключе́нния, но твої́ми моли́твами возбуди́в м'я от сна гріхо́внаго, єле́й покая́нія мі да́руй, і ри́зою заслу́г Христо́вих прикри́в мою́ наготу́, досто́йна м'я сотвори́ невече́рняго Ца́рствія."]}],"notes":[]},{"u":"Канон преподобному Олексію, чоловікові Божому","e":"Canon to St Alexis, the Man of God","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Тісні́йший ше́ствовал єси́ путь, непоро́чноє і преподо́бноє житіє́, му́дре, проходя́ от ю́ности, ті́мже мою́ тісноту́ разшири́ ума́, восхвали́ти тя, в ра́йстій широті́ водворя́яся, Алексі́є.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Тебі́ сама́го весьма́ Бо́гу возложи́в, блаже́нне, вні пло́ті і ми́ра бил єси́, бога́тству теку́щу небе́сноє предпоче́л єси́ і пребива́ющеє і обіща́нний град Сіо́н ві́чнующий.","Ложе́сн ти ма́терніх непло́діє разріши́л єси́, ро́ждся, я́коже Самуї́л, пребога́те, во чре́ві же се́рдця чи́стий заче́н страх, роди́л єси́ дух спасе́нія Боже́ственних доброді́телей ві́рою.","Богородичен: Бо́жий Собезнача́льний Син імі́ я́ко вино́вну Тя к нам, Ді́во, подо́бія, єди́ну, па́че всея́ тва́рі, Чи́стая, чи́сту Тя обрі́т. Тім Тя поє́м, всі ро́ди, і ублажа́єм."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня я́ко крин Го́споди, язи́чеськая неплодя́щая це́рков, прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Пронза́єм жела́нієм чистоти́, черто́гом, і́же на землі́, небе́сний преміни́л єси́ і жени́ любо́вію сладча́йшеє а́нгельськоє подо́біє.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Молви́ жите́йськія і тя́жесть бога́тства оста́вил єси́ і пресе́льник бив оте́чества, блаже́нне Алексі́є, Христо́ві нищеті́ подо́б'яся.","Слеза́ми, і болі́зньми, і воздержа́нієм, всему́дре, благо́є взиска́л єси́, когда́ при́йдеть світ ра́зума, безстра́стіє дая́ се́рдцю твоєму́.","Богородичен: Го́ре неви́димий а́нгелом, Чи́стая, до́лі із Тебе́ ражда́єм, зри́ться соверше́н Челові́к, погиба́ющий мир обновля́я."]},{"h":"Сідален, глас 3","ps":["Ми́ра красоту́, преподо́бне, оста́вил єси́, преміни́в бога́тством теку́щим непроходи́моє я́ві і пребива́ющеє, Алексі́є. Ті́мже со всі́ми тя святи́ми сла́вим і торжеству́єм сві́тло в па́м'яті твоє́й, прося́ще обрісти́ моли́твами твої́ми, блаже́нне, ве́лію ми́лость.","Слава, і нині, Богородичен: Недоми́сленно і непости́жно єсть, Влади́чице Богора́дованная, є́же соді́ланноє о Тебі́ стра́шноє Бо́жиє та́їнство, і́бо Необиме́ннаго, заче́нши, родила́ єси́, пло́тію обложе́на от пречи́стих крове́й Твої́х. Єго́же всегда́, Чи́стая, я́ко Си́на Твоєго́ моли́ спасти́ся душа́м на́шим.","Хрестобогородичен: Неіскусобра́чная Чи́стая і Ма́ти Твоя́, Христе́, ви́дящи Тя, ме́ртва ви́сяща на Кресті́, ма́терськи пла́чущи, глаго́лаше: что Тебі́ воздаде́ євре́йський беззако́нний собо́р і неблагода́рний, і́же мно́гих і вели́ких Твої́х, Си́не Мой, даро́в наслади́вийся? Пою́ Твоє́ Боже́ственноє снизхожде́ніє."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви не хода́тай, ні а́нгел, но Сам Го́споди вопло́щся, і спасл єси́ всего́ м'я челові́ка; тім зову́ ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Претерпі́л єси́ нищету́, проси́тель бив, нищ, я́коже Ла́зар, жела́ніє бо Боже́ственноє утіша́ше, блаже́нне, се́рдце твоє́, пожела́вшеє бога́тства небе́снаго.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Безпеча́льнаго і ти́хаго житія́ возжела́л єси́, єди́нощі яди́й в седьми́ці, Алексі́є, жела́нієм ожида́ющаго тя не мимотеку́щаго, всеблаже́нне, наслажде́нія.","Храм Бо́гу се́рдце іща́й соді́лати, в дому́ возлюби́л єси́ Богома́тере, сла́вне, всегда́ сіді́ти і небе́сния добро́ти созира́ти.","Богородичен: Воздої́вши Да́теля, Ді́во, млека́, а́лчущеє і утісня́ємоє ни́ні се́рдце моє́ наси́ти вся́каго ра́зума і умиле́нія Боже́ственнаго, молю́ Тя."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо Влади́ко, к світонача́льнику Отцю́ Твоєму́, от но́щі неві́дінія, приведе́ніє і́мами.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","То́ки свяще́нними напая́я всегда́ слез твою́ ду́шу, соді́лал єси́ клас, воі́стину стори́чествующ, Ді́лателю Безсме́ртному до́брі соблюда́єм.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Ви́дін бил єси́ на землі́, житіє́ безпло́тних подража́я, премно́гим твої́м, о́тче, воздержа́нієм, досточу́дне, і в моли́твах приліжа́нієм, і́мже, я́ко сві́том, просвіти́лся єси́.","Огне́м моли́тв гріха́ попали́л єси́ вещ, му́дре, бді́нними же стоя́ньми вся́коє сладостра́стіє успи́л єси́, усну́в же, к сія́нію преста́вился єси́ невече́рнему.","Богородичен: І́же, во Сві́ті живи́й, во свято́є чре́во Твоє́ всели́ся, Чи́стая, мир, поги́бший тьмо́ю неразу́мія, па́ки назида́я, Єго́же моли́ вся просвіти́ти, пою́щия Тя."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же м'я возведи́.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Я́ко храм жив Бо́жий, тя, би́вша Христо́во селе́ніє, Неіскусобра́чная проявля́єть кри́ющася і прославля́єть утаї́тися тща́щагося.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Моли́тви твоя́ Бо́гу, я́ко кади́ло, блаже́нне, прия́тни би́ша, отсю́ду житіє́м твої́м ві́рних ра́зуми облагово́нил єси́ Ду́ха благода́тію.","Свяще́нним житіє́м украша́єма, па́ки Христо́с не хотя́ща, сла́вне, тя оте́честву дає́ть, отбіга́юща сла́ви привре́менния.","Богородичен: Зако́ни єстества́, Чи́стая Влади́чице, Зижди́тель, новосоді́лавий созда́нія, із Тебе́ неізрече́нно ражда́ється і обожа́єть м'я безмі́рною ми́лостію."]},{"h":"Кондак, глас 2","ps":["Дом роди́телей твої́х, я́ко чуждь, імі́в, водвори́лся єси́ в нем нищеобра́зно і, по преставле́нії віне́ць приє́м сла́ви, ди́вен на землі́ яви́лся єси́, Алексі́є, челові́че Бо́жий, а́нгелом і челові́ком ра́дованіє."]},{"h":"Ікос","ps":["Житіє́м і словеси́ украси́лся єси́ і Христо́ву Це́рков возвели́чил єси́ твої́м житіє́м, отця́ і ма́тер, царя́ і лю́ди торжествова́ти устро́їв, ді́ли же соблю́д, є́же по о́бразу Бо́жию, Алексі́є преподо́бне, возсія́л єси́ в ми́рі твої́м цілому́дрієм. Ті́мже благода́ть доброді́телей твої́х облистава́єть вся, ві́рою пра́зднующия, о́тче, па́м'ять твою́, яви́л бо ся єси́ а́нгелом і челові́ком ра́дованіє."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий Благослове́н і Препросла́влен.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Претерпі́л єси́, преподо́бне, пред роди́тельними врати́ сідя́, і весьма́ непознава́єм, і от о́трок руга́нія под'є́мля, і наруга́єм лю́ті, і нището́ю мно́гою оскорбля́єм.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Пло́ті твоєя́ мудрова́ніє умертви́в, зря роди́телі, і си́ми непознава́єм, єстества́ покрива́л єси́ ну́жду, преподо́бне, і презрі́ніє твої́х неіску́сних о́трок, оскорбля́ющих тя.","О, чудесе́! Ка́ко преби́л єси́, при́сно ни́щетствуя, в бога́тстві, Алексі́є, безмі́рнаго смире́нія? Ка́ко претерпі́л єси́ руга́нія і укори́зни от о́трок, прему́дре, твої́х, не ві́дівших житія́ твоєго́?","Богородичен: Вели́каго служи́тельниця Ти та́їнства била́ єси́, Всенепоро́чная: Бо́га бо воплоти́ла єси́, вели́ких зол нас ізба́вльшаго, Тя велича́ющия, Чи́стая Благослове́нная, Богора́дованная."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Неві́дом пре́жде роди́телем сий, во вре́м'я отше́ствія твоєго́ сим та́йну открива́єши, явля́єм в сла́ву Бо́га на́шего, сла́вне, вельми́ тя і досто́йні просла́вльшаго.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Госпо́дь гла́сом ве́ліїм явля́єть тя всему́ Ри́му, сокрове́нноє сокро́вище, пребога́те, в ни́щетні о́бразе лежа́ща і да́ри врачева́ній вся, ві́рою к тебі́ приходя́щия, обогаща́юща.","Кня́зі лю́дстії, і ца́ріє снидо́шася, і свяще́нници, блаже́нне, погребсти́ тя Бо́жиїм манове́нієм і, ви́дяще ве́ліє виді́ніє, диви́шася чудесе́м, преподо́бне, я́же твори́л єси́ Боже́ственною си́лою Ду́ха.","Богородичен: Істле́вшия ни дре́вле преступле́нієм обновля́я, Человіколю́бець нетлі́нно воплоти́ся от нетлі́нния Твоєя́, Всенепоро́чная, утро́би і ізба́ви всіх гріхо́вния тлі, Богоневі́стная."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Ісціле́нія істочи́л єси́, ко гро́бу несо́м, Бо́гу тя, блаже́нне, вельми́ сла́в'ящу: світ бо неви́дящії ви́діша і глаго́ланіє прия́ша пре́жде су́ще німі́ї, всесла́вне Алексі́є.","Приспів: Преподо́бне о́тче Алексі́є, моли́ Бо́га о нас.","Ви́дін бил єси́, предлежа́щ і к погребе́нію несо́м, я́ко со́лнце, о́тче, іспуща́я ісціле́ній зари́ пресла́вно, і те́мния стра́сті отгоня́, і опаля́я де́мони, і просвіща́я богому́дрия.","Приї́де погребсти́ тя патріа́рхов пе́рвійший, цар же, вельми́ христолюби́війший, кня́зі, ста́рці і ю́нії і мона́шествующих ли́ци, Боже́ственним манове́нієм освяща́ющеся прикоснове́нієм твої́м, блаже́нне.","Восхище́н бил єси́, на колесни́ці доброді́телей несо́м, і почива́єши, іді́же преподо́бних чи́ни, собо́р апо́стол і му́чеников, патріа́рхов і всіх пра́ведник, с ни́миже нас пом'яни́, почита́ющия тя, Алексі́є.","Богородичен: Глас Тебі́ прино́сим Гавриї́лов, Всенепоро́чная: ра́дуйся, глаго́люще, ни́во неді́ланная; ра́дуйся, кля́тви разріше́ніє; ра́дуйся, істо́чниче води́ живо́тния, преподо́бних похвало́, Богоро́дице Присноді́во."]}],"notes":[]},{"u":"Канон святим мученикам Адріану і Наталії","e":"Canon to the Holy Martyrs Adrian and Natalia","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","В нощі́ м'я житія́, сном лю́тим одержи́ма дія́ній, к сві́ту покая́нія, Бо́же, воздви́гни моли́твами му́ченик Твої́х, Христе́, да сла́влю Тя.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Восто́ком ми́сленнаго со́лнця озари́вшеся му́ченици і дне си́нове би́вше, всю і́дольськую мглу крі́пко потреби́сте.","От усте́н, іска́пающих сла́дости Боже́ственнаго ра́зума, наслади́вся, Адрія́не, яд ізблева́л єси́ пре́жняго неразу́мія, воі́стину, богоблаже́нне.","Богородичен: Твоєго́ приє́мши Соді́теля, я́ко Сам восхоті́, от безсі́менна Твоєго́ чре́ва, па́че ума́ воплоща́єма, Чи́стая, тва́рі воі́стину яви́лася єси́ Влади́чиця."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Уз ізбіжа́в і́дольськаго су́єтства, му́чениче, связа́лся єси́ жела́нієм любве́ Христо́ви, і у́зам страда́лець Єго́ ра́достію приобщи́лся єси́.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Заво́рами желі́зними го́лени сокруша́ємі, страстоте́рпці Госпо́дні, нече́стія ко́сті терпі́нія заво́рами і му́жеством воі́стину сокруши́сте.","Огне́м любве́ Боже́ственния ду́шу опаля́єму супру́га, распали́ла єси́ жела́ніє ко Христу́, любо́в плотську́ю, Ната́ліє, до конця́ возненави́дівши.","Богородичен: Боже́ственнаго рождества́ Твоєго́, Чи́стая, вся́кий єстества́ чин превосхо́дить чу́до: Бо́га бо преєсте́ственні зачала́ єси́ во чре́ві, і ро́ждши, пребива́єши Присноді́ва."]},{"h":"Кондак, глас 4","ps":["Жени́ богому́дрия боже́ственная словеса́ в се́рдці положи́в, Адрія́не, му́чениче Христо́в, к муче́ніям усе́рдно устреми́лся єси́, с супру́гою віне́ць приє́м."]},{"h":"Сідален, глас 4","ps":["Нече́стія запале́ніє благоче́стія ороше́нієм угаси́л єси́, страстоте́рпче, сокруше́нієм твої́х удо́в, і́дольськую крі́пость істни́л єси́, супру́жницю обрі́т помо́щницю ко всім лю́тим, му́чениче, ополче́нієм, с не́юже во ви́шнєє всели́лся єси́ Ца́рство, Адрія́не, кріпкоду́шне. Христу́ моли́ся да́ти всім, чту́щим тя, ми́лость.","Богородичен: Треволне́нії стра́стними безсо́вістний аз обурева́єм, Чи́стая, призива́ю Тя те́плі, да не пре́зриши мене́, окая́ннаго, поги́бнути, бе́здну милосе́рдія ро́ждши, ра́зві бо Тебе́, наде́жди не і́мам. Да не враго́м у́бо обра́дованіє і сміх, наді́явся на Тя, явлю́ся, і́бо мо́жеши, єли́ко хо́щеши, я́ко Ма́ти су́щи всіх Бо́га.","Хрестобогородичен: Ді́ва і А́гниця, ви́дівши на кресті́, без сі́мене із Нея́ А́гнця ро́ждшагося і копіє́м прободе́на, печа́лі уя́звлена стріла́ми, вопія́ше болі́зненно, восклиця́ющи: что но́воє та́їнство? Ка́ко умира́єши, І́же живота́ єди́н Госпо́дь? Ті́мже воскресни́, па́дшаго воздвиза́я пра́отця."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи, от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Христа́ му́ченици крі́пость стяжа́вше, некрі́пкоє суровство́ гони́телей воі́стину попра́вше, і вінці́ побі́ди с небесе́ прия́ша.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Гно́єм, всю́ду обтека́ющим святи́х тілесе́м, ми́ро Бо́гу воі́стину принесе́ся, гноє́ніє пре́лести очища́ющеє держа́вно.","Твої́ми кровми́ оде́жду обагри́л єси́ себе́ нетлі́нія, совле́к тлі́нія оде́жду, і Христу́, Адрія́не, со сла́вою ни́ні предстої́ши.","Богородичен: Я́ко воі́стину неізвіща́нна і непостижи́ма, я́же Твоєго́ боголі́пнаго, Богоро́дице, суть рождества́, су́щим на землі́ і на небесі́, Присноді́во, та́їнства."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Десяти́ця сугу́ба страда́лець с просто́ю тро́йцею, Христа́ ни́ні моля́ще, разріши́ша соу́з нече́стія, су́ща безкрі́постна, крі́постію Тро́їчною, до́блественнії.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Я́коже со́лнце, посреді́ стоя́ звізд сві́тлих, Адрія́не, с тобо́ю стра́ждущих облиста́л єси́ сві́том благоче́стія, нече́стія мглу отгна́в, і просвіти́л єси́ ми́ра конці́.","Роса́ глаго́л твої́х честни́х, ісціле́ніє болі́зней воі́стину твоєму́ супру́жнику бисть, вкуси́вшу лу́чших любо́в, богому́драя Ната́ліє, му́чеников сожи́тельнице.","Богородичен: Богоро́дицю Тя от душі́, Влади́чице ми́ра Блага́я, іспові́дающих спаси́: Тя бо предста́тельство непобори́моє і́мами, і́стинную Богороди́тельницю."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Христо́вою окормля́ємі дла́нію благоче́стно, безбо́жия пучи́ну прейдо́сте і ко приста́нищу ти́хому ви́шнія сві́тлости, страда́льці Госпо́дні, устреми́стеся.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Я́ко цві́ти, благоуха́ють по́двиг твої́х, му́дре, я́же па́че єстества́ одолі́нія, і́бо Бо́жиє яви́лся єси́, Адрія́не, благово́нно кади́ло, огне́м мук опаля́єм.","Добро́тою ві́ри свята́я твоя́ душа́ укра́шена, всечестна́я, і добро́ту і́щущи, я́ко воі́стину Христо́ву безмі́рную, Ната́ліє, жела́нія не погріши́.","Богородичен: Всечи́стая Влади́чице, ро́ждшая челові́ком ко́рмчія Го́спода, страсте́й мої́х непостоя́нноє і лю́тоє утоли́ смуще́ніє, і тишину́ пода́ждь се́рдцю моєму́."]},{"h":"Кондак, глас 4","ps":["Му́ченик возсія́ боже́ственная па́м'ять, і земни́я озари́ вся конці́ сві́тло, с весе́лієм зову́щих: Ти єси́ му́чеников, Христе́, ра́дованіє."]},{"h":"Ікос","ps":["На дре́ві кре́стнім пло́тію пригвожде́ннаго, Христа́ Царя́ возжела́вше до́блественне, во́їни, усе́рдно болі́зні лю́тия і му́ки стра́шния претерпі́ша, попра́вше і́дольськоє нече́стіє все, і беззако́нних сопротивле́нія низло́жше, десяти́ця сугу́бая і тро́йця му́ченик. Ті́мже Адрія́н і Ната́лія, супру́г кра́сний сих зря́ще, поревнова́ша їм, і ра́дующеся, вопію́ть: Ти єси́ му́чеников, Христе́, ра́дованіє."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла А́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увіща́ вопи́ти: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Необори́ми я́коже столпи́ яви́стеся, Сіо́на ви́шняго му́ченици, низложи́вше утвержде́нія вся вра́жія терпі́нієм страда́нія ва́шего. Ті́мже почита́єм благоче́стно ва́шу па́м'ять при́сно.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Помо́щниця Адрія́ну Ната́лія я́ко єдиноду́шна от Бо́га дарова́ся, ізвлача́щи углі́бша сего́ во глубині́ пре́лести і увіря́ющи вопи́ти: благослове́н Бог оте́ць на́ших.","Я́ко многоці́нно сокро́вище, му́ченика ру́ку скри́вши, не предала́ єси́ цілому́дрія твоєго́ сокро́вища укра́сти тща́щимся, честна́я, окормля́єма руко́ю отце́в Бо́га.","Богородичен: Свяще́ннії проро́ци провозвісти́ша, Чи́стая, явле́нно та́їнство честна́го рождества́ Твоєго́, і ни́ні ми, сбитія́ іздале́ча смотря́юще, благоче́стно Тя ублажа́єм."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. Тя превозно́сим во вся ві́ки.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Огне́м муче́нія всесожига́ємі, нече́стія пла́мень весь угаси́сте кровми́ ва́шими, страда́льці, зову́ще: Тя превозно́сим, Христе́, во вся ві́ки.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Жени́ чу́дния кто не удиви́ться су́щия к Бо́гу любві́? Я́ко возненави́ді жела́ніє плотсько́є, і супру́жника уві́ри чести́ і сла́вити Христа́ во ві́ки вся.","Посрами́в безбо́жних су́єтства і возжела́в Христо́ву красоту́, столп благоче́стія ві́рним бил єси́, му́чениче, страстоте́рпче Адрія́не всеблаже́нне.","Богородичен: От Сві́та Світода́вця Сло́ва зачала́ єси́, і ро́ждши несказа́нно Пресу́щественнаго: Дух бо в Тя, Ді́во, Бо́жий всели́ся. Ті́мже Тя поє́м, Чи́стая, во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни а́нгельстії взира́ти; Тобо́ю бо, Всечи́стая, яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с небе́сними во́ї, Тя ублажа́єм.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Удо́в сокруше́ніє, лю́тих преще́нія, ні меч, ні огнь, ні смерть пло́ті тлі́нния, Христо́ви любве́ разлучи́ти вас, сла́внії страда́льці, отню́д возмого́ша. Ті́мже во ві́ки с Ним при́сно веселіте́ся.","Приспів: Святі́ї му́ченици Адрія́но і Ната́ліє, молі́те Бо́га о нас.","Свіщи́ богосві́тли, зві́зди сія́ющия, світи́льници, нам світ благоче́стія озаря́юще, со́лнця сла́ви сія́нія, ча́да невече́рняго блаже́нства, му́ченици яви́стеся Христо́ви всечестні́ї.","Істо́чник вод іспо́лнен духо́вних, і ріка́, Боже́ственних дарова́ній іспо́лнена, і ча́ша страда́нія пролива́ющая то́ки, пучи́ни спасе́нія, му́ченици яви́стеся, бу́ри напа́стей разли́чних нас ізбавля́юще.","Богородичен: Ме́ртвим воста́ніє ни́ні дарова́ся Твої́м несказа́нним і неізрече́нним рождество́м, Богоро́дице Всечи́стая: Жизнь бо із Тебе́, пло́тію обложе́на, всім возсія́ і сме́ртную дря́хлость я́ві разруши́."]},{"h":"Світилен","ps":["Адрія́н всему́дрий, страда́льцев утвержде́ніє, с честно́ю Ната́лією пі́сньми досто́йно да почти́ться, с ни́миже облиста́єть му́ченик собо́р святи́й. Ї́хже сві́тлоє торжество́ соверша́юще благочестному́дренно, поє́м пі́сньми боже́ственними.","Богородичен: І́же дре́вле мі обоже́нію во Єде́мі позави́дівша, томи́теля змі́я, Ді́во, смири́вся во утро́бі Твоє́й Творе́ць тва́рі і Зижди́тель єстества́, боголі́пно погуби́ кресто́м і сме́ртію, істоча́я мі нетлі́ніє."]}],"notes":[]},{"u":"Канон загальний святій мучениці","e":"General canon to a holy female martyr","secs":[{"ps":["Початок канонів (див. Чин читання канонів)","Після «Бог Господь»:","Якщо є, тропар мучениці і Богородичен за гласом тропаря; якщо ж тропаря немає, то читаємо:"]},{"h":"Тропар загальний мучениці, глас 4","ps":["А́гниця Твоя́, Ісу́се, ім’я, зове́ть ве́ліїм гла́сом: Тебе́, Женише́ мой, люблю́, і Тебі́ і́щущи страда́льчествую, і сраспина́юся, і спогреба́юся креще́нію Твоєму́, і стра́жду Тебе́ ра́ди, я́ко да ца́рствую в Тебі́, і умира́ю за Тя, да і живу́ с Тобо́ю. Но я́ко же́ртву непоро́чну прийми́ м'я с любо́вію поже́ршуюся Тебі́. Тоя́ моли́твами, я́ко ми́лостив, спаси́ ду́ші на́ша. (Два́жди.)","Слава, і нині, Богородичен: Є́же от ві́ка утає́нноє і А́нгелом несві́домоє та́їнство, Тобо́ю, Богоро́дице, су́щим на землі́ яви́ся Бог, в несли́тном соєдине́нії воплоща́єм, і Крест во́лею нас ра́ди восприї́м, і́мже воскреси́в первозда́ннаго, спасе́ от сме́рти ду́ші на́ша."]},{"h":"Потім: Псалом 50","ps":["Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́.","Найпа́че оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я.","Я́ко беззако́ніє моє́ аз зна́ю і гріх мой предо мно́ю єсть ви́ну.","Тебі́ Єди́ному согріши́х, і лука́воє пред Тобо́ю сотвори́х, я́ко да оправди́шися во словесі́х Твої́х і побіди́ши, внегда́ суди́ти Ті.","Се бо в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́.","Се бо і́стину возлюби́л єси́, безві́стная і та́йная прему́дрости Твоєя́ яви́л мі єси́.","Окропи́ши м'я іссо́пом, і очи́щуся, оми́єши м'я, і па́че сні́га убілю́ся.","Слу́ху моєму́ да́си ра́дость і весе́ліє, возра́дуються ко́сті смире́нния.","Отврати́ лице́ Твоє́ от гріх мої́х, і вся беззако́нія моя́ очи́сти.","Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й.","Не отве́ржи мене́ от лиця́ Твоєго́, і Ду́ха Твоєго́ Свята́го не отими́ от мене́.","Возда́ждь мі ра́дость спасе́нія Твоєго́, і Ду́хом Влади́чним утверди́ м'я.","Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться.","Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́, возра́дується язи́к мой пра́вді Твоє́й.","Го́споди, устні́ мої́ отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́.","Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо, всесожже́нія не благоволи́ши.","Же́ртва Бо́гу дух сокруше́н, се́рдце сокруше́нно і смире́нно Бог не унічижи́ть.","Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія.","Тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая: тогда́ возложа́ть на олта́р Твой тельці́."]},{"h":"Канон, глас 8. Пісня 1","ps":["Ірмос: Пої́м Го́сподеві, прове́дшему лю́ди Своя́ сквозі́ Чермно́є мо́ре, я́ко єди́н сла́вно просла́вися.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Влече́ть к піснопі́нію преми́рних во́їнства, і земни́х ли́ки, всехва́льная отрокови́ця, чудеси́.","Добро́ти возжела́во Влади́ка всіх, красні́йшаго твоєго́ се́рдця всехва́льная, небе́сних черто́гов сподо́би тя.","Слава: На ка́зні і болі́зні, і на ра́ни многообра́зния, не устраше́на, му́ченице, вмісти́лася єси́: поспіша́ющую бо і́маши благода́ть Спа́сову, возмога́ющую тя.","І нині: Пречи́стая Богоро́дице, воплоще́нно Присносу́щноє і Пребоже́ственноє Сло́во па́че єстества́ ро́ждшую, поє́м Тя.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)"]},{"h":"Пісня 3","ps":["Ірмос: Ти єси́ утвержде́ніє притека́ющих к Тебі́, Го́споди, Ти єси́ світ омраче́нних, і поє́ть Тя дух мой.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Яви́лася єси́ на суди́щі му́жественну ду́шу нося́щи, і врага́ я́коже нему́жественна побіди́ла єси́ всехва́льная.","Поро́к в добро́ті твоє́й, ніже́ вра́ська душі́ бисть; і тя Христо́с неві́сту в нетлі́нния черто́ги прия́т.","Слава: Ісціли́ всехва́льная душі́ моєя́ стру́пи, му́ченице Христо́ва, ім’я, і утиши́ твої́ми моли́твами жи́зні моєя́ бу́рю.","І нині: Тя всі стяжа́хом прибі́жище, і сті́ну на́шу христия́не, і Тя славосло́вим немо́лчно, Безневі́стная.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)","Го́споди поми́луй. (Три́жди.)","Якщо є особливий кондак мучениці, читаємо його перед сідаленом."]},{"h":"Сідален, глас 8","ps":["Крове́й твої́х струя́ми, му́ченице Христо́ва, пото́п нечести́вим при́сно ді́йствуєши, всехва́льная; ту́чами же благода́ті слове́сния ни́ви напая́ющи всегда́, в ни́хже возраща́єши клас ві́ри, тім пресла́вно і по сме́рті яви́лася єси́ о́блак, істоча́ющи жи́зні свиді́тельство, страстоте́рпице всехва́льная, ім’я, моли́ся Христу́ Бо́гу, согріше́ній оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Слава, і нині, Богородичен: Я́ко Ді́ву і єди́ну в жена́х Тя безсі́менно ро́ждшую Бо́га пло́тію, всі ублажа́єм ро́ди челові́честії: огнь бо всели́ся в Тя Божества́, і я́ко Младе́нця доі́ши Зижди́теля і Го́спода. Тім а́нгельський собо́р і челові́чеський род, досто́йно сла́вим пресвято́є рождество́ Твоє́, і согла́сно вопіє́м Ті: моли́ Христа́ Бо́га, прегріше́ній оставле́ніє дарова́ти, досто́йно пою́щим сла́ву Твою́."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́, і просла́вих Твоє́ Божество́.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Нескве́рноє зерца́ло боже́ственних разумі́ній тебі́ саму́ю устро́ївши, я́ко світи́льник златолі́потнійший страда́лиць посреді́, му́ченице, возсія́ла єси́.","Мра́чному не принесла́ єси́ де́мону же́ртви, непобіди́мая му́ченице, ім’я, жизноно́сную бо возлюби́ла єси́ за благоче́стіє смерть прия́ти.","Слава: Я́ко неболі́зненно нося́щи со страстоно́сці ті́ло непоро́чная, ра́нами нечу́вственна пребила́ єси́, боже́ственния любве́ раче́нієм.","І нині: Очище́ніє нам да́руй неві́діній, я́ко безгрі́шен, і умири́ мир Твой, Бо́же, моли́твами Ро́ждшия Тя.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)"]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще вопіє́м Ті: Го́споди, спаси́ ни, Ти бо єси́ Бог наш, ра́зві Тебе́ іно́го не ві́ми.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Дне і ми́ра противополо́жноє уві́дівши, ратолю́бнаго де́мона люби́ти не восхоті́ла єси́.","Мнів твою́ осла́бити боже́ственную, му́ченице, ім’я, любо́в, сміх яви́ся, козньми́ вселука́вий.","Слава: Пода́ждь мі просвіще́ніє і мир, всехва́льная, ріша́щи моли́твами твої́ми многом'яте́жноє смуще́ніє.","І нині: Ді́ву по рождестві́ поє́м Тя, Богоро́дице, Ти бо Бо́га Сло́ва пло́тію ми́ру породи́ла єси́.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)"]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том я́ко ри́зою, многоми́лостиве Христе́ Бо́же наш.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Му́жественноє в же́нстій пло́ті душі́ мудрова́ніє нося́щи сла́вная, о зві́ріх су́щих во вода́х неради́ла єси́.","Побіди́ла єси́ мучи́телей горди́ню, неврежде́на преби́ла єси́, му́ченице непобіди́мая, і віне́ць побі́ди прия́ла єси́.","Слава: Я́ко добру́, і я́ко красну́, я́ко че́стну, і я́ко ді́вства заря́ми сія́ющую, тебі́ Жени́х Госпо́дь Себі́ приво́дить, пресла́вная.","І нині: Єди́на Сло́вом пло́тію Сло́во поро́ждшая, ізба́ви, мо́лимся, сіте́й вра́жиїх ду́ші на́ша.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)","Го́споди поми́луй. (Три́жди.) Сла́ва, і ни́ні."]},{"h":"Кондак, глас 2","ps":["Храм Твой всечестни́й, я́ко цільбу́ душе́вную обрі́тше всі ві́рнії, велегла́сно вопіє́м Ті, ді́во му́ченице, ім’я, великоімени́тая: Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Ікос","ps":["Уневі́стившуюся Христу́ муче́нієм, ім’я, соше́дшеся, почти́м досто́йно, я́ко да тоя́ моли́твами, душетлі́нния па́губи ізба́вльшеся, губи́тельства, тру́са і падежа́, житіє́ во смире́ніє препрово́дим, сподо́бльшеся со всі́ми святи́ми, от ві́ка Бо́гу благоугоди́вшими, ходи́ти во сві́ті, і пі́ти с си́ми: удиви́л єси́, Спа́се, Твоя́ ми́лості всім челові́ком, ві́рою хва́лящим ю. Ті́мже зове́м єй: моли́ непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше о́троци, во Вавило́ні іногда́, ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще: отце́в Бо́же, благослове́н єси́.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Па́че ума́ яви́шася боже́ственних му́чеников благому́жества, Зижди́тель бо всіх твар покаря́єть во страда́нії зову́щим: отце́в на́ших Бо́же, благослове́н єси́.","Ху́лящая загради́ преслову́щая отрокови́ця уста́ мучи́телей, і горди́ню пребеззако́нних Ду́хом Святи́м, боже́ственно воспіва́ющи: отце́в на́ших Бо́же, благослове́н єси́.","Слава: Тро́йця о́трок преподо́бних разже́гшия пещ дре́вле попали́; ни́ні же Богому́драя, Тро́йцю пою́щи, слуги́ улови́, отце́в Бо́га пою́щия: Бо́же, благослове́н єси́.","І нині: На́ше спасе́ніє я́коже восхоті́л єси́, Спа́се, устро́їти, во утро́бу Ді́ви всели́лся єси́, Ю́же ми́ру предста́тельницю показа́л єси́, отце́в на́ших Бо́же, благослове́н єси́.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)"]},{"h":"Пісня 8","ps":["Ірмос: Царя́ Небе́снаго, Єго́же пою́ть во́ї а́нгельстії, хвалі́те і превозносі́те во вся ві́ки.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Блаже́ннійшая в жена́х, Ви́шняго возме́здную іму́щи благода́ть, поя́ше хва́лящи Христа́ во ві́ки вся.","Укріпле́на по́мислом Неві́стника, невеще́ственним раче́нієм, ті́ло предала́ єси́ на смерть, і живе́ши во ві́ки вся.","Слава: Та́йно Жени́х ко пречи́стій неві́сті в пещ прише́д, духо́вною росо́ю О́тчим благоволе́нієм спасл єсть, пою́щу Христа́ во ві́ки.","І нині: По́мощі я́же от Тебе́ тре́бующия не пре́зри, Ді́во, пою́щия і превознося́щия Тя во ві́ки.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)"]},{"h":"Пісня 9","ps":["Ірмос: Тя, неіскусобра́чную Ма́тер Бо́га ви́шняго, Тя, па́че ума́ ро́ждшую сло́вом воі́стину Бо́га, ви́шшую пречи́стих сил, немо́лчними славословле́нії велича́єм.","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Приспів: Свята́я му́ченице, ім’я, моли́ Бо́га о нас. (Покло́н.)","Тече́ніє живи́я кро́ве зна́меніє нетлі́нния сви́ше дарова́нния тебі́ жи́зні, му́ченице всехва́льная, ціле́ній бо сокро́вище непреста́нноє че́рплющим яви́лася єси́.","Косне́ся тебі́ смерть єстества́ зако́ном, богому́драя, в живоно́сную же ме́ртвость нестра́стно облекла́ся єси́. Є́юже я́ко одушевле́нноє твоє́ ті́ло поло́жши всечестно́є, живе́ши нетлі́нно, і свидіте́льствують твоя́ кровотече́нія.","Слава: Я́ко со́лнечную лучу́ озаря́ющую вся, і я́ко неві́сту Христо́ву предо́бру, я́ко го́рлицю чистолюби́вую, і я́ко ма́слину, я́ко кедр, я́ко су́щую ізбра́нную голуби́цю, хва́лим тя всі, ім’я, богоімени́тая.","І нині: Неві́сто неіскусобра́чная, сосу́де благово́нія, Тя я́ко і́стинную і непоро́чную, і боже́ственнаго о́блак сві́та, приє́мшую небе́сний дождь во утро́бі, Ді́во Ма́ти, велича́єм.","Моли́ Бо́га о нас, свята́я му́ченице, ім’я, я́ко ми усе́рдно к тебі́ прибіга́єм, ско́рой помо́щнице і моли́твеннице о душа́х на́ших. (Покло́н.)","Потім закінчення канону (див. Чин читання канонів)"]},{"h":"Тропар загальний мучениці, глас 4","ps":["А́гниця Твоя́, Ісу́се, ім’я, зове́ть ве́ліїм гла́сом: Тебе́, Женише́ мой, люблю́, і Тебі́ і́щущи страда́льчествую, і сраспина́юся, і спогреба́юся креще́нію Твоєму́, і стра́жду Тебе́ ра́ди, я́ко да ца́рствую в Тебі́, і умира́ю за Тя, да і живу́ с Тобо́ю. Но я́ко же́ртву непоро́чну прийми́ м'я с любо́вію поже́ршуюся Тебі́. Тоя́ моли́твами, я́ко ми́лостив, спаси́ ду́ші на́ша.","Якщо є особливий кондак мучениці, потім:"]},{"h":"Кондак, глас 2","ps":["Слава: Храм Твой всечестни́й, я́ко цільбу́ душе́вную обрі́тше всі ві́рнії, велегла́сно вопіє́м Ті, ді́во му́ченице, ім’я, великоімени́тая: Христа́ Бо́га моли́ непреста́нно о всіх нас.","І нині, Богородичен: Вся па́че сми́сла, вся пресла́вная Твоя́, Богоро́дице, та́їнства, чистоті́ запеча́танной, і ді́вству храни́му, Ма́ти позна́лася єси́ нело́жна, Бо́га ро́ждши і́стиннаго, Того́ моли́ спасти́ся душа́м на́шим.","Потім:","«Чеснішую Херувим:» і далі (див. Чин читання канонів)"]}],"notes":[]},{"u":"Канон святим мученикам Гурію, Самону і Авіву","e":"Canon to the Holy Martyrs Gurias, Samonas and Abibus","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́зними Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Тро́йці єдинонача́ліє, святі́ї, богосло́в'яще че́стно, многонача́лія нестоя́нную мглу удо́бно разруши́сте, восто́ка, многосві́тлії, я́коже зві́зди возсія́вше.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Тріє́ іспові́дниці, благода́тію просвіща́ємі Нача́льния Тро́йці я́вственно, лесть многобо́жную, терпіли́вно противле́ніє явля́юще, істреби́ша.","Вас, у́бо синоположи́в, сла́внії, любо́вію Єсте́ственний Син, ни́ні Єму́ наслі́дію, дає́му я́ві, я́ко Благоутро́бен снаслі́дники показа́ і Ца́рствія соприча́стники.","Богородичен: Му́дрости прему́дростния ски́нія била́ єси́, Всенепоро́чная, Свой бо храм от Твої́х пречи́стих крове́й, Чи́стая, созда́ти благоволи́ на спасе́ніє душ на́ших."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Ті́ло му́кам во́лею і лю́тим ра́нам Христо́ви преда́ша іспові́дниці і уго́дниці.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Ізба́витися от лю́тих гріхо́вних по́мисл, святі́ї, ва́шу па́м'ять ві́рою соверша́ющим умолі́те.","На дре́ві терпіли́вно воздви́жені, честні́ї свиді́теліє всеблагоче́стно невре́дно іспові́даніє соблюдо́ша.","Богородичен: Ціле́ній Тя істо́чник в Твою́ утро́бу Вше́дий показа́, Ма́ти Бо́жия, Пречи́стая, мою́ у́бо ду́шу ісціли́."]},{"h":"Сідален, глас 8","ps":["Кресто́м вооружи́вшеся Христо́вим, в нем мучи́телей всю крі́пость му́жеськи низложи́сте, я́ко ві́ри побо́рници; безбо́жіє все і́дольськоє обличи́сте і Тро́йцю, святі́ї, усе́рдно пропові́давше. Тім досто́йно от Нея́ вінці́ побі́ди прия́сте, я́ко зако́нно пострада́вше, страстоте́рпці всесла́внії, молі́те Христа́ Бо́га гріхо́в оставле́ніє пода́ти пра́зднующим любо́вію святу́ю па́м'ять ва́шу.","Слава: Христу́ порабо́тавше му́ченичеськи, порабо́тисте лесть мучи́тельськую, непорабоще́нну іму́ще ду́шу і му́дрость, і́бо Тро́їчною ві́рою уязви́вшеся, прехва́льнії, многобо́жія сла́ву несла́вную обличи́сте. Тім, я́ко зві́зди, сві́тло в ми́рі блиста́нієм сія́єте чуде́с, блаже́ннії. Страстоте́рпці всехва́льнії, молі́те Христа́ Бо́га гріхо́в оставле́ніє пода́ти чту́щим любо́вію святу́ю па́м'ять ва́шу.","І нині: Я́ко ді́ву і єди́ну в жена́х, Тя, без сі́мене ро́ждшую Бо́га пло́тію, всі ублажа́єм, ро́ди челові́честії: огнь бо всели́ся в Тя Божества́, і я́ко Младе́нця доі́ши Зижди́теля і Го́спода. Тім, а́нгельський і челові́чеський род, досто́йно сла́вим пресвято́є Рождество́ Твоє́ і согла́сно вопіє́м Ті: моли́ Христа́ Бо́га согріше́ній оставле́ніє дарова́ти покланя́ющимся ві́рою пресвято́му Рождеству́ Твоєму́.","Хрестобогородичен: А́гнця, і Па́стиря, і Ізба́вителя А́гниця зря́щи на Кресті́, восклиця́ше, пла́чущи, і, го́рко рида́ющи, вопія́ше: мир у́бо ра́дується, приє́мля Тобо́ю ізбавле́ніє, утро́ба же Моя́ гори́ть, зря́щи Твоє́ расп'я́тіє, є́же терпи́ши за милосе́рдіє ми́лости. Долготерпіли́ве Го́споди, ми́лости бе́здно і істо́чниче неісчерпа́ємий, умилосе́рдися і да́руй согріше́ній оставле́ніє ві́рою пою́щим Боже́ственния стра́сті Твоя́."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце Пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Тро́йці равночи́сленнії віне́чници трисія́нною свіще́ю ни́ні соверша́ющия па́м'ять всесвяще́нную тіх озаря́ють, всім ісціле́нія подаю́ще.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","С благогові́нієм притеце́м к світоно́сній і світоза́рній, богому́дрії, ра́ці му́ченик, то́чить бо врачева́нія ві́рою зову́щим: сла́ва си́лі Твоє́й, Го́споди.","Іспові́дающе Боже́ственноє строє́ніє і па́че ума́ та́їнство, богосло́вними язи́ки все безбо́жіє мучи́телей боже́ственнії і всему́дрії іспові́дниці попра́ша.","Богородичен: Па́че ума́ родила́ єси́, о Ді́во, і по рождестві́ яви́лася єси́, ді́вствующи па́ки. Тім немо́лчними гла́си, ра́дуйся, Тебе́, Влади́чице, ві́рою несомні́нною вопіє́м."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой Світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Сві́тлостію я́ві подвиго́в сія́юще, посрами́ша мучи́телей свирі́пий нрав ві́ри побо́рници.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Во вся я́вственно вселе́нния конці́ чудеса́ му́ченик пропові́дашася і вся ві́рою утверди́ша.","Я́коже земля́ блага́я, благода́ті сі́мена приє́мши, житіє́м трудолю́бно бога́тство блаже́ннії соді́яша.","Богородичен: Єди́н Благи́й, пучи́ною благости́ні вся́чеськая, Богома́ти, содержа́й, Твої́ми об'я́тії держа́тися сподо́би."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Зако́нно, я́ко до́брії во́їни, богому́дрії, удержа́вше вся і я́сно ві́ру соблю́дше, Боже́ственния пра́вди прия́сте вінці́.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Пре́жде у́бо Авваку́м висо́ці возвиша́ється Влади́чнім повелі́нієм, чрез вас же отрокови́ця му́чима, богоглаго́ливії, к воспита́вшей возврати́ся.","Сія́єть ра́ка му́ченик чудеси́ і рі́ки істоча́єть ісціле́ній всім, приходя́щим ві́рою і тіх терпі́нію див'я́щимся.","Богородичен: Тя єди́ну посреді́ те́рнія обрі́т, я́ко чисті́йший крин і во удо́ліїх цвіт, о Богома́ти, Жени́х у́мний в Тя всели́ся."]},{"h":"Кондак, глас 2","ps":["С висоти́, му́дрії, благода́ть приє́мше, су́щим во іскуше́ніїх предстоїте́, всехва́льнії. Ті́мже отрокови́цю, святі́ї, от сме́рти го́ркия ізба́висте, ви бо воі́стину єсте́ Єде́су сла́ва і ми́ру ра́дость."]},{"h":"Ікос","ps":["Вра́жия м'я рабо́ти ізба́ви, Ісу́се Жизнода́вче, Твої́х страда́лець мольба́ми умоля́єм, я́ко да непорабоще́нну стяжа́в от страсте́й ду́шу мою́ і ті́ло, восхвалю́ тіх скорі́йшую по́мощ, я́коже во гро́бі затворе́нная му́жа лука́вствієм, і сію́ ско́ро предвари́вше, от сме́рти ізба́виша, зову́щу: Єде́су сла́ва і ми́ру ра́дость."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем, опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Авраа́мськия в пещі́ ді́ти ізба́вивий, Сий і стра́нную отрокови́цю лю́таго обстоя́нія спасе́ хода́тайством ни́ні святи́х уго́дник, я́ко Благоутро́бен.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Суро́війшаго безчелові́чія му́ку да́вий, всіх зол а́біє істя́зан уби́йця злоїмени́тий судо́м пра́ведним Твої́м, Сло́ве Бо́жий, му́дросте і си́ла.","Укріпля́єма к вам наде́ждею, сла́внії, отрокови́ця, заключе́нная во гро́бі с ме́ртвими, ча́янія не погріши́, зову́щи: благослове́н єси́, Го́споди Бо́же оте́ць на́ших.","Богородичен: Я́ко новосміше́ноє і світоза́рноє пуща́я зерца́ло, Зарю́ Боже́ственнаго, Ді́во, сія́нія, приложи́вшуюся Тебі́, вмісти́ла єси́. Благослове́нна Ти в жена́х, Всенепоро́чная Влади́чице."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р, Данії́л, львов зія́нія в ро́ві затче́; о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Всеми́рний днесь нам наста́ пра́здник му́ченик Христо́вих, озаря́ющ благода́тію чуде́с приходя́щия ві́рою і ра́достію духо́вною і любо́вію зову́щия: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Удо́бно іспові́дниці Твоєго́ Божества́ все упраздни́ша безбо́жіє, Влади́ко, мучи́телей не убоя́вшеся преще́ній злоу́мних, ві́рою укріпля́ємі, взива́юще: благослові́те вся діла́ Госпо́дня Го́спода.","Всему́дрії іспові́дниці, предстоя́ще боже́ственному повелі́нію, враго́в полки́ побіжда́ющи, мече́м закала́ємі, побі́ду пресла́вно я́ві і пресія́ющу показа́ша, па́дающе бо, проти́вния побіди́ша.","Богородичен: Єстестви́ ви́димаго двіма́, Христа́ родила́ єси́, єди́ну нося́ща я́ві Іпоста́сь сло́жну Божества́ і челові́чества, сте́кшуся єсте́ственному і́стинно по соєдине́нію: тім Тя благослови́м, Марі́є Богоневі́стная."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся — Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Словесе́м послі́дующе боже́ственним і богодухнове́нним Христо́вим, іспові́дниці богосві́тлії, крест на ра́мена, ра́дующеся, взя́сте, жизноно́сним стопа́м послі́дующе, достосла́внії.","Приспів: Святі́ї му́ченици Гу́ріє, Само́не і Ави́ве, молі́те Бо́га о нас.","Всему́ сві́ту Тро́йці с весе́лієм до́блії іспові́дниці вмі́щшеся, подвиго́в че́сти восприйма́ють, безпло́тних чино́в сподо́бльшеся соводворе́нія.","Ни́ні не в зерца́лі зріте́ блаже́нних наде́жди, іспові́дниці Спа́сови; і́стини же па́че, всему́дрії, добро́ту зріте́, вінцено́сці всечестні́ї.","Я́ко Пребоже́ственния Тро́йці я́ві равночи́сленнії я́вльшеся іспові́дниці, богоглаго́ливії, Тоя́ заря́ми просвіща́єтеся, я́ко Тоя́ ра́ди пострада́вше, Жи́зні нетлі́нния ни́ні улучи́ша.","Богородичен: Пло́тію прийти́ восхоті́в, украси́вий вся, Сло́во в Тя всели́ся, єди́ну святі́йшу всіх обрі́ть, і Богоро́дицю воі́стинну яви́, Ма́ти Ді́во."]},{"h":"Світилен","ps":["І́же от гро́ба отрокови́цю ізба́вльше дре́вле, Гу́ріє, і Само́не, і Ави́ве, му́ченици Христо́ви, предварі́те, я́ко от гро́ба прегріше́ній ни ізбавля́юще.","Богородичен: Крі́пким Твої́м покро́вом от наві́т вра́жиїх ни, Чи́стая, Твоя́ раби́, сохрани́ невреди́ми, Тя бо стяжа́хом єди́ну прибі́жище в біда́х."]}],"notes":[]},{"u":"Канон молебний святим рівноапостольним Мефодію і Кирилу, учителям Словенським","e":"Supplicatory canon to the Holy Equals-to-the-Apostles Methodius and Cyril, Teachers of the Slavs","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, / і єги́петськаго зла ізбіжа́в, / ізра́їльтянин вопія́ше: / Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Ки́я досто́йния принесу́ похва́льния пі́сні Богослове́сником? / Сві́та дар сви́ше послі́те мі, / да досто́йно воспою́ ва́шу па́м'ять.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Ю́ность ізмла́да твою́ без поро́ка восприї́м, / Влади́ці своєму́ послі́довав, свя́те Кирі́лле блаже́нне. / Тім тя досто́йно сла́вить вся твар.","Ро́су істочи́ Бо́жия Ду́ха, восприї́м от Бо́га, свя́те, / я́ко гром, возгремі́ в конці́х, / сло́во разсіва́я во язи́ціх.","Ілия́ други́й ра́вний яви́ся на землі́, Мефо́діє свя́те, / вся́кия є́ресі попаля́я Богодохнове́нним уче́нієм.","Богородичен: Чи́ни Тя а́нгельстії і челові́честії, / Безневі́стная Ма́ти, хва́лять непреста́нно, / Зижди́теля бо їх, я́ко Младе́нця, на руку́ Своє́ю понесла́ єси́."]},{"h":"Пісня 3","ps":["Ірмос: Ти єси́ утвержде́ніє / притека́ющих к Тебі́, Го́споди, / Ти єси́ Світ омраче́нних, / і поє́ть Тя дух мой.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Лі́ствиця ізбра́на яви́ся, фило́софе Богогла́сне, / вся бо уче́нієм на Не́бо возво́диши.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Ангелообра́зно житіє́ живи́й на землі́, прему́дре Константи́не, / досто́їн всім нарече́ся учи́тель.","Фарао́на ми́сленнаго в мо́рі жите́йстім погрузи́, / ізбра́н во́їн яви́ся Христа́ Бо́га, Мефо́діє.","Ієре́йськую слу́жбу вознося́ пред Бо́га, / обрі́теся досто́їн, ра́вен А́нгелом, о́тче Мефо́діє.","Богородичен: Тебі́ всі і́мами прибі́жище і сті́ну на́шу, христия́ни, / і Тебі́ сла́вим немо́лчно, Безневі́стная."]},{"h":"Сідален, глас 8","ps":["Я́ко заря́, просвіща́я всю зе́млю, / єретики́ го́ниши на восто́ці, і за́паді, і сі́вері же, і ю́зі, / тріязи́чники пра́виши, пропові́дая конце́м, на язи́ці їх глаго́ля, кни́ги прелага́я. / Ри́ма же доше́д, ту і ті́ло своє́ положи́, блаже́нне, / і ду́шу свою́ в ру́ці Госпо́дні пре́дал єси́, / благові́рний учи́телю, / моли́ Христа́ Бо́га гріхо́в оставле́ніє пода́ти."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, / Ти моя́ і си́ла, / Ти моє́ Бог, Ти моє́ ра́дованіє, / не оста́вль ні́дра О́тча / і на́шу нищету́ посіти́в. / Тім с проро́ком Авваку́мом зову́ Ті: / си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Лику́я со А́нгели на Небесі́х, / прилі́жно за ни моли́ся / со А́нгели, і проро́ки, і апо́столи, / вся́кия ско́рби отгоня́я і напа́стния прило́ги разоря́я і біди́, Богогла́се.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Очи́щ ізмла́да, свя́те, ду́шу твою́ і ті́ло, / досто́їн сосу́д обрі́теся Пресвято́му Ду́ху, о́тче Кирі́лле блаже́нне, / І́мже просві́щся, сія́єши в ми́рі, / ісціле́нія всім оби́льно подая́, пресла́вне.","Стопа́ми всю вселе́нную освяти́, Богогла́се о́тче Мефо́діє, / сло́во раздая́ всім страна́м, но́вим язи́ком, / ті́мже тя, бла́же, вся твар сла́вить, / твої́ми словеси́ просвіща́єма.","Обрі́теся но́вий Па́вел, прему́дре, / весь мир Бо́гові приобрі́те, / разу́мно Крест Христо́в на ся восприї́м, доі́де до за́пада, свя́те, / лесть і́дольськую всю разоря́я, вся є́ресі, блаже́нне, потребля́я.","Богородичен: Ти ві́рним похвала́ єси́, Безневі́стная, / Ти заступле́ніє, Ти прибі́жище христия́ном, стіна́ і приста́нище, / к Си́ну бо Своєму́ мольби́ но́сиши, Непоро́чная, / і от бід спаса́єши ві́рою і любо́вію Богоро́дицю Чи́стую Тя зна́ющия."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, / і ми́шцею Твоє́ю висо́кою / Твой мир пода́ждь нам, / Человіколю́бче.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Фило́софову му́дрость поче́рпл єси́ / і бе́здни Бо́жия сокро́вища, / і́миже озари́вся, сло́во разсі́я в язи́ки но́ви.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","А́нгельськия чи́ни преспі́л єси́, му́дре, / на землі́, я́ко безпло́тен, яви́ся, / Христо́вими заря́ми просвіща́я вселе́нную.","І́дольськую лесть безбо́жную іскорени́, / сла́дость всім істоча́я Бо́жия словесе́, / свя́те Мефо́діє.","Бо́жию при́сно Престо́лу, свя́те, предстої́ши, / прилі́жно за ни моли́ся, / творя́щия ві́рно твою́ па́м'ять.","Богородичен: Помоли́ся ви́ну Си́ну Своєму́ і Бо́гу на́шему, / Браконеїску́сная Марі́є Чи́стая, / посла́ти нам, ві́рним, ве́лію ми́лость."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду / і Тому́ возвіщу́ печа́лі моя́, / я́ко зол душа́ моя́ іспо́лнися / і живо́т мой а́ду прибли́жися, / і молю́ся, я́ко Іо́на: / от тлі, Бо́же, возведи́ м'я.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Лю́тими страстьми́ одержи́ми / і напа́стною бу́рею дви́жими, / вопіє́м ті, святи́й учи́телю: / ни́щія своя́ раби́ ізба́ви от бід, / ско́рим посіще́нієм вся ско́рбі отгоня́я, Богогла́се.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Апо́столом ра́вну благода́ть Пречи́стаго Ду́ха, о́тче, приї́м, / іспо́лнь весь мир благоче́стія, сла́достно наставля́я, / рі́ки бо живо́тния, по гла́су Бо́жию істека́ющия із тебе́, / мир возвесели́ша.","Жите́йськую сла́ву на землі́ всю оста́вль, блаже́нне о́тче, / Влади́ці своєму́ і Бо́гу весь приве́ржеся душе́ю і ті́лом, / тім тя досто́йна нам всім по́дал єсть учи́теля.","Єресе́м всім проти́вен яви́ся благода́тію, Мефо́діє, досто́йними отві́ти, / от Отця́ у́бо Пара́клита ісходя́ща, а не от Си́на, глаго́ля, / но ра́венством Тро́йцю чи́сті іспові́дая.","Богородичен: Не преста́ни о нас моля́щи, Пресвята́я Богоро́дице Ді́во, / я́ко ві́рним утвержде́ніє Ти єси́, / і наде́ждою Твоє́ю кріпі́мся. / Ті́мже Тя і із Тебе́ воплоще́ннаго Бо́га прославля́єм."]},{"h":"Кондак, глас 2","ps":["Тве́рдаго і Богодохнове́ннаго уче́нія / просвіща́я мир пресві́тлими заря́ми, / обтече́, я́ко мо́лнія, вселе́нную, Кирі́лле свя́те, / разсіва́я Бо́жиє сло́во на за́паді, і сі́вері, і ю́зі, / мир просвіща́я уче́нієм, свя́те."]},{"h":"Інший кондак, глас 2","ps":["Пресві́тло житіє́ возлюби́, свя́те, / заря́ми трисо́лнечними Божества́ освіща́єм, / приї́де, я́ко мо́лнія, во всю вселе́нную, / сі́верную і ю́жную зе́млі просвіща́я, / за́падним же світ незаходи́м яви́ся. / Ті́мже і ни́ні мрак гріхо́вний прогна́в, свя́те, / сви́ше іспроси́ благода́ть духо́вную, / і́маши бо дерзнове́ніє к Бо́гу."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше, о́троци / во Вавило́ні іногда́ / ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще: / отце́в Бо́же, благослове́н єси́.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Неоску́дно сркро́вище яви́ся, Кири́лле, Пресвято́му Ду́ху, / І́мже просві́щся, научи́ весь мир язи́ки воспіва́ти: / оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Авраа́м други́й преселе́нієм яви́ся, о́тче Кири́лле, в зе́млю Ханаа́нську, / ю́же просвіти́ сло́вом но́ва уче́нія, воспіва́я: / оте́ць на́ших Бо́же, благослове́н єси́.","Мора́вськая страна́, ве́лій за́ступ і столп імі́я к Бо́гу, тобо́ю просвіще́на, / научи́ся воспіва́ти в свой язи́к: / оте́ць на́ших Бо́же, благослове́н єси́.","Єва́нгельському словесі́ досто́їн яви́ся, о́тче Мефо́діє, / я́сно іспові́дати Тро́йцю і научи́ти конці́ всіх язи́к воспіва́ти: / оте́ць на́ших Бо́же, благослове́н єси́.","Богородичен: Із діви́чеських ложе́сн вопло́щся, / яви́ся на спасе́ніє на́ше, / ті́мже Ма́тер Твою́ ви́дівше Богоро́дицю, правові́рно вопіє́м: / оте́ць на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ / халде́йський мучи́тель / Богочесті́вим неі́стовно разжже́, / си́лою же лу́чшею спасе́ни, сія́ ви́дів, / Творцю́ і Ізба́вителю вопія́ше: / о́троци, благослові́те, / свяще́нници, воспо́йте, / лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Тобо́ю нам, пресвя́те, світ возсія́, / те́мним і омраче́нним гріхми́ лю́тими, / ти бо, я́ко світ, проше́л єси́ до за́пада, / бісо́вськую лесть і є́ресь посіка́я. / Ті́мже твою́ днесь пра́зднующе па́м'ять, всі вопіє́м: / о́троци, благослові́те, свяще́нници, воспо́йте, / лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","От восто́ка проі́де, я́ко со́лнце світоза́рноє, / лесть прогна́ бісо́вськую, Богогла́се, / ту́чами кни́жними сла́стно напої́ весь мир, / сло́во раздая́ язи́ком, вопія́: / о́троци, благослові́те, свяще́нници, воспо́йте, / лю́діє, превозносі́те во вся ві́ки.","Досто́йну ті похвалу́ кто ізрещи́ мо́жеть, / по́двиги і труди́ твоя́ почита́я? / Возгремі́, я́ко гром, во всіх конці́х, / слове́сний плод всім раздава́я, о́тче Мефо́діє, / тім, тя чту́ще, ві́рно вопіє́м: / о́троци, благослові́те, свяще́нници, воспо́йте, / лю́діє, превозносі́те во вся ві́ки.","Ілії́ рве́нієм, і кро́тостію Моїсе́ю, / і незло́бієм Дави́ду подо́б'яся, / ізря́ден при́тчами і наказа́нієм прему́др / і сла́стію прему́дро вопія́ше: / о́троци, благослові́те, свяще́нници, воспо́йте, / лю́діє, превозносі́те во вся ві́ки.","Богородичен: Черто́г ца́рський, в не́мже Христо́с полежа́, / свобо́ду челові́чеському ро́ду подая́, / ю́же пронареко́ша пречестні́ї проро́ци, / Христа́ Бо́га на́шего Преві́чную Святи́ню, / Того́ благослові́те, Марі́ю воспо́йте, лю́діє, / і превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю, / Тя іспові́дуєм, / спасе́ннії Тобо́ю, Ді́во Чи́стая, / с Безпло́тними ли́ки Тя велича́юще.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Я́ко ча́да твоя́, блаже́нне, прийми́ нас, припа́дающих ті, / і пречи́стими моли́твами свої́ми / за ни, свя́те, помоли́ся ко Го́споду.","Приспів: Святи́є равноапо́стольниє отці́ на́ші Кири́лле і Мефо́діє, молі́те Бо́га о нас.","Прийми́, Богогла́се, моле́бную ті піснь принося́щих, / і предвари́ к Бо́гу моли́твами свої́ми, / і от напа́сти і біди́ ізба́ви ни, свя́те, тебі́ велича́ющих.","Очи́сти м'я, молю́ся, твої́ми моли́твами, / Богогла́се о́тче Мефо́діє / от лю́тих гріх, і́миже м'я уязви́ враг.","Ю́же ті прино́сим мольбу́, преблаже́нне, / прийми́ із уст недосто́йних / і прилі́жно моли́ся ко Христу́ за ста́до своє́.","Богородичен: Приста́нище Тя спасе́нноє сві́дуще, / пресвято́му Твоєму́ рождеству́ ві́ровавше, / от бід ізба́вити ни Тебі́ мо́лимся."]},{"h":"Стихири на цілування, глас 8","ps":["Кири́лле, сла́вне учи́телю добро́ті, / научи́ мора́влени свої́ми язи́ки Бо́га благодари́ти, / прелага́я на слове́нський язи́к от гре́чеськаго зако́н Госпо́день / і уча́ пра́вді Єго́. / Тім ни́ні, ра́дующеся, слове́нстії наро́ди / Бо́гу сла́ву возсила́ють.","Кто мо́жеть іспові́дати чудеса́ Госпо́дні, / я́же сотвори́ сла́вним Свої́м Кири́ллом? / От я́да сараци́нськаго ізба́ви / і от тлі же го́ркия істо́рже, / утвержда́я в хоза́ріх ві́ру Госпо́дню, / і уста́ їм заключи́ язи́ком єго́, / услади́ во́ди го́ркия / і і́на ди́вная тьма́ми соді́я.","Слава, глас той самий:","О сла́дкий учи́телю Кири́лле, / о ти́хая бесе́до, / о милосе́рдноє се́рдце і у́ме прему́дрий, / о глаго́ли, сла́ждшії ме́да, / о́ними бо страни́ прелета́я, я́ко оре́л. / О втори́й Па́вле і учениче́ Петро́в, / в єго́же гра́де ізво́ли почи́ти, / пом'яни́ ни, грі́шния, ко Го́споду / і моли́твами твої́ми спаси́ ни.","І нині, Богородичен:"]},{"h":"Молитва","ps":["О пресла́внії просвіти́теліє слове́нських язи́к, святі́ї равноапо́стольнії Мефо́діє і Кири́лле, ва́ших писме́н і уче́ній сві́том просвіти́вшеся і во ві́рі Христо́вой наста́вльшеся, я́ко ча́да ко отце́м, усе́рдно ни́ні прибіга́єм і сокруше́нієм серде́чним мо́лимся: а́ще і заві́т ва́ших не соблюдо́хом, о угожде́нії бо Бо́гу небрего́хом і от бра́тняго єдиноми́слія во ві́рі отпадо́хом, оба́че я́коже дре́вле в земно́м житії́ ва́шем, си́це і ни́ні грі́шних і недосто́йних не отвраті́те тщи, но, я́ко іму́ще ве́ліє ко Го́споду дерзнове́ніє, прилі́жно Того́ молі́те, да обрати́ть нас в путь спасе́нія, да умири́ть раздо́ри єдинові́рних, да приведе́ть к єдиноми́слію отпа́дших і всіх нас ду́хом любве́ да соєдини́ть Єди́ній Святі́й, Собо́рній і Апо́стольстій Це́ркві! Ві́ми бо, я́ко мно́го мо́жеть моли́тва пра́ведних ко благосе́рдію Влади́ки. Не оста́віте у́бо нас, уни́лих і недосто́йних, чад ва́ших, ї́хже ра́ди гріхо́в па́ства ва́ша, враждо́ю разділя́єма і собла́знми іносла́вних прельща́єма, ума́лися, о́вці же слове́сния, разрева́єми, восхища́ються во́лки губи́тельними. Пода́ждьте у́бо нам моли́твами ва́шими ре́вность Правосла́вія, я́ко да оте́чеськая преда́нія до́брі сохрани́м, кано́ни церко́вния ві́рно соблюде́м, вся́ких лжеуче́ній стра́нних отбіжи́м і, та́ко в житії́ богоуго́днім преспіва́юще, жи́зні ра́йськия на Небесі́ сподо́бимся, іді́же ку́пно с ва́ми просла́вим в Тро́йці Єди́наго Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О всехва́льнії равноапо́столи Мефо́діє і Кири́лле, припа́дающе пред честно́ю іко́ною ва́шею, усе́рдно мо́лим ви: воззрі́те ми́лостивно на нас, ї́хже трудо́м ва́шим просвіти́ли єсте́, і оградите́ нас неуси́пним предста́тельством ва́шим от злих ко́зней вра́жиїх! При́зріте у́бо на виногра́д сей, єго́же насади́ли єсте́, і не преда́йте ди́веєму ве́прю озоба́ти єго́. Сохрані́те, святі́ї уго́дниці Бо́жії, Це́рков на́шу Правосла́вную, ю́же ви назда́ли єсте́ на краєуго́льном Ка́мені, Христе́, я́ко да бу́деть недви́жима, но да разси́п'яться о Ка́мень сей во́лни вся́каго малові́рія. Укріпі́те па́стирей на́ших во всіх доброді́теліх і в по́двизі пропові́данія, вразумі́те же пасо́мих, во є́же послу́шати гла́са їх. Сохрані́те вся страни́ слове́нськия от вся́каго оскуді́нія, от огня́ і меча́, от смертоно́сния я́зви і от вся́каго зла. Усли́шіте і вся́каго челові́ка, с ві́рою к вам приходя́щаго і благода́тния по́мощі ва́шея тре́бующаго. В стра́шний же час сме́ртний предста́ніте всім нам блазі́ї хода́таї і те́мних зра́ков де́монських прогони́теліє, да в ми́рі і покая́нії сконча́єше земно́є по́прище, дости́гнем ві́чних благ наслажде́нія і ку́пно с ва́ми просла́вим Пресвяту́ю Тро́йцю – Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон священномученику Іларіону Верейському","e":"Canon to the Hieromartyr Hilarion of Vereya","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Волно́ю морсько́ю скри́вшаго дре́вле гони́теля мучи́теля под земле́ю скри́ша спасе́нних о́троци: но ми я́ко отрокови́ці, Го́сподеві пої́м, сла́вно бо просла́вися.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Іларіо́не, всечестни́й святи́телю, по і́мені твоєму́ і житіє́ твоє́ бисть, тишину́ бо моли́твенную внутр себі́ імі́я, ра́дость пасха́льную всім яви́л єси́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Лесть гони́телей твої́х отве́ргнув, муче́нія лю́таго не убоя́лся єси́, свя́те, Христа́ же пред судія́ми непра́ведними му́жеськи іспові́дав, сла́вою небе́сною просла́вился єси́.","А́нгелов собесі́дниче, Іларіо́не преподо́бне, во огра́ді до́ма Живонача́льния Тро́йці, пожи́л єси́, іді́же посто́м і моли́твою ду́шу очи́стив, богові́дініє стяжа́л єси́.","Ре́вность по Бо́зі імі́я, святи́телю, богобо́рцев сло́вом облича́л єси́, та́кожде і єрети́чеських мудрова́ній не терп'я́, нечести́вия із оби́телей і хра́мов ізгоня́л єси́, ка́ющіяся же ко спасе́нію приводи́л єси́.","Богородичен: Іни́я по́мощі не і́мами, ра́зві Тебе́, Влади́чице, Ти нам помози́ мо́ря житія́ сего́ пучи́ну я́ко по су́ху проіти́ неіскуше́нно от злих."]},{"h":"Пісня 3","ps":["Ірмос: Тебі́ на вода́х пові́сившаго всю зе́млю неодержи́мо, твар ви́дівши на ло́бнім ви́сима, у́жасом мно́гим содрога́шеся, ність свят, ра́зві Тебі́, Го́споди, взива́ющи.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","От ю́ности чистоту́ возлюби́в, Іларіо́не ди́вний, ді́вственник душе́ю і ті́лом преби́л єси́ і, не пожела́в порабо́тати тва́ри па́че Творця́, на землі́ невеще́ственноє житіє́ показа́л єси́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Небе́сний челові́че, земни́й А́нгеле, Іларіо́не прему́дре, святи́м отце́м житіє́м послі́дуя, за Христа́ ду́шу твою́ положи́л єси́ і землі́ Українськия украше́ніє яви́лся єси́.","Архієре́ю Бо́жий, Іларіо́не свя́те, кро́тостію, смире́нієм і терпі́нієм, па́че же любо́вію преукра́шен бил єси́, сего́ ра́ди за мучи́телей твої́х моли́лся єси́, Христу́ Бо́гу подража́я.","Свята́го Ду́ха дар стяжа́в, Си́ну Бо́жию, крест взем, послі́довал єси́, і во́лю Отця́ Небе́снаго іспо́лнил єси́, Іларіо́не блаже́нне, Тро́йці Святи́я і́стинний почита́телю.","Богородичен: Лі́ствице Небе́сная, Є́юже сни́де Бог, до́лу лежа́щеє єстество́ на́ше к небесі́ возво́диши, ті́мже Тя, Пресвята́я Богоро́дице, любо́вію непреста́нно велича́єм."]},{"h":"Сідален, глас 7","ps":["Священному́чениче сла́вне Іларіо́не, архієре́ю і дру́же Христо́в, ти, в темни́ці заключе́н бив, не восхоті́л єси́ слуга́м анти́христовим поклони́тися, я́коже і му́ченици дре́вле не возжела́ша же́ртву і́дольськую принести́. Сего́ ра́ди помози́ нам моли́твами твої́ми стрі́ли вра́жія отрази́ти і ко́зні дия́вольськия разори́ти, єди́наго же Христа́ расп'я́таго ви́ну очеси́ у́мними зрі́ти і Тому́ із глубини́ серде́чния взива́ти: Го́споди, Ісу́се Христе́, поми́луй нас.","Богородичен: Предста́тельнице і Моли́твеннице на́ша, Пресвята́я Влади́чице, умоли́ Си́на Твоєго́ і Бо́га, єгда́ ся́деть суди́ти живи́м і ме́ртвим, да прости́ть гріхи́ і беззако́нія на́ша, і сподо́бит ни Ца́рствія Небе́снаго."]},{"h":"Пісня 4","ps":["Ірмос: На Кресті́ Твоє́ Боже́ственноє істоща́ніє прови́дя Авваку́м, ужа́сся вопія́ше: Ти си́льних пресі́кл єси́ держа́ву, Бла́же, приобща́яся су́щим во а́ді, я́ко Всеси́лен.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Апо́стольськоє сло́во ісполня́я, в безбо́жнім ми́рі Христа́ пропові́дал єси́, Іларіо́не богому́дре, і Це́рков Єго́ от волко́в, расхища́ющих ю, неуси́пно охраня́л єси́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Вели́ка та́йна єсть Це́ркве, я́ко неві́сти Христо́ви, ю́же ти, Іларіо́не, чи́стим се́рдцем узрі́л єси́ і я́сно провозгласи́л єси́.","Небе́сния любве́ да́ра удосто́єн бив, Іларіо́не, Бо́га Тро́йцю во Єди́ниці, І́же єсть Люби́, іспові́дал єси́ і о Це́ркві Святі́й, я́же єсть любве́ єдине́ніє, богосло́вствовал єси́.","Адама́нт ві́ри бив і оте́чеських заві́тов храни́тель, святи́телю Іларіо́не, лука́вими уче́нії не смуща́єм, Богоро́дицю Чи́стую, я́ко Ді́ву і Ма́тер, просла́вил єси́.","Богородичен: Голго́фі предстоя́щи, Ма́тер Бо́жия ско́рбно взива́ше: уви́ Мні, Си́не Мой! Ка́ко на Кресті́ ви́сиши, зе́млю на вода́х пові́сивий? Ка́ко стра́сті терпи́ши, прише́дий спасти́ мир?"]},{"h":"Пісня 5","ps":["Ірмос: Богоявле́нія Твоєго́, Христе́, к нам ми́лостивно би́вшаго, Іса́їя світ ви́дів невече́рній, із но́щі у́треневав взива́ше: воскре́снуть ме́ртвії, і воста́нуть су́щії во гробі́х, і всі земноро́днії возра́дуються.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","О, святи́телю Христо́в Іларіо́не, помози́ нам нощ житія́ сего́ ско́рбнаго в терпі́нії і покая́нії без поро́ка прейти́, і ра́дости сві́та невече́рняго сподо́битися.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Христо́вим па́стирем пра́вило бил єси́, Іларіо́не, і наста́вник терпіли́вий, не то́кмо сло́вом, но і ді́лом о́браз їм показу́я, і благода́тію, тебі́ от Бо́га да́нною, укріпля́я.","Ра́дости духо́вния іспо́лнен, Іларіо́не, ше́ствовал єси́ путе́м ті́сним і приско́рбним, всіх уча́ Христу́ сраспина́тися, даби́ с Ним воскре́снути.","І́ноці оби́телі Сре́тенськия днесь прославля́ють архипа́стиря Іларіо́на, служи́теля благогові́йнаго Ді́ви Пренепоро́чния, сла́ву Влади́мирському о́бразу Єя́ досто́йно возда́вшаго і тім преще́нія безбо́жних презрі́вшаго.","Богородичен: Сла́вим Тя немо́лчно, Влади́чице, і ко іко́ні Твоє́й Влади́мирстей припа́даєм, взива́юще: покри́й град Київ от тьми гріхо́вния і безбо́жния і спаси́ душі́ на́ша."]},{"h":"Пісня 6","ps":["Ірмос: Ять бисть, но не удержа́н в пе́рсіх ки́тових Іо́на: Твой бо о́браз нося́, Страда́вшаго і погребе́нію Да́вшагося, я́ко от черто́га от зві́ря ізи́де, приглаша́ше же кустоді́ї: храня́щії су́єтная і ло́жная, ми́лость сію́ оста́вили єсте́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Ти, ієра́рше честни́й, о устроє́нії Це́ркве Українськия ревну́я, із глубини́ душе́вния Христу́ Бо́гу взива́л єси́: Го́споди, чин патріа́ршій возста́ви і єдиноми́сліє в Це́ркві соблюди́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","О, Іларіо́не блаже́нне, ти, Собо́ру муже́й церко́вних предстоя́, му́дрим сло́вом, благода́тію растворе́нним, призва́л єси́ їх патріа́ршеством Це́рков Українськую па́ки украси́ти і по достоя́нію возвели́чити.","Всечестни́й Іларіо́не святи́телю, ві́рний сподви́жник Ти́хона патріа́рха яви́лся єси́, Це́рков от безбо́жних власте́й і раздира́ющих хито́н Христо́в до́блественне охраня́я.","Архієре́я достосла́внаго Іларіо́на Вере́йськаго днесь, ві́рнії лю́діє, благоче́стно восхва́лим, той бо град Київ от поновля́ющих і ізменя́ющих чин церко́вний огради́ і ві́рних в благоче́стії утверди́.","Богородичен: Ра́дуйся, Цари́це Небе́сная, Патріа́рхов правосла́вних Похвало́, оби́телей святи́х неруши́мая Стіно́, гра́да же первопресто́льнаго і страни́ на́шея Утвержде́ніє."]},{"h":"Кондак, глас 2","ps":["Сла́ву ми́ра сего́ оста́вив, Христу́ до́блественне послі́довал єси́ і, святи́тельськоє служе́ніє восприї́м, вінце́м му́ченичества украси́лся єси́, і ни́ні, Престо́лу Бо́жию предстоя́, моли́ся, Іларіо́не, ієра́рше прему́дре, спасти́ся душа́м на́шим."]},{"h":"Ікос","ps":["Сві́том боже́ственния му́дрости, Іларіо́не святи́й, іспо́лни ум мой помраче́нний, да восхвалю́ житіє́ твоє́, взива́я си́це:","Ра́дуйся, Христа́ Бо́га ві́рний служи́телю;","ра́дуйся, Це́ркве Єго́ і́стинний іспові́дниче.","Ра́дуйся, ю́них до́брий наста́вниче;","ра́дуйся, Сло́ва Бо́жия ізря́дний пропові́дниче.","Ра́дуйся, ві́рним путь спасе́нія возвісти́вий;","ра́дуйся, хитросплете́нія су́єтная посрами́вий.","Ра́дуйся, патріа́ршества ревни́телю;","ра́дуйся, оте́чеських заві́тов ди́вний храни́телю.","Ра́дуйся, Іларіо́не, Це́ркве на́шея сла́во і украше́ніє."]},{"h":"Пісня 7","ps":["Ірмос: Неізрече́нноє чу́до, в пе́щі ізба́вивий преподо́бния о́троки із пла́мене, во гро́бі мертв бездиха́нен полага́ється, во спасе́ніє нас пою́щих: Ізба́вителю Бо́же, благослове́н єси́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","А́ще не яви́лася би ве́лія ре́вность новому́чеников Це́ркве Українськия, поги́бла би ві́ра Правосла́вная во оте́честві на́шем. Ти же, святи́телю Іларіо́не, с ни́ми страда́нія претерпіва́я, взива́л єси́: Ізба́вителю Бо́же, благослове́н єси́.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Труди́ і по́двиги, священному́чениче Іларіо́не, богоуго́дні поне́сл єси́, і́миже разори́тели Це́ркве Христо́ви посра́млени би́ша, ві́рнії же восклиця́ху: Ізба́вителю Бо́же, благослове́н єси́.","Наста́вник мона́хом бив, Іларіо́не свя́те, ти во вре́м'я лихолі́тія оби́тель Сре́тенськую от нечести́вих защища́л єси́. І ни́ні та́мо моща́ми почива́єши, і́ноков єя́ науча́я взива́ти: Ізба́вителю Бо́же, благослове́н єси́.","Іларіо́не свя́те, Це́ркве Українськия похвало́, сподо́би нас, немощни́х і грі́шних, моли́твами твої́ми от пла́мене страсте́й ізба́витися і от іскуше́ній невреди́ми сохрани́тися, Го́сподеві взива́юще: Ізба́вителю Бо́же, благослове́н єси́.","Богородичен: Кто Тебі́ не просла́вить, Пресвята́я Ді́во, Ти бо єси́ Роса́ небе́сная, гріхо́вний пла́мень угаша́ющая і ві́рния благода́тію ісполня́ющая. Ті́мже Тебе́ вопіє́м: ізба́ви нас ві́чнаго осужде́нія і спаси́ душі́ на́ша."]},{"h":"Пісня 8","ps":["Ірмос: Ужасни́ся боя́йся не́бо, і да подви́жаться основа́нія землі́: се бо, в мертвеці́х вміня́ється во ви́шніх Живи́й, і во гроб мал странноприє́млеться: Єго́же, о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","А́гнця Бо́жия возлюби́в і ду́ха ми́ра сего́ отве́ргнув, єди́наго і́стиннаго Бо́га служи́тель преби́л єси́, Іларіо́не сла́вне, ни́ні же на Небесі́ Влади́ці всіх предстої́ши. Єго́же, о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Внегда́ вся власть тьми на Це́рков Українськую ополчи́ся, тогда́ ти, Іларіо́не, ду́хом крі́пкий, Христа́ іспові́дати не убоя́лся єси́. Єго́же, о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","О, свяще́нная і спаси́тельная нощ Па́схи, єгда́ ти, святи́телю Христо́в, во у́зах солове́цьких возгласи́: да воскре́снеть Бог! Єго́же, о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Солове́цькая земле́ многострада́льная, возра́дуйся і возвесели́ся: Іларіо́н бо преди́вний с со́нмом новому́чеников на небесі́х за Україну Святую мо́лить ни́ні Царя́ Сла́ви. Єго́же, о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Богородичен: Пресвята́я Ді́во, на Небеса́ к Си́ну Твоєму́ возшла́ єси́ і нас, си́рих, на землі́ не оста́вила єси́; покри́й честни́м Твої́м омофо́ром оби́телі і гра́ди на́ша, жизнь ві́чную подаю́щи всім воспіва́ющим Тя."]},{"h":"Пісня 9","ps":["Ірмос: Не рида́й Мене́, Ма́ти, зря́щи во гро́бі, Єго́же во чре́ві без сі́мене зачала́ єси́ Си́на: воста́ну бо і просла́влюся, і вознесу́ со сла́вою, непреста́нно, я́ко Бог, ві́рою і любо́вію Тя велича́ющия.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Єгда́ во враче́бниці темни́чній Петро́ва гра́да огне́вицею ті́ло твоє́ пали́мо бя́ше, душа́ твоя́, я́ко на вода́х упокоє́нія ра́достію іспо́лнися, і, сіте́й кня́зя ми́ра сего́ ізбі́гнув, ко Христу́ оти́де.","Приспів: Священному́чениче Іларіо́не, моли́ Бо́га о нас.","Во́їне Христо́в, Іларіо́не сла́вне, ти Го́спода в житії́ твоє́м небоя́зненно іспові́дав, кончи́ни блаже́нния сподо́бился єси́. Ті́мже взива́єм: моли́ ми́лостиваго Бо́га, да пода́сть нам во і́стинній ві́рі живо́т свой сконча́ти.","А́нгельськоє пі́ніє і звон пасха́льний дру́зі твої́ і сро́дниці, усли́шавше, возра́довашася, Іларіо́не, уразумі́ша бо, я́ко душа́ твоя́ чи́стая на не́бо восхо́д соверша́ше.","Єгда́ ті́ло твоє́ многоболі́зненноє во гро́бі положе́но бисть, ча́да твоя́ духо́вная со слеза́ми к тебі́ взива́ху: моли́ся о нас, пра́ведниче, у престо́ла Госпо́дня.","Богородичен: Ма́ти Безневі́стная, не лиши́ нас Твоєго́ заступле́нія, умоли́ Милосе́рдаго Судію́ оправда́ти ни, ві́рою і любо́вію Тя велича́ющих."]},{"h":"Світилен","ps":["Всі святі́ї Це́ркве Українськия ни́ні торжеству́ють сві́тло, священному́ченика і архієре́я Іларіо́на зря́ще, с ни́ми Тро́йце Боже́ственній моли́твенно предстоя́щаго.","Богородичен: Пресвята́я Богоро́дице, ди́вноє селе́ніє Бо́га і Сло́ва, помози́ нам, Ми́лостивая, моли́твами Твої́ми терпі́ніє і упова́ніє стяжа́ти, і спасе́ніє улучи́ти."]}],"notes":[]},{"u":"Канон святому мученику Уару Єгипетському (інший канон)","e":"Canon to the Holy Martyr Uar of Egypt (another canon)","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Яви́лся єси́ на висоті́ Христо́ви Це́ркве, Уа́ре, я́коже со́лнце сві́тлоє, блиста́ньми просвіща́я твої́х боре́ній, блаже́нне, земна́я ісполне́нія.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Боже́ственния любве́, всеблаже́нне, об'я́т сла́дким раче́нієм, отве́рглся єси́ себе́ і ко вся́кой му́ці пло́тстій устреми́лся єси́, крі́пко подвиза́вся.","Сми́сленно боже́ственних подви́жник ю́зами связа́в себі́, страстоте́рпче, і ле́стния разори́л єси́ у́зи крі́пким терпі́нієм мно́гих мук.","Богородичен: Пресу́щественноє Сло́во во Твоє́м чре́ві па́че сло́ва всели́ся, і роди́вся боголі́пно, му́ченичеськия ли́ки, Чи́стая, приведе́, с ни́миже пісносло́вим Тя."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Вшел єси́ ра́зумом крі́пким в му́жественния по́двиги, утверди́вся наде́ждами бу́дущих благи́х і му́чеников Христо́вих всему́дрими, блаже́нне, поуче́нії.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Во́їнство святи́х страстоте́рпець, стра́ждущих зако́нні зря, о́ніх показа́л єси́ му́жеськую крі́пость, приміша́яся многообра́зним, Уа́ре, му́кам.","В полці́ свяще́ннім, Уа́ре, я́ко до́блій во́їн, обрі́лся єси́, і ссік мно́жество му́жества мече́м, му́дре, ра́тним, побі́дами сла́вим.","Богородичен: Ді́во Ма́ти Бо́жия, моєго́ уни́нія глубоча́йшую тьму і о́блаки страсте́й просвіще́нієм, є́же в Тебі́, молю́ Тя, благода́ті, отжени́."]},{"h":"Сідален, глас 1","ps":["Стра́сті честни́х ви́дів му́чеников і тіх лобза́в у́зи любо́вію, на висоту́ восте́кл єси́ свиді́тельства, всечу́дне, на дре́ві бо пові́шен, ра́ни претерпі́л єси́, до́ндеже в ру́ки Госпо́дні ду́ха пре́дал єси́.","Слава, і нині, Богородичен: Упова́ніє христия́н, Пресвята́я Ді́во, Єго́же родила́ єси́ Бо́га, па́че ума́ і сло́ва, непреста́нно моли́ о воспіва́ющих Тя, пода́ти оставле́ніє гріхо́в на́ших всіх і ісправле́ніє житія́, ві́рою і любо́вію при́сно сла́в'ящим Тя.","Хрестобогородичен: Зря́щи Тя, Христе́, Всенепоро́чная Ма́ти, ме́ртва на Кресті́ просте́рта, вопія́ше: Си́не Мой, Собезнача́льне Отцю́ і Ду́ху, что неізрече́нноє Твоє́ сіє́ смотре́ніє, і́мже спасл єси́ пречи́стих рук Твої́х, Ще́дре, созда́ніє?"]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи, от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Святи́ми я́звами удобря́єм, красні́йшій яви́лся єси́, і Бо́гу, Уа́ре, возлю́блен, Вінча́вшему твой верх, досточу́дне.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","На кресті́, сла́вне, растяза́єм і на землі́ простира́єм, лю́тия болі́зні претерпі́л єси́. Тім неболі́зненную жизнь наслі́довал єси́, веселя́ся.","Зако́нно ви́дяще боже́ственнії му́ченици стра́ждуща тя, блаже́нне, терпі́нія словеси́ укріпля́ху, с ни́миже стра́сті до́лгия соверши́в, ублажи́лся єси́.","Хвала́ми вінча́єм боже́ственния му́ченики, я́же вінча́ благода́ть Боже́ственная Боже́ственними ув'язе́нії, низло́жших вра́жия висо́кая мудрова́нія.","Богородичен: От ти́ни страсте́й, Влади́чице, возведи́, і стра́стних помишле́ній, отчужда́ющих м'я Бо́га Єди́наго Чи́стаго, да ві́рою ублажа́ю Тя."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Укріпля́єшися манове́ньми Боже́ственними і неосла́бная терза́нія терпи́ши до́блим сми́слом, Уа́ре, растерза́я го́рдаго се́рдце, зло́бу соді́лавшаго.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Сла́вний му́ченик, ви́дя отпа́дающия на зе́млю своя́ пло́ті, ра́довашеся, ві́чнующая ума́ сві́тлостію і Боже́ственная возда́нія предпрозира́я.","Пою́ Тя, Го́споди Бо́же, і славосло́влю, і покланя́юся, благи́х сподобля́яся, угото́ванних Тебі́ возлю́бльшим, — му́ченик в страда́нії те́плі зов'я́ше.","Богородичен: Я́вльшися херуви́м і серафи́м я́ко воі́стину святі́йши, Всенепоро́чная, вся, ві́рно Тя ни́ні освяща́ющия, освяти́ і спаси́ хода́тайством Твої́м."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Глаго́лов небре́гл єси́ пребеззако́ннаго врага́ і пла́мень претерпі́л єси́ нестерпи́мих болі́зней терпіли́вно, многострада́льне Уа́ре, моле́бниче о хва́лящих тя ві́рою.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Не преста́ше мучи́тель пребезу́мний, ра́нами неми́лостивно сдробля́я тя, до́ндеже в ру́ки Бо́жия свяще́нную твою́ ду́шу преда́л єси́, добро́тами просві́щшуся по́двиг твої́х.","Возви́сился єси́, подо́б'яся на дре́ві Христу́, і на том ви́ся, твою́ ду́шу пре́дал єси́ Бо́гу, тя вінчава́ющу, страстоте́рпче, зако́нно до́блествовавша.","Богородичен: Упра́ви, Влади́чице, в пучи́ні лю́тих, обурева́ємую всегда́ смире́нную ду́шу мою́, і к ти́хому приста́нищу напра́ви, несомні́нним ра́зумом Тя блажа́щую."]},{"h":"Кондак, глас 4","ps":["Христу́ послі́дуя, му́чениче Уа́ре, Того́ іспи́в ча́шу, і муче́нія вінце́м ув'язе́ся, і со а́нгели ликовству́єши: моли́ непреста́нно за ду́ші на́ша."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла А́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увіща́ вопи́ти: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Просвіще́на тя подвиго́в приложе́ньми, предо́брая Клеопа́тра, Уа́ре, ску́тала єсть, обрі́тши сла́ву тобо́ю, ві́ри досто́йну я́ві, ю́же показа́ те́плі в твоє́ сконча́ніє.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Ізлива́ющи на тя сле́зи, і ми́ри тя честни́ми помазу́ющи, сокрива́єть тя под земле́ю всечестна́я жена́, погре́бшаго пре́лесть лука́вую і із гро́ба блиста́ньми просвіща́юща нас.","Не престая́ше, преподо́бне, угожда́ющи тебі́ Христо́ву уго́днику, приснопа́м'ятная, до́ндеже яви́лся єси́ хода́тай єй, му́дре, Ца́рствія небе́снаго, єго́же сподо́бися тобо́ю с любе́знійшим си́ном.","Богородичен: Сокруше́на м'я безчи́сленними согріше́нії, Ді́во, хода́тайством Твої́м обнови́, уврачу́ющи мою́ ду́шу і сло́во подаю́щи, вопи́ти: благослове́нна, Я́же Бо́га пло́тію ро́ждшая."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. Тя превозно́сим во вся ві́ки.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Ма́терніх послу́шав, му́чениче, моле́б, небе́сному во́їнству сві́тло во́їнствуя, о́трока честна́го і твоєго́ неотсту́пна показа́л єси́ благосла́вія неізрече́нним милосе́рдієм.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","От Єги́пта тя бога́тство я́коже многоці́нноє принесе́, му́чениче, разбогатя́щи многоці́нними дарми́, Клеопа́тра, целе́нії всю Палести́ну, любо́вію тя почита́ющую.","Веселя́ся, по́двиги твоя́ соверши́л єси́, во́їне до́блій Вседержи́теля, і я́ко побіди́тель от Него́ вінча́лся єси́, Уа́ре всеблаже́нне, му́чеников вели́кая сла́во.","Богородичен: Гріхи́ прилага́ю ко гріхо́м і бу́дущаго не бою́ся Стра́шнаго Суда́: побіди́, Чи́стая, душі́ моєя́ осліпле́ніє, і мольбо́ю Твоє́ю обрати́вши, м'я спаси́."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни а́нгельстії взира́ти; Тобо́ю бо, Всечи́стая, яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с небе́сними во́ї, Тя ублажа́єм.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Крі́пость низложи́л єси́ ратобо́рця, Боже́ственною я́ві си́лою препоя́сався, страда́льче до́блій Уа́ре. Тім тя хва́лим, врачева́ніє оби́льноє от твої́х моще́й, ві́рнії, почерпа́юще.","Приспів: Святи́й му́чениче Уа́ре, моли́ Бо́га о нас.","Я́ко світ, я́ко у́тро, я́ко вели́коє со́лнце в земни́я простре́ся па́м'ять твоя́ конці́, світоно́сними просвіща́ющи сія́ньми твої́х честни́х по́двиг вся, прехва́льне, і мрак серде́ць отгоня́щи.","С тобо́ю сія́юща ви́дівши сла́вою мно́гою своєго́ си́на чадолюби́вая, всіх Бо́га велича́ше; тебі́ же і́скреннійше, му́чениче, сла́в'яще, велича́йшаго предста́теля, я́вственно обогати́вшися.","Земля́, на не́йже терпіли́війшеє ті́ло твоє́, му́дре, лежи́ть, боже́ственне освяти́ся, но даждь моли́твами твої́ми нам разріше́ніє гріхо́в, житія́ ісправле́ніє, Уа́ре, і всіх неудо́бних ізбавле́ніє.","Богородичен: Я́влься, Ді́во, із Тебе́ Госпо́дь, сві́тлаго о́блака, єги́петськия куми́ри вся́чеськой па́губі предаде́; мно́жество же страстоте́рпцев Сего́ носи́ти сподо́би, Сего́ подража́телі честни́м Єго́ страда́нієм."]}],"notes":[]},{"u":"Канон святителю Луці, сповіднику, архієпископу Кримському","e":"Canon to St Luke, Confessor, Archbishop of Crimea","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Ди́вному Бо́гу вели́чія принесе́м і великолі́пно с на́ми, да воспоє́ть земля́ і не́бо я́сно сла́ву Єго́.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Во дні гоне́ній тя́жких на Це́рков Українськую свяще́нний сан во гра́ді Ташке́нте небоя́зненно прия́л єси́, блаже́нне Луко́, і отсту́пники, нововведе́нія льсти́вая вводя́щия, му́жественні облича́л єси́, принося́ вели́чіє Бо́гу і воспіва́я сла́ву Єго́.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Яви́лся єси́ па́стві твоє́й, іспові́дниче Христо́в, столп непоколеби́мий і защи́тник крі́пкий, боля́щим ісціле́ніє, скорб'я́щим утіше́ніє, Бо́га велича́я і воспіва́я сла́ву Єго́.","Вседержи́теля і Го́спода о нас моли́, святи́телю Луко́, дарова́ти нам оставле́ніє прегріше́ній, да с тобо́ю ди́внаго Бо́га возвели́чим і воспоє́м сла́ву Єго́.","Богородичен: Тя призива́ющим, Богороди́тельнице Пречи́стая, яви́лася єси́ спаси́тельноє приста́нище і покро́в. Ті́мже любо́вію зове́м Ті: Влади́чице, спаси́ ни і научи́ ди́вному Бо́гу вели́чія приноси́ти і воспіва́ти сла́ву Єго́."]},{"h":"Пісня 3","ps":["Ірмос: Уподо́би м'я, Христе́, у́мно го́ре Сіо́нстій, возви́сивий і утверди́вий в наде́жді о Тебі́ і іска́павий ро́су благода́ті, Человіколю́бче.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Єгда́ в Сиби́рськую зе́млю ізгна́н бил єси́, святи́телю, тогда́ мно́гія гра́ди єя́ апо́стольськими труди́ просвіти́л єси́ і, тіле́сния неду́ги врачу́я, о лю́діх Бо́гу моли́лся єси́, да істочи́ть на них ро́су благода́ті Своєя́, я́ко Человіколю́бець.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Руко́ю твоє́ю святи́тельською о́чі сліпи́м ісціли́л єси́, врачу́ преди́вний, та́же і ду́ші їх Сві́том Христо́вим просвіти́л єси́, моля́ся, да істочи́ть на них Госпо́дь ро́су благода́ті Своєя́, я́ко Человіколю́бець.","Твої́ми поуче́нії, святи́телю Луко́, я́ко до́брий па́стир, указа́л єси́ лю́дем путь в Ца́рство Небе́сноє. Сего́ ра́ди сла́вою от Бо́га увінча́лся єси́, Єго́же моли́, да низпо́слеть і нам ро́су благода́ті Своєя́, я́ко Человіколю́бець.","Богородичен: Люби́ти у́бо Тя, Пречи́стая Богома́ти, і пі́сньми прославля́ти науча́єть нас вели́кий Арха́нгел, сего́ ра́ди вопіє́м Ті, Богоневі́сто: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю; ра́дуйся, Ра́досте А́нгелов і всіх челові́ков."]},{"h":"Сідален, глас 8","ps":["О́чі серде́чнеї ко Го́споду ви́ну імі́я, іспові́дник дерзнове́нний ві́ри Христо́ви яви́лся єси́, о́тче Луко́, і, си́лою слове́с боже́ственних полки́ безбо́жних отгоня́я, Кри́мськую па́ству му́дре упа́сл єси́. Ті́мже по кончи́ні в Небе́сния оби́телі со сла́вою водвори́лся єси́, святи́телю блаже́нне. Моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим всечестну́ю па́м'ять твою́.","Слава, і нині: Тя Приста́нище і Сті́ну, Прибі́жище і Наде́жду, Покро́в і Заступле́ніє те́плоє і́мами, к Тебі́ притека́єм і вопіє́м прилі́жно: спаси́, Богоро́дице, упова́ющия на Тя і от прегріше́ній ізба́ви."]},{"h":"Пісня 4","ps":["Ірмос: Всіл єси́ на ко́ни, апо́столи Твоя́, Го́споди, і прия́л єси́ рука́ма Твої́ма узди́ їх, і спасе́ніє бисть їжде́ніє Твоє́ ві́рно пою́щим: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Ю́же стяжа́л єси́ честно́ю Твоє́ю Кро́вію, Це́рков Твою́, Христе́, утверди́ і напра́ви на путь ми́ра, та́ко воздиха́л єси́, святи́телю о́тче Луко́, преподо́бнії твої́ ру́ці го́ре воздіва́я.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Любо́в Христо́ву в денноно́щних труді́х твої́х яви́л єси́, святи́телю: неду́жних безме́здно врачу́я, вдов і си́рих ми́лостивно пита́я, согріша́ющих кро́тко вразумля́я, унива́ющих і отчаява́ємих оте́чеськи утіша́я, о ни́хже і Же́ртву безкро́вную благогові́йно Бо́гу принося́.","Ні глад, ні мраз, ні темни́чная заключе́нія, ні безче́стія, ні му́ки, ні са́мая смерть возмого́ша разлучи́ти тя, святи́телю, от любве́ Христо́ви, ти бо, во ізгна́нії сий і преді́ли землі́ Українськия обходя́, лю́дем єя́ о́браз па́стиря до́браго яви́л єси́ і, я́ко столп непоколеби́мий пребива́я, іспові́дник ві́рен наре́клся єси́.","Богородичен: Крі́пость на́ша Ти єси́, Пречи́стая Богома́ти, Твої́ми бо мольба́ми ізба́вихомся всі от страсте́й і бід, обстоя́ній і неду́гов многообра́зних, Спа́су Христу́ зову́ще: сла́ва си́лі Твоє́й, Го́споди."]},{"h":"Пісня 5","ps":["Ірмос: Повелі́нія Твоя́ просвіще́нієм, Христе́ Бо́же, я́ко Благ, показа́л єси́, зане́, Світода́вче, от но́щі у́тренююще, сла́ву возсила́єм.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Єди́ницю в Тро́йці, Трийпоста́сноє Божество́, богосло́вил єси́, Луко́ блаже́нне, і трієди́ний соста́в челові́чеськаго єстества́ писа́нії твої́ми із'ясни́л єси́.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Єгда́ іспита́ніє ра́тноє при́йде на зе́млю на́шу, тогда́ ти, святи́телю, во враче́бниці гра́да Красноя́рська, враче́бноє іску́сство прилага́я, мно́гія во́їни от неісці́льних ран ісціли́л єси́ і к жи́зні возврати́л єси́.","Словеса́ похва́льная прийми́ ни́ні от нас, недосто́йних чад твої́х, святи́телю Луко́, і моли́ Христа́ Бо́га, да ізба́вить нас шу́їяго стоя́нія і сподо́бит Небе́снаго Ца́рствія Своєго́.","Богородичен: Єди́на Чи́стая, Богороди́тельнице, не пре́зри моле́ній раб Твої́х, но уго́дника Твоєго́ ра́ди принеси́ сія́ ко престо́лу Си́на Твоєго́, да спасе́ть ду́ші на́ша."]},{"h":"Пісня 6","ps":["Ірмос: Отве́ргл м'я єси́ во глубини́ се́рдця морська́го, і ви́діх чудеса́ Твоя́, Го́споди.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Раздава́я послі́дняя твоя́ і попече́ніє о неіму́щих імі́я, сироти́ і вдо́вия с любо́вію пита́л єси́, Ми́лостивому Спа́су подража́я.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Ду́хом ві́ри пламені́я, і́стинноє благоче́стіє ві́рним явля́л єси́, святи́телю Луко́, і, ієре́ї до́брі назира́я, к ді́ланію па́стирському тіх наставля́л єси́.","Не отре́клся єси́ креста́ Госпо́дня во многотру́днем житії́ твоє́м, архієре́ю Бо́жий, і ни́ні архипа́стирем на́шим моли́твами твої́ми помози́, да пра́во пра́в'ять сло́во Боже́ственния І́стини.","Богородичен: Отрокови́це Богоізбра́нная, Ді́во Марі́є, восхваля́єм Тя всі і ві́рно взива́єм: моле́ніє на́ше прийми́ і проше́нія ско́ро іспо́лни."]},{"h":"Кондак, глас 1","ps":["Я́ко звізда́ всесві́тлая, в нощі́ безбо́жия доброді́тельми просія́л єси́ і, от гони́телей мно́го пострада́в, непоколеби́м ві́рою преби́л єси́, враче́бною же му́дростію укра́шен, мно́гия лю́ди ісціли́л єси́. Сего́ ра́ди с любо́вію вопіє́м ті: ра́дуйся, добропобі́дний іспові́дниче, ра́дуйся, о́тче святи́телю Луко́, ра́дуйся, землі́ Українськия похвало́ і утвержде́ніє."]},{"h":"Ікос","ps":["Іспові́данієм тве́рдим Бо́га просла́вив, сі́ятель духо́вних доброді́телей яви́лся єси́, Луко́ прехва́льне, і, я́ко архипа́стир і учи́тель благоче́стія, нече́стія ре́вностний іскорени́тель показа́лся єси́, жизнь же в по́двизіх і труді́х мно́гих соверши́в, віне́ць неув'яда́ємий от Го́спода прия́л єси́. Сего́ ра́ди с любо́вію вопіє́м ті: ра́дуйся, добропобі́дний іспові́дниче, ра́дуйся, о́тче святи́телю Луко́, ра́дуйся, землі́ Українськия похвало́ і утвержде́ніє."]},{"h":"Пісня 7","ps":["Ірмос: В нача́лі зе́млю основа́вий і Небеса́ сло́вом утверди́вий, благослове́н єси́ во ві́ки, Го́споди, Бо́же оте́ць на́ших.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Єва́нгельськи Христу́ послі́довав, о́тче Луко́, єле́єм любве́ врачева́л єси́ лю́ди стра́ждущия і боля́щия і, сло́во Бо́жиє возвіща́я, святи́тельськи потруди́лся єси́, да прославля́ють ві́рная ча́да Сотво́ршаго вся Го́спода, воспіва́юще: благослове́н єси́ во ві́ки, Бо́же оте́ць на́ших.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Па́стир до́брий слове́сному ста́ду твоєму́ бил єси́, святи́телю Луко́, ду́шу твою́ за него́ при́сно положи́ти гото́вий. Ті́мже яви́лся єси́ оби́димим засту́пник непреобори́мий, пра́вди Бо́жия ревни́тель неустраши́мий, си́льних ми́ра сего́ кро́ткий обличи́тель, Го́споду воспіва́я: благослове́н єси́ во ві́ки, Бо́же оте́ць на́ших.","Ра́довахуся лю́діє гра́да Симферо́поля, зря́ще тя, о́тче Луко́, сві́тлостію са́на святи́тельськаго облече́на і престо́лу благода́ті Бо́жия в моли́тві предстоя́ща. Ти же, по апо́столу, вся всім бив, мно́гія ко Христу́ приве́л єси́, і́же ни́ні Го́спода прославля́ють: благослове́н єси́ во ві́ки, Бо́же оте́ць на́ших.","Богородичен: Ра́дости Пода́тельнице, Богороди́тельнице Пречи́стая, ві́рою сла́в'ящия і от душі́ пою́щия Тя ра́дости неізрече́нния іспо́лни і Сві́та Невече́рняго сподо́би, Ді́во Богоблагода́тная."]},{"h":"Пісня 8","ps":["Ірмос: Покрива́яй вода́ми преви́спренняя Своя́, полага́яй мо́рю преді́л песо́к і содержа́й вся, Тя поє́ть со́лнце, Тя сла́вить луна́, Тебі́ прино́сить піснь вся твар, я́ко Соді́телю всіх во ві́ки.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","І́м'я твоє́, святи́телю Луко́, я́коже благоуха́ніє рая́ Бо́жия по всей землі́ прославля́ється, услажда́я сердца́ ві́рующих і призива́я благода́рні воспіва́ти Соді́теля всіх во ві́ки.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Ни́ні Престо́лу Бо́жию предстоя́, мо́лишися о лю́діх, тя призива́ющих, на моли́тву же твою́ с ві́рою упова́ющих і благодаря́щих Соді́теля всіх во ві́ки.","О, ієра́рше богому́дре, ти, тече́ніє жи́зні до́брі соверши́в, ві́ру Христо́ву в гоне́ніїх і страда́ніїх до́брі сохрани́л єси́, сего́ ра́ди ни́ні віне́ць небе́сний от Пода́теля жи́зні обрі́л єси́, ра́дуяся і воспіва́я освяща́ющаго Соді́теля всіх во ві́ки.","Богородичен: Шед путе́м за́повідей Си́на Твоєго́, Богома́ти, весь род челові́чеський Твої́м Рождество́м от пра́отечеськаго паде́нія воста́ і кля́тви прама́тернія ізба́вися, воспіва́я Соді́теля всіх во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Благослове́н Госпо́дь, Бог Ізра́їлев, воздви́гнувий рог спасе́нія нам в дому́ Дави́дові, о́трока Своєго́, в ни́хже посіти́ нас Восто́к с висоти́ і напра́вил ни єсть на путь ми́ра.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Єва́нгеліє Христо́во пропові́дав, богому́дре святи́телю, служе́ніє Бо́жиє на землі́ страда́льчеськи соверши́л єси́ і, прия́тія Святи́х Та́їн Христо́вих сподо́блься, о Бо́зі ми́рно почи́л єси́.","Приспів: Святи́телю, о́тче Луко́, моли́ Бо́га о нас.","Ни́ні с Ви́шніми во́їнстви моли́, уго́дниче Христо́в, Человіколю́бця Бо́га, дарова́ти притека́ющим к тебі́ оставле́ніє гріхо́в і житія́ ісправле́ніє.","І по сме́рті, я́ко жив сий, благода́тію Бо́жиєю с на́ми пребива́єши, святи́телю Луко́, іспові́дниче до́брий, укріпля́я нас тве́рдо стоя́ти в Правосла́вній ві́рі і в доброді́тельній жи́зні наставля́я.","Богородичен: Є́же ра́дуйся, со арха́нгелом зове́м Ті, Чи́стая, я́ко Царя́ Небе́снаго родила́ єси́, Ді́во Богоро́дице, і мо́лим Тя: ізба́ви ни, раби́ Твоя́, от ві́чния сме́рти."]},{"h":"Світилен","ps":["Світи́льник ві́ри і іспові́дник тве́рдий яви́лся єси́, Луко́ пресла́вне. Пло́тію, а́ще і почи́л єси́, но ду́хом в Ца́рствії невече́рнім со Христо́м пребива́єши і при́сно мо́лишися Єму́ о всіх, ві́рою і любо́вію тя почита́ющих.","Слава, і нині: Ви́шніх чинонача́лій Преви́шшая су́щи, нас, ни́жніх, не оста́ви, Пречи́стая Влади́чице, но при́сно с на́ми бу́ди і от вся́ких наві́тов вра́жиїх свободи́."]}],"notes":[]},{"u":"Канон святим сорока мученикам Севастійським","e":"Canon to the Holy Forty Martyrs of Sebaste","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Гряді́те лю́діє, пої́м піснь Христу́ Бо́гу, разді́льшему мо́ре і наста́вльшему лю́ди, я́же ізведе́ із рабо́ти єги́петськия, я́ко просла́вися.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Боговінча́нний полк пою́ му́чеников Христо́вих, богодухнове́нними пі́сньми, четиредесятилі́тнюю па́м'ять сві́тло торжеству́яй, я́ко просла́вися.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","На землі́ всего́ отве́ргшеся іменова́нія, ізво́лиша чети́редесяте христоіме́нноє зва́ніє, і́мже ни́ні во ви́шніх живу́ть.","Су́щії во Христі́, плоть і мир возненави́дівше, ве́тхаго у́бо челові́ка совлеко́стеся со привре́менною оде́ждею, во оде́жду же нетлі́нія облеко́стеся.","Богородичен: Кто ізрещи́ Твоє́ по досто́їнству возмо́жеть па́че сло́ва зача́тіє? Бо́га бо родила́ єси́ пло́тію, Пречи́стая, нам я́вльшагося, Спа́са всіх нас."]},{"h":"Пісня 3","ps":["Ірмос: Утверди́ нас в Тебі́, Го́споди, дре́вом умерщве́й гріх, і страх Твой всади́ в сердця́ нас, пою́щих Тя.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Во́їнство, і жизнь, і красоту́ тіле́с, і бога́тство пренебре́гше, благосла́внії чети́редесять Христа́ вмі́сто всіх наслі́доваша.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ка́менієм неща́дно чети́редесяте повелі́нієм біє́мі мучи́телевим, мета́нія Бо́жиїм Ду́хом на повелева́ющия возвраща́хуся.","Глаго́лаше на самаго́, мучи́телевими устна́ми змій созда́вшаго хулу́, но того́ богобо́рная уста́ на му́ченики ка́меньми сокруша́ються.","Богородичен: Без сі́мене во утро́бі Бо́га зача́ла єси́ і ро́ждши несказа́нно вопло́щшася, на Него́же зрі́ти не смі́ють, Чи́стая, небе́сния си́ли, Присноді́во."]},{"h":"Сідален, глас 8","ps":["Христу́ вво́їнившеся му́ченичеськи, врага́ низложи́вше страда́льчеськи, ді́ли іспо́лнисте проро́ка глаго́ли: сквозі́ бо огнь і во́ду му́жеськи проідо́сте, поко́й обрі́тше, жизнь нетлі́нную. Ті́мже небе́сними укра́шшеся вінці́, с ли́ки веселіте́ся безпло́тних, блаже́ннії страстоте́рпці прехва́льнії, молі́те Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять ва́шу.","Слава, і нині, Богородичен: В напа́сти многоплете́нния впад от враг ви́димих і неви́димих, бу́рею одержи́м безчи́сленних согріше́ній мої́х, і я́ко к те́плому заступле́нію і покро́ву моєму́, Чи́стая, ко приста́нищу притека́ю Твоєя́ бла́гости. Ті́мже, Пречи́стая, із Тебе́ Воплоще́нному безсі́менно моли́ся прилі́жно о всіх рабі́х Твої́х, непреста́нно моля́щихтися, Богоро́дице Пречи́стая, моля́щи Єго́ при́сно согріше́ній оставле́ніє дарова́ти воспіва́ющим досто́йно сла́ву Твою́."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, слух Твоєго́ смотре́нія, і просла́вих Тя, Єди́не Человіколю́бче.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Умовре́дуєте, — глаго́лаху страда́льці, — стра́нную тщету́ всу́є простира́юще, пребезбо́жнійшії.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ізощре́ни мечі́, і зві́ри, і огнь, і крест святи́м Христо́ви гони́телі простира́ху.","Стра́шен нам, — глаго́лаху страда́льці, — огнь геє́нський, ни́нішняго же, я́ко клевре́та, не убої́мся.","Да от'я́ти бу́дуть ру́ки, сожже́на же бу́ди нога́, — святі́ї вопія́ху, — нетлі́нни бо сія́ па́ки при́ймем.","Богородичен: Мо́лим Тя, Пречи́стая, Бо́га безсі́менно заче́ншую, при́сно моли́тися за раби́ Твоя́."]},{"h":"Пісня 5","ps":["Ірмос: Сві́та Пода́телю, і віко́в Тво́рче, Го́споди, во сві́ті Твої́х повелі́ній наста́ви нас: ра́зві бо Тебе́, іно́го Бо́га не зна́єм.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Неі́стовством пребезу́мним гони́телей, страда́льці под возду́хом на сту́дені обноществова́ти осуди́вшеся, воспіва́ху пі́ніє Бо́гу благода́рственноє.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ра́дующеся чети́редесяте Христо́ви му́ченици, болі́зненний претерпі́вше лед, во є́зері стоя́ще, наде́ждею Боже́ственних вінце́в укріпля́ємі.","Сміх предлага́ється чети́редесятем Христо́вим му́чеником, уда́влен бив пре́жде гніздя́щийся во вода́х змій, пагуборо́дния бо крі́пости лиши́ся.","Богородичен: Тебі́, ро́ждшей Христа́, всіх Зижди́теля, зове́м: ра́дуйся, Чи́стая; ра́дуйся, возсія́вшая Світ нам; ра́дуйся, вмі́щшая Бо́га Невмісти́маго."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же м'я возведи́.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ра́достні началозло́бний восхити́, я́ко от двоюна́десяти Іу́ду окая́ннаго, і от Еде́ма челові́ка, от чети́редесяти отпа́дшаго.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Безсту́ден сий, всу́є шата́яся, я́коже бо разбо́йником і Матфі́єм пе́рвіє, та́ко і ни́ні мучи́тель стрегу́щаго зва́нієм осуди́ся.","Суєму́дренний і рида́нія досто́їн, і́же живото́в обої́х погріши́, огне́м бо раста́яся і ко огню́ оти́де негаси́мому.","Богородичен: Неіскусому́жно, Ді́во, родила́ єси́ і ві́чнуєши Ді́ва, явля́ющи і́стиннаго Божества́, Си́на і Бо́га Твоєго́, о́брази."]},{"h":"Кондак, глас 6","ps":["Все во́їнство ми́ра оста́вльше, на небесі́х Влади́ці приліпи́стеся, страстоте́рпці Госпо́дні чети́редесять, сквозі́ огнь бо і во́ду проше́дше, блаже́ннії, досто́йно восприя́сте сла́ву с небе́с і вінце́в мно́жество."]},{"h":"Ікос","ps":["На престо́лі непристу́пнім сідя́щему, просте́ршему не́бо, я́ко ко́жу, і зе́млю утверди́вшему, і собра́вшему во́ду в со́нми їх, вся от не су́щих сотво́ршему би́ти і всім подаю́щу диха́ніє і живо́т, приє́млющему от арха́нгел пі́ніє, і от а́нгел покланя́ємому, і от всіх сла́вимому, Христу́ Вседержи́телю, Зижди́телю і Бо́гу на́шему, припа́даю, недосто́йний, принося́ моє́ моле́ніє, сло́ва благода́ті прошу́: да возмогу́ благоче́стно воспі́ти і аз святи́я, я́же Сам показа́в побіди́телі, дарова́в їм сла́ву с небе́с і вінце́в мно́жество."]},{"h":"Пісня 7","ps":["Ірмос: О́бразу злато́му, на по́лі Деї́рі служи́му, тріє́ Твої́ о́троци небрего́ша безбо́жнаго велі́нія, посреді́ же огня́ вве́ржені, ороша́ємі, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ужасе́ся, зря вінці́, страж чети́редесяти, і, отри́нув любожи́зненноє, впири́ся раче́нієм явле́нния Твоєя́ сла́ви, і с му́ченики поя́ше: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","В ба́ню прите́к душетлі́нну, умерщвля́ється жизнолю́бний; христолю́бець же, хи́щник ізря́днійший ви́дінних бив, я́коже в ба́ні нетлі́нія с му́ченики поя́ше: благослове́н єси́, Бо́же оте́ць на́ших.","Огню́ ми́сленному, возже́ну во умі́х чети́редесяти, многоко́зненноє нече́ствующих попаля́шеся безу́міє, я́коже ні́кий воск та́єм. Тебі́ же, Христе́, воспіва́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Я́ко зіло́ світла́, благолі́пна же, Христе́, Креста́ Твоєго́ си́ла, проти́вними вінці́ плету́щи чети́редесятим му́чеником. Во́ду бо і огнь проше́дше, в нетлі́нії зову́ть: благослове́н єси́, Бо́же оте́ць на́ших.","Богородичен: Тя купину́ Мойсе́й в горі́ Сина́йстій огнепали́мую, Чи́стая, предзря́ше, поне́сшую неопа́льно нестерпи́мую зарю́ неізрече́ннаго Существа́, соєдини́вшагося дебельству́ пло́ті, єди́ния в ней святи́х Іпоста́сей."]},{"h":"Пісня 8","ps":["Ірмос: В пещ о́гненную ко отроко́м євре́йським снизше́дшаго, і пла́мень в ро́су прело́жшаго Бо́га, по́йте діла́, я́ко Го́спода, і превозносі́те во вся ві́ки.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Неі́стовно страда́льцем поусти́во враг вся́ко зда́ніє, всі́ми постиді́ся, чети́редесять бо непреста́нно пою́ть Го́спода і превозно́сять во вся ві́ки.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Неми́лостивно за Христа́ тіле́с ва́ших у́ди сокру́шшеся, всесожже́ніє боже́ственно принесо́стеся Бо́гу, со а́нгели при́сно лику́єте, му́ченици, пою́ще Христа́ во ві́ки вся.","Крі́постію сми́сла, єго́же роди́, на ра́мена взе́мши, христолюби́вая ма́ти, благоче́стія плод прино́сить, с му́ченики му́ченика, священноді́йству Авраа́мову подо́б'ящися.","К непреста́нній жи́зні правоте́чно, о си́ні, твори́ ше́ствіє, — христолюби́вая ма́ти христолюби́вому ді́тищу вопія́ше, — не терплю́ тебі́ второ́є, Подвигополо́жнику Христу́ яви́тися.","Богородичен: І́же в ні́дріх О́тчих неразді́льно же Си́на сідя́щаго, во веще́ственнім чре́ві Твоє́м все́льшася, Чи́стая, поє́м, Ді́во Богоневі́сто, і превозно́сим во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: От Бо́га Бо́га Сло́ва, неізрече́нною му́дростію прише́дшаго обнови́ти Ада́ма, я́дію в тлі́ніє па́дшаго лю́ті, от Святи́я Ді́ви неізрече́нно воплоти́вшагося нас ра́ди, ві́рнії, єдиному́дренно пі́сньми велича́єм.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","За Христа́ обнажи́вшеся і ка́менієм біє́ни би́вше, возду́шную претерпі́сте зи́мность, водни́й лед і сокруше́ніє уде́с і, огне́м опа́льшеся, в річні́й сія́єте бистрині́ іздале́ча, я́коже світи́ла, му́ченици чети́редесяте.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Жезл си́ли Боже́ственния, крест стяжа́вше, вопія́ху Христу́ страда́льці чети́редесяте: Влади́ко Всеси́льний Побіди́телю, руко́ю Твоє́ю да вінча́ємся, да всі тя пі́сньми непреста́нно велича́єм.","Я́ко болі́знен у́бо лед, я́коже зіло́ безмі́рна лю́тость, ю́же претерпі́сте, мра́за, но сла́док рай; Авраа́мова бо ні́дра патріа́рха грі́ють вас в се́ліх ві́чних, му́ченици чети́редесяте.","Побіди́вше страда́ньми і вінці́ приі́мше от боже́ственния Влади́чни десни́ці, ни́ні дарова́ти молі́теся мир ми́ру, і нам спасе́ніє, му́ченици чети́редесяте.","Богородичен: Неві́сто Ма́ти Ді́во, а́нгельськая мно́жества Твоєго́ мо́лять Си́на, прийми́ моле́ніє на́ше, єди́на наде́жде ві́рних, і мир ми́ру, і нам спасе́ніє, Тебі́ лю́б'ящим, да́руй."]},{"h":"Світилен","ps":["Десяти́цю четверочи́сленную, побідоно́сний полк, во́їнство святи́х му́ченик воспої́м досто́йно, огне́м бо, і сту́денію, і водо́ю посрами́ша вражде́бних полки́ і от Христа́ Спа́са вінці́ прия́ша сла́ви.","Слава: Лик четверодесяточи́сленний му́чеников чети́редесяти, Пребоже́ственния Тро́йці доброді́телей четвери́чних огня́, возду́ха, води́ і землі́, стихі́й чети́ріх, пі́сньми боже́ственними да воспоє́ться, я́ко за Христа́ пострада́вший, всіх Влади́ці.","І нині: Влади́ку всея́ тва́рі ро́ждши, Ма́ти Ді́во, і вся́чеських, я́ко су́щи Отрокови́ця, о Влади́чице Богоро́дице, страсте́й мучи́тельствующих м'я ісхити́ і проводи́ к милосе́рдія осія́нію і к прекра́сной Па́сці воскре́сшаго Си́на Твоєго́."]}],"notes":[]},{"u":"Канон мученику Андрію Стратилату","e":"Canon to the Martyr Andrew Stratelates","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́зними Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Пі́ти свяще́нноє твоє́ торжество́ усе́рдствующаго, сві́тлими Ду́ха заря́ми ду́шу мою́ озари́ і мглу отжени́ неві́дінія, му́чениче сла́вне.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Му́ченик бога́тно сві́тлостьми, блаже́нне, обогати́лся єси́, мужему́дренно си́лою боже́ственною попра́л єси́ льсти́ваго і побіди́тель бив, му́чениче великоімени́те Андре́є.","Умертви́в я́же на землі́ мудрова́нія, му́чениче многострада́льне, умертви́вшемуся Сло́ву тебе́ ра́ди му́жеськи послі́довал єси́ і к жи́зні неги́бнущей сме́ртію премину́л єси́.","Богородичен: І́же в плоть за премно́гую бла́гость із Тебе́, Всенепоро́чная, на спасе́ніє всім челові́ком воі́стину обле́кся, Бог вку́пі і Челові́к, сугу́б єстество́м познава́ється."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Ві́трилом Креста́ напа́сти препла́вая пучи́ну, враги́, сла́вне, струя́ми твої́х крове́й погрузи́л єси́.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Собла́зн лука́ваго і того́ хи́тростей преви́ше, я́ко побіди́тель ізря́ден, му́чениче, бив, просла́вился єси́.","Украша́єм благолі́пія вінце́м, му́чениче Христо́в, всегда́ со ізбра́нними му́ченики в ра́дості предстої́ши.","Богородичен: Ізбавля́ющаго челові́ки от мучи́тельства вра́жия, родила́ єси́ всіх Го́спода, Влади́чице, Ді́во Всенепоро́чная."]},{"h":"Сідален, глас 1","ps":["Му́жеством ду́шу укріпля́я, му́чениче, потреби́л єси́ вра́жиє крі́пкоє суровство́, і, ра́дуяся, пострада́л єси́, і Бо́гу угоди́л єси́. Ті́мже всі пресвяту́ю твою́ па́м'ять пра́зднуєм весе́лієм се́рдця, Андре́є пребога́те.","Слава, і нині: Лик боже́ственних апо́стол собра́ся погребсти́ Тя прече́стно, Богоро́дице Всечи́стая, с ни́миже і а́нгельстії чи́ни воспіва́ху преставле́ніє Твоє́, взива́юще прехва́льно. С ни́миже і ми, любо́вію ігра́юще, Чи́стая, хвалу́ Тебі́ прино́сим, гла́си пі́сненними, ві́рнії, і вопіє́м: ра́дуйся, Предста́тельнице при́сно чту́щих Тя."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце Пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Я́ко сті́ну крі́пку, тя Це́рков стяжа́вши, прему́дре, вра́жіїми сопроти́вними прило́ги непреклони́ма явля́ється, зову́щи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Боже́ственними уче́нії укріпи́в му́ченичеський полк, я́коже воєво́да, ті́лу я́ко растли́тися, сла́вне, хотя́щу пощади́тися ніка́коже повину́л єси́.","Я́ко ору́жієм, вооружи́вся му́жеством, і, я́коже мече́м обоюдуо́стрим, Андре́є преблаже́нне, Кресто́м Честни́м враги́ потреби́л єси́, я́коже воєво́да до́блественнійший.","Тя, побо́рника ві́ри, восхваля́єм, я́ко страда́льця непобіди́ма, і небе́сния сві́тлости прича́стника, і істо́чника, істоча́юща во́ди чуде́с тре́бующим.","Богородичен: Восхваля́єм Тя, похвало́ му́чеников і ві́рних спасе́ніє, всі челові́честії ро́ди, Пренепоро́чная: Бо́га бо родила́ єси́, преби́вши Ді́ва нетлі́нна."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой Світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Му́жества і́стиннаго бив тезоімени́ть, отгна́л єси́ враги́ твоя́, і до конця́, Андре́є всеблаже́нне, потреби́л єси́.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Во́ди ві́рним ісціле́ній всегда́, прехва́льне, істоча́єши, спаси́тельною благода́тію обогати́в духо́вною.","Протече́ во всю зе́млю воі́стину, богодухнове́нне, хвала́ твої́х чуде́с і честна́го муче́нія, сія́ніє Боже́ственния благода́ті.","Богородичен: Ору́жія врага́ ни́ні до конця́ оскуді́ша, ро́ждши Тебі́, Богоро́дице, копіє́м Уя́звеннаго і мир Обно́вльша."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Притупи́л єси́ лука́ваго жа́ла болі́зньми твої́ми і к неболі́зненній сла́ві преста́вился єси́, ра́дуяся, му́чениче Андре́є, Стратила́те му́ченичеських честни́х полко́в.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Кровми́ ма́лими ізміни́л єси́ сві́тлость ві́чнующия сла́ви, і ра́дость, нікогда́же престаю́щую, і вінці́ небе́сния, і сія́ніє невече́рнєє.","Во́їнство многочи́сленноє, му́чениче, собра́в, і лико́м а́нгельським приче́л єси́, блаже́нне, с тобо́ю страда́вшеє, ра́достно Влади́ці всіх предстоїте́.","Богородичен: Родила́ єси́ неізглаго́ланно Отцю́ Собезнача́льнаго, уподо́бльшася челові́ком, па́че ума́ і сло́ва, Богороди́тельнице: Єго́же моли́ ізба́витися от бід рабо́м Твої́м."]},{"h":"Кондак, глас 2","ps":["В моли́твах Го́сподеві предстоя́, я́коже звізда́ со́лнцю предтеки́й, і жела́ємоє сокро́вище Ца́рствія узрі́л єси́, ра́дости неізрече́нния ісполня́яся. Безсме́ртному Царю́ в безконе́чния ві́ки, от а́нгел безпреста́ни хвали́мому, поє́ши, Андре́є Стратила́те. С ни́миже моли́ся непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем, опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Струя́ми кро́вними істо́чник істещи́ сотвори́л єси́, вся́чеських неду́г, му́чениче, я́ко воі́стину болі́знь ісціля́ющ, приступа́ющим к тебі́ несумні́нною ві́рою, богодохнове́нне.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Святи́х собо́р Пресвято́му Сло́ву, му́дре му́чениче, приве́л єси́ кро́вію, жизнь нестарі́ємую наслі́довал єси́, с ни́миже моли́ о нас Христа́ Человіколю́бця.","Боже́ственною ре́вностію твої́ми кровми́ багряни́цю себі́, му́чениче, обагри́в і в сію́ оді́явся, всі́ми Ца́рствующему сца́рствуєши ни́ні, побі́дним вінце́м украша́єм.","Богородичен: Я́же челові́ки па́че єстества́ Боже́ственним Рождество́м Твої́м, Ді́во, проявле́нно обожи́вши, я́ко Бо́га неізрече́нно вопло́щши, благослове́нна Ти в жена́х єси́, Пренепоро́чная Влади́чице."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р, Данії́л, львов зія́нія в ро́ві затче́; о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Львов ди́віїх стремле́нія удержа́л єси́, сла́вне, тве́рдими по́двиги твої́ми, мучи́телей безбо́жних шата́нія Боже́ственною си́лою смири́л єси́ і побіди́тель к небесе́м, вопія́, восте́кл єси́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Святи́х сві́тлости ви́діти і жи́ти в ра́дості, му́чениче, сподо́бился єси́, подви́гся, до́блественне, і сконча́в по́двиг твой ме́чним усікнове́нієм. І ни́ні вопіє́ши с весе́лієм: благослові́те, вся діла́ Госпо́дня, Го́спода.","К боже́ственному притека́юще хра́му, боже́ственнаго му́ченика світ при́ймем і, ра́ці прикаса́ющеся всегда́ моще́й сего́, ра́дующеся, свяще́ніє пода́тельно благода́ті приі́мше, вопіє́м: вся діла́, благослові́те, Госпо́дня, Го́спода.","Богородичен: Свята́я Ді́во, Я́же Бо́га Пресвята́го свя́то поро́ждши, Єго́же всі святі́ї му́ченици на суди́щі іспові́даша, освяще́ніє і просвіще́ніє нам низпосли́, вопію́щим: вся діла́, благослові́те, Госпо́дня, Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся — Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Се світоза́рна страстоте́рпця па́м'ять просія́ світоно́сно, тьму де́монськую отгоня́щи, ві́рния же вся просвіща́ющи, сію́ сві́тло соверша́єм, сего́ досто́йно велича́юще.","Приспів: Святи́й му́чениче Андре́є, моли́ Бо́га о нас.","Яви́лся єси́, я́ко со́лнце ве́ліє, посреди́, Андре́є, стра́ждущих с тобо́ю, сих к невече́рнему сія́нію небе́сния сві́тлости наставля́я словеси́ твої́ми, с ни́миже тя ві́рою ублажа́єм.","Тя, сві́тлостію чуде́с всю просвіща́ющаго твар, тя, неукло́нним муче́нієм Це́ркві столпа́ би́вша і ві́рним утвержде́ніє, му́чениче Андре́є, велича́єм.","Процві́л єси́ посреди́ рая́ страда́лець, я́коже ши́пок, нося́ та́йно благово́ніє, і обвеселя́ ві́рних ісполне́ніє, і смрад, всему́дре, пре́лести отгоня́ Боже́ственною благода́тію.","Богородичен: Нося́щи Христа́ на руку́, ма́нієм нося́щаго вся, Сего́ моли́ руки́ м'я чужда́го ізба́вити, Влади́чице, правосла́вною ві́рою Тя непреста́нно велича́юща."]}],"notes":[]},{"u":"Канон преподобному Олександру Свірському","e":"Canon to St Alexander of Svir","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Боже́ственную па́м'ять твою́, богому́дре о́тче, ві́рно пра́зднующе, вся́чеських Го́спода при́сно сла́вим, тя просла́вльшаго мно́гими чудеси́.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Безстра́стія жела́нієм те́плим, о́тче, одержи́м, ве́щния ув'яди́л єси́ страсте́й во́лни, Алекса́ндре, і дости́гл єси́, любо́вію вперя́єм, присносу́щнаго сія́нія, преблаже́нне, Божества́.","Доброді́тельно ізнача́ла приє́м житіє́, пребога́те, ба́нею, о́тче, пакибитія́, дар духо́вний от младе́нства боже́ственне, твоєя́ душі́ благолі́піє, Алекса́ндре, показа́л єси́, со́лнця світлі́йше.","Слава, і нині, Богородичен: Мла́до Отроча́ па́че сло́ва родила́ єси́, Ве́тхаго Де́ньми, но́ву на землі́ стезю́ доброді́телей показа́вша. Тім уго́дник Твой при́сний Алекса́ндр, Отрокови́це, любо́вію сніда́єм, сей храм Тебі́ созда́."]},{"h":"Пісня 3","ps":["Ірмос: На ка́мені м'я ві́ри утверди́в, разшири́л єси́ уста́ моя́ на враги́ моя́, возвесели́бося дух мой, внегда́ пі́ти: ність свят, я́коже Бог наш, і ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","По́том воздержа́нія твоєго́ пла́мень страсте́й погаси́л єси́, і одожде́нієм моли́тв струї́ чуде́с істочи́л єси́, болі́зньми разжже́нія погаша́я я́ві, преблаже́нне Алекса́ндре.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","І́же к честні́й ра́ці твоє́й притека́юще, прему́дре, от сея́ почерпа́єм ісціле́нія сокро́вище, і чуде́с пучи́ну, і дар незави́стний, Алекса́ндре. Ті́мже, пою́ще, тя восхваля́єм.","Душе́вния чу́вства от ужа́снаго, преподо́бне о́тче, просві́щ виді́нія, я́ко чу́ден ра́зум благи́х стяжа́л єси́, і́ночества житіє́ іму́щим, Алекса́ндре, небла́знено житіє́ показа́л єси́.","Слава, і нині, Богородичен: І́же пре́жде вік ро́ждься от Отця́ неізрече́нно, напослі́док із утро́би Твоєя́ про́йде, і обожи́ на́ше єстество́, Ма́ти Ді́во, І́же преподо́бних ли́ки я́ві ізводя́й."]},{"h":"Сідален, глас 8","ps":["От ю́ности вся оста́вль жите́йськая, кра́сная же і лі́потная, і в пусти́ню всели́вся, усе́рдно послі́довал єси́ Зва́вшему тебі́, преподо́бне, в труді́х же і пості́х, о́тче, ті́ло твоє́ ізнури́л єси́. Отону́дуже тя па́стиря свої́м овця́м до́брі устроя́єть всебога́тий Госпо́дь, Алекса́ндре блаже́нне. Моли́ Христа́ Бо́га прегріше́ній оставле́ніє дарова́ти, чту́щим любо́вію святу́ю па́м'ять твою́.","Слава, і нині, Богородичен: Я́ко Ді́ву і єди́ну в жена́х, Тя, без сі́мене ро́ждшую Бо́га пло́тію, всі ублажа́єм, ро́ди челові́честії: огнь бо всели́ся в Тя Божества́, і я́ко Младе́нця млеко́м пита́єши Зижди́теля і Го́спода. Тім, а́нгельський і челові́чеський род, досто́йно сла́вим пресвято́є рождество́ Твоє́, і согла́сно вопіє́м Ті: моли́ Христа́ Бо́га, согріше́ній оставле́ніє дарова́ти, покланя́ющимся ві́рою пресвято́му Рождеству́ Твоєму́."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви, не хода́тай, ні а́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Житіє́ твоє́, богоно́се преблаже́нне Алекса́ндре, пра́вило ізві́стно мона́шествующих бисть, єму́же ни́ні ревну́юще, спаса́ємся, і́же твої́м послі́дующе, о́тче, боже́ственним уче́нієм.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Ду́ха Свята́го зарю́ приє́м, звізда́ пресві́тлая, о́тче Алекса́ндре, сія́я благода́тію, бил єси́ всім, ї́хже наста́вил єси́ к спасе́нія приста́нищу твої́ми уче́нії.","Преби́ти внутр ніка́коже ми́ра восхоті́л єси́, прему́дре о́тче Алекса́ндре, імі́я наставля́ющаго тя Бо́жия Ду́ха си́лу, в непроходи́мих пусти́нях живи́й і со звірми́ ходя́ без боя́зні, ю́ноша сий, і болі́зньми пита́лся єси́ тіле́сними.","Слава, і нині, Богородичен: Плещми́ херуви́мськими стра́шними носи́м, Влади́ко, я́ко на престо́лі о́гненні, в Твою́, Чи́стая, всели́ся утро́бу, і пло́ті прия́тієм челові́чеськоє обожи́ существо́, я́ко учи́ть ізря́дний в преподо́бних Алекса́ндр, єди́на Всепі́тая."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо, Влади́ко, к Світонача́льнику, Отцю́ Твоєму́, от но́щі неві́дінія приведе́ніє і́мами.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Возжелі́в ум твой храни́ти соблюде́ньми за́повідей, Алекса́ндре, і плотсько́є взигра́ніє твої́м воздержа́нієм ув'яди́л єси́, і па́стир показа́лся єси́ боголюбе́зному твоєму́ совокупле́нію.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Зако́ном Боже́ственним послі́дуя, прему́дре Алекса́ндре, і повелі́нієм повину́яся Сотво́ршаго, законополо́жник яви́лся єси́ мона́хов і пра́вило ізві́стнійшеє, наказа́тель безу́мних, і наста́вник заблу́ждших, і світи́льник во тьмі неві́дінія, пресла́вне.","Огнь іскуше́ній і страсте́й пещ слеза́ми твої́х, о́тче, тече́ній і духо́вною росо́ю бога́тно угаси́л єси́, соблю́дся неопали́м: опаля́єм бо любо́вію всіх Царя́, ве́щная ув'яди́л єси́ жела́нія.","Слава, і нині, Богородичен: Жите́йськая не мо́гуть уста́ по достоя́нію Тя пі́ти, Всепі́тая, ви́шшу су́щу херуви́м і вся́кия тва́рі. Ті́мже с боже́ственним Алекса́ндром Влади́ку о всіх нас умоли́."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Сми́сленно ти вре́менная проразсуди́в, Алекса́ндре блаже́нне, ві́чнующая болі́зньми воздержа́нія дости́гл єси́, о́тче, душа́м строї́тель бив, преподо́бне.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Я́ко терп'я́щу ті вельми́ по́ти трудо́в твої́х, преподо́бне Алекса́ндре, удо́б воздержа́нієм, чу́дний о́тче, я́влься, Влади́ка тебі́ Христо́с, вруча́єть си́лу боже́ственну, і сим ті неду́ги повеліва́єть ціли́ти.","Мона́шествующих наста́вник бив, прему́дре Алекса́ндре, су́щих ті єдинообра́зних ла́ври, і о́браз і начерта́ніє доброді́тельних дія́ній сий, украси́л єси́ вся, я́же во оби́телі супру́жних пребива́нія.","Слава, і нині, Богородичен: Нов, я́коже Мойсе́й, я́влься, устро́їл єси́, я́ко ски́нію, огра́ду, всече́стне, ю́же і превозрасти́л єси́ болі́зньми і по́ти твої́ми, весь возложи́вся Пречи́стій Ма́тері Бо́жії."]},{"h":"Кондак, глас 8","ps":["Я́ко многосві́тлая звізда́, днесь в страна́х Українських возсія́л єси́, о́тче, всели́вся в пусти́ню, Христо́вим стопа́м послі́довати усе́рдно возжелі́л єси́, і Того́ свято́є і́го на ра́мо твоє́ взем — Честни́й Крест, умертви́л єси́ труди́ по́двиг твої́х тіле́сная взигра́нія. Ті́мже вопіє́м ті: спаси́ ста́до твоє́, є́же собра́л єси́, му́дре, да зове́м ті: ра́дуйся, преподо́бне Алекса́ндре, о́тче наш."]},{"h":"Ікос","ps":["Ка́ко восхвалю́ твоя́ по́двиги і боре́нія, преподо́бне Алекса́ндре? Я́ко невеще́ствен ра́зум стяжа́в смире́нієм, житіє́ твоє́ препроводи́л єси́ зі́льним воздержа́нієм трудо́в твої́х. А́ще у́бо і челові́к бил єси́ єстество́м, но Ви́шняго Ієрусали́ма яви́лся єси́ граждани́н: с пло́тію бо на землі́ пожи́л єси́, но а́нгельськоє пребива́ніє проше́д і бил єси́ столп, страстьми́ непотрясо́м. Тім вся Українськая земля́, тобо́ю обога́щшися, хва́лить тя і ві́рою велича́єть, взива́ющи тебі́ такова́я: ра́дуйся, оте́честву твоєму́ похвала́, Вели́кому же Нову́граду і всей страні́ Українській пресві́тлий світи́льниче; ра́дуйся, і́же благочести́ва отця́ пресла́вная о́трасль і благогові́йни ма́тере вітв многопло́дна; ра́дуйся, цілому́дрія непрекло́нний сто́лпе і мона́хов пресві́тлая сла́ва; ра́дуйся, па́стирю Христо́ви огра́ди слове́сних ове́ць, ї́хже к Бо́жию приводя́ ра́зуму; ра́дуйся, ти бо многоча́дну пусти́ню возді́лал єси́ висото́ю смире́нія твоєго́; ра́дуйся, мона́шествующих всіх о́браз доброді́телі і єдинообра́зних ла́ври спасе́ніє; ра́дуйся, кра́сноє доброді́телей храни́лище і всім, в печа́лі унива́ющим, утіше́ніє; ра́дуйся, я́ко вся ми́ра сего́ мудрова́нія презрі́в, стра́сті плотські́я умертви́л єси́; ра́дуйся, я́ко а́нгелом собесі́дник би́ти сподо́бился єси́ і вся бісо́вськия полки́ посрами́л єси́; ра́дуйся, ти бо во всіх страна́х просла́влен бил єси́, о Христі́ бо мно́га чудеса́ сотвори́л єси́; ра́дуйся, я́ко воі́стину обрі́л єси́ Бо́жию благода́ть і со а́нгели при́сно зрі́ти сподо́бился єси́ лице́м к лицю́ Святу́ю Тро́йцю; ра́дуйся, я́ко второ́є со́лнце, сія́я чудеси́, всім да́руєши благода́ть ісціле́ній; ра́дуйся, преподо́бне Алекса́ндре, о́тче наш."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть, Христо́с же простре́ богочести́вим отроко́м ро́су духо́вную, Сий благослове́н і препросла́влен.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Крі́постію оді́явся, Алекса́ндре, Влади́чнею, і я́ко прах, сладостра́стіє житія́ попра́л єси́, любо́вію побіжда́єм нетлі́нния жи́зні, є́йже ни́ні і причасти́лся єси́, с ли́ки а́нгел, о́тче, сочета́вся.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Крестообра́зно простира́я дла́ни твоя́, Алекса́ндре прему́дре, і моли́тви твоя́ возсила́я Ви́шнему, я́ко Христа́, Царя́ сла́ви, со а́нгели, очи́ма явле́нно, богоно́се, узрі́л єси́, і в пусти́нях непрохо́дних водворя́яся, іща́й Го́спода, Боже́ственною тя благода́тію соблюда́юща.","Я́ко звізду́ тя, Алекса́ндре, всеми́рну, мона́хов світи́ло незаходи́моє, помо́щника в біда́х і грі́шником вели́коє прибі́жище ві́дий, хода́тая і моли́твенника тя предлага́ю Влади́ці Христу́, всече́стне.","Слава, і нині, Богородичен: Ви́діти жела́я Твой уго́дник Твоєго́ Си́на і Бо́га неізрече́нную сла́ву, Богороди́тельнице, Сего́ Честни́й Крест на ра́мо взем, послі́дова живоно́сним Єго́ стопа́м."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Я́коже мо́лнія вели́кими блиста́нії, житіє́ сія́ющеє всім возсія́ воздержа́нія твоєго́, Алекса́ндре прему́дре, благоче́стно Зижди́телю зову́щим: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","На землі́ я́ко челові́ко ходя́, о́тче Алекса́ндре, житіє́ себе́ на небесі́х я́ко воі́стину стяжа́л єси́, а́нгелом собесі́дник я́влься, житіє́ же і жизнь соверша́я о́ніх. С ни́миже воспіва́єши ни́ні: благослові́те, вся діла́ Госпо́дня, Го́спода.","Тя, па́че ума́ із нерожде́нна Отця́, пре́жде вік рожде́нна Си́на, сла́вний пропові́да Алекса́ндр, і Ду́ха Пресвята́го, Єди́ну Тро́йцю єстество́м ві́дий Божества́.","Слава, і нині, Богородичен: Я́коже Ілия́ пе́рвіє в Карми́лі всели́ся, та́ко і ти, в пусти́нях непрохо́дних упражня́яся, возжела́л єси́ осо́б с Бо́гом жи́ти, і богонача́льними озари́вся виді́нії, уго́дник яви́лся єси́ Богоро́дице, вопія́ Єй: ра́дуйся, Обра́дованная."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная. Тім Всепі́тую Богоро́дицю велича́єм.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Стопа́м послі́дуя, преподо́бне і богоно́се, Влади́ки Христа́, благоче́стно пожи́в на землі́, кро́ток, незло́бив яви́лся єси́, ми́лостив і смире́н, Алекса́ндре, і любве́ іспо́лнен боже́ственния, сего́ ра́ди тя ві́рно восхваля́єм.","Приспів: Преподо́бне о́тче Алекса́ндре, моли́ Бо́га о нас.","Ісплете́ся тебі́ віне́ць, я́ко побіди́телю, Алекса́ндре, живоно́сною і вседержи́тельною десни́цею, о́тче, і ни́ні пою́щия па́м'ять твою́ сподо́би, блаже́нне, улучи́ти оставле́ніє согріше́ній, пресла́вне.","Совокупи́лся єси́ со безпло́тними во́їнстви, і преподо́бним лико́м сочта́лся єси́, і со ізбра́нними всі́ми лику́єши, претво́рся і́стинним обоже́нієм і безсме́ртною, о́тче, жи́знію, с ни́миже непреста́нно о нас твоєго́ Влади́ку умоли́.","Слава, і нині, Богородичен: Хра́мі освяще́нний, вмі́стен Єди́ному от Тро́йці сий, храм Твой, Влади́чице, уго́дник Твой Алекса́ндр че́стен воздви́же в сла́ву Твою́ і честь, в не́мже не преста́й моля́ся, да́тися нам по́мощі моли́твами Твої́ми."]},{"h":"Світилен","ps":["Благода́ть преізби́сть Бо́жія в душі́ твоє́й, прему́дре Алекса́ндре, і я́ко безпло́тен, на землі́ пожи́л єси́. Тім почита́ющих тя страсте́й ізба́ви те́мних о́блак, і к ти́хому приста́нищу приводя́ і отгоня́я ополче́нія бісо́вськая Боже́ственною си́лою.","Слава, і нині, Богородичен: Сотво́р воі́стину с Тобо́ю вели́чія Син Преві́чний О́тчим сові́том: Жизнь бо нетлі́нную без стра́сті родила́ єси́ і пребила́ єси́, я́коже пре́жде рождества́, Ді́ва, ма́терських ізбі́гши болі́зней і по рождестві́ Ді́вою преби́вши."]}],"notes":[]},{"u":"Канон благовірному князю Ігорю Чернігівському і Київському","e":"Canon to the Right-Believing Prince Igor of Chernihiv and Kyiv","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, Ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Во́ду нече́стія тиме́нну оста́вив, к воді́ чисти́тельней прите́кл єси́, свя́те І́горю, і на́ша очи́сти сердца́ чи́сто пі́ти твої́ страда́нія.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Водо́ю креще́нія оми́вся, перворо́днаго гріха́ ізба́вился єси́ і Чи́стому Влади́ці Христу́ присво́їлся єси́, Єму́же і нас чи́сто присво́й моли́твами твої́ми.","Во воді́ потопи́вшему змі́я лука́ваго подо́б'яся, кро́вію твоє́ю страда́льчеською вра́жию погрузи́л єси́ си́лу, страстоте́рпче, от него́же і нам ізба́витися Спа́са умоли́.","Богородичен: Во́ду слез очища́ющую, Пречи́стая, пода́ждь мі і, очи́стивши м'я от ка́ла беззако́ній, чи́ста предста́ви, Богороди́тельнице, Си́ну Твоєму́ і Бо́гу."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Небе́снаго кру́га Верхотво́рцю все житіє́ своє́ отда́в, возлюби́л єси́ Того́ до конця́; сподо́би і нас моли́твами твої́ми, страстоте́рпче, люби́ти Го́спода до конця́ дній на́ших.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Небе́сния жи́зні жела́я, в земно́м житії́ твоє́м вся пренебре́гл єси́; сподо́би і нас, свя́те, моли́твами твої́ми Небе́сния жи́зні сподо́битися.","Небе́снаго черто́га жела́я, чистоту́ ді́вства твоєго́ соблю́л єси́ і ни́ні с де́вственники в Небе́сних черто́зіх лику́єши.","Богородичен: Небе́снаго Творця́, Богоро́дице Всепі́тая, ро́ждши, Небе́с простра́ннійшая яви́лася єси́; мене́ от простра́ннаго путі́ поги́бельна укло́ньши, на Небе́сний путь наста́ви, молю́ся."]},{"h":"Сідален, глас 5","ps":["Доброді́тельними світлостьми́ просвіща́єм і муче́нія сві́том украша́єм, па́че со́лнця, прему́дре, сія́єши тве́рді і просвіща́єши воі́стину творя́щих ві́рно па́м'ять твою́ світоно́сную, пресла́вний страстоте́рпче І́горю, спаса́й моли́твами твої́ми.","Богородичен: Ужа́сно чу́до зача́тія і несказа́нен о́браз Рождества́ в Тебі́ позна́ся, Чи́стая Присноді́во, ужаса́єть мой ум і удивля́єть по́мисл; сла́ва Твоя́, Богоро́дице, всім простре́ся, во спасе́ніє душа́м на́шим."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Усли́шав, І́горю, Небеса́ пові́дающа сла́ву Бо́жию, на землі́ Бо́га сла́вити возжела́л єси́, Єго́же сла́ви і нас сподо́би.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Усли́шав, я́ко вразі́ твої́ воста́ша на тя, не убоя́лся єси́ свирі́пства їх, но кро́тці в ру́ці їх скве́рния вда́лся єси́, Го́сподеві взива́я: не поста́ви їм гріха́ сего́.","Усли́шав преще́нія вра́жеськая і му́ки от них терп'я́, непоколеби́м преби́л єси́, і мене́ непоколеби́ма в доброді́теліх сотвори́.","Богородичен: Усли́ши, Пречи́стая Влади́чице, моле́ніє моє́, і ізба́ви м'я от зол, і глас, благослове́нних призива́яй в Ца́рство, сли́шати удосто́й."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, і ми́шцею Твоє́ю висо́кою Твой мир пода́ждь нам, Человіколю́бче.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Просвіти́в стезю́ жи́зні твоєя́ сві́том богоразу́мія, Христа́ Го́спода вседу́шні возлюби́л єси́; сподо́би і мене́, страстоте́рпче, в сих би́ти тебі́ подража́телю.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Просвіща́хуся ві́рнії лю́діє, ви́дяще тя, нестерпи́мия му́ки до́бльственні терп'я́ща, сподо́би і мене́, страда́льче, би́ти терпели́ву.","Просвіти́ м'я, о І́горе, омраче́ннаго мгло́ю гріхо́вною, і сві́том невече́рнім осіява́тися, сві́тлий му́чениче, молю́ся, сотвори́.","Богородичен: Просвіти́ла єси́ потемне́нноє єстество́, Богоро́дице, Світ і́стинний ро́ждши, ті́мже і мене́, сві́том просвіти́вши, от мра́чних враг свободи́."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Моли́тву твою́ страда́льчеськую усли́шав, Христо́с, І́горю, крі́пость і си́лу ко страда́нієм тебі́ подаде́; сподо́би і м'я моли́твами твої́ми в страда́ніїх жите́йських би́ти тве́рду.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Моли́твою пред о́бразом Пречи́стия себі́ укріпи́в, ізше́л єси́ ко враго́м твої́м, і́щущим тя, і, я́ко а́гнець незло́бив, пострада́л єси́ от них, непра́ведно умерщвля́єм.","Моли́тву всяк принося́й ті с ві́рою, страда́льче, душе́вних страсте́й і тіле́сних ісціле́ніє ско́ро приє́млеть; є́же і нам бога́тно подава́й, мо́лимся.","Богородичен: Моли́тву на́шу прийми́, Пречи́стая, і моли́твою Ті всемо́щною ізба́вити нас враг ви́димих і неви́димих, от гріхо́в же і вся́кия му́ки моли́, Єго́же родила́ єси́, Человіколю́бця Бо́га."]},{"h":"Кондак, глас 6","ps":["Ізміни́л єси́ земна́го княже́нія сла́ву во і́ночества о́браз смире́нний і, страда́льчеськи земно́є житіє́ сконча́в, ни́ні на Небесі́х ра́дуєшися, усе́рдні моля́ся о чту́щих тя, І́горю, страда́льцев похвалі́."]},{"h":"Інший кондак, глас 8","ps":["Кня́жеськую діади́му обагри́л єси́ кро́вію твоє́ю, богому́дре страстоте́рпче І́горю, за скиптр крест в ру́ку приї́м, яви́лся єси́ побідоно́сець і же́ртву непоро́чну Влади́ці прине́сл єси́ себе́. Я́ко бо А́гнець незло́бив, от раб убіє́н бил єси́ і ни́ні ра́дуяся предстої́ши Святі́й Тро́йці, моли́ спасти́ся душа́м на́шим."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки. Ді́ти євре́йськая А́нгел от огня́ неопа́льна сохрани́вий, і тебі́, І́горю, во страда́нії укріпи́, пою́ща: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Ді́тськоє ігра́лище вміня́я му́ки, не пощади́л єси́ ті́ла твоєго́, но стра́сті му́жественні терпі́л єси́, поя́: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Ді́тем му́чимим подража́я, І́горю, хвалю́ і аз Христа́, да́вшаго тебі́ крі́пость; ти же м'я, на по́двиг доброді́телей укріпи́в, сподо́би пі́ти с тобо́ю: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Богородичен: Деторо́дію Твоєму́, Ді́ві і по Рождестві́ преби́вшей, дивлю́ся, Богоро́дице. Удиви́ у́бо і на мні ми́лость Си́на Твоєго́, да поми́лован Тобо́ю, пою́: благослове́н єси́, Го́споди Бо́же, во ві́ки."]},{"h":"Пісня 8","ps":["Ірмос: Побіди́телі мучи́теля і пла́мене благода́тію Твоє́ю бив те, за́повідем Твої́м зіло́ приліжа́ще, о́троци вопія́ху: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Побіди́тель яви́лся єси́, сла́вне І́горю, враго́в, му́чащих тя, і́бо в лю́тих му́ках стражда́, непреста́нно взива́л єси́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Побіди́л єси́ му́жеством твої́м, страстоте́рпче сла́вне І́горю, вся мучи́тельськая ухищре́нія. Моли́ у́бо Влади́ку Христа́, мо́лим тя, всім ві́рним на враги́ побі́ду да́ти, пою́щим: благослові́те, вся діла́ Госпо́дня, Го́спода.","Побіди́тель жестокосе́рдих уби́йць яви́лся єси́, сла́вне І́горю, они́ бо Небе́сним огне́м во а́дський огнь низведо́шася, ти же на Не́бо возше́л єси́, іді́же ни́ні со А́нгели поє́ши: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Побіди́, Пречи́стая, враго́во ви́димих і неви́димих, низложи́ти нас тща́щихся, і страсте́й м'я вся́ких ізба́ви, да пою́ торже́ственне: благослові́те, вся діла́ Госпо́дня, Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю Тя іспові́дуєм, спасе́ннії Тобо́ю, Ді́во Чи́стая, с безпло́тними ли́ки Тя велича́юще.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Воі́стину Бо́га іспові́дуя, страстоте́рпче, черто́г Небе́сний наслі́довал єси́, єго́же і нас сподо́би, да с тобо́ю Христа́ ві́чно велича́єм.","Приспів: Святи́й благові́рний вели́кий кня́же І́горе, моли́ Бо́га о нас.","Воі́стину на тебі́, Ігорю блаже́нне, іспо́лнися Христо́во прорече́ніє: вся претерпі́вий до конця́ спасе́н бу́деть, ни́ні бо со всі́ми спасе́нними Христа́ ві́чно велича́єши.","Воі́стину нікто́же притека́яй к тебі́, страстоте́рпче, тощ благода́ті твоє́й отхо́дить, є́йже і мене́ іспо́лни, да тя велича́ю.","Богородичен: Воі́стину і́стиннаго Бо́га Пло́тію, Богоро́дице, родила́ єси́, Єго́же ми́лостива нам в День Суда́ соді́лай, да безконе́чно с Ним Тя велича́єм."]},{"h":"Світилен","ps":["Я́коже со́лнце, світоно́сно возсія́ ни́ні, страстоте́рпче, па́м'ять твоя́, вся ві́рния веселя́щи, і́же моли́твенно взива́ють ті: моли́ся прилі́жно, во є́же спасти́ся нам.","Богородичен: Держа́вним Твої́м покро́вом, Чи́стая, нас, рабо́в Твої́х, от наві́та вра́жия сохраня́й всегда́ невреди́мих, Тя бо єди́ну стяжа́хом прибі́жище в біда́х."]}],"notes":[]},{"u":"Канон блаженному Августину, єпископу Іппонійському","e":"Canon to Blessed Augustine, Bishop of Hippo","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль, по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м вопія́ше.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Прийді́те, ві́рнії, препросла́вленную па́м'ять святи́теля вели́каго і вселе́нния учи́теля Августина блаже́ннійшаго согла́сно пра́зднуїм, єретико́в посрами́теля і покая́нія пропові́дника.","Ізбра́н Го́сподем бив служе́ніє святи́тельськоє восприя́ти, в правові́рії і любві́ боже́ственній уче́нії твої́ми прему́дрими па́ству Христо́ву упа́сл єси́, святи́телю.","Прему́дрость Боже́ственную сви́ше прия́в, уче́ніє животво́рноє істочи́л єси́, душі́, страстьми́ попаленния, ісціля́ющеє, святи́телю сла́вне Августине.","Богородичен: Я́ко Вселе́нния сокро́вище вели́коє чтем Тя, Ді́во Пренепоро́чная, Ти бо ми́ру от Тро́йці Єди́наго родила́ єси́, Єму́ же моли́ся, да спасе́ть ни."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Воспої́м, ві́рнії, днесь па́стиря і святи́теля і вселе́нния учи́теля, пра́вило ві́ри і о́браз, і Боже́ственнаго Пастиренача́льника подража́теля.","Бо́жиїм ізволе́нієм проізбра́н бив, святи́тель вели́кий Це́ркве Христо́ви яви́лся єси́, бескровную Та́йную Же́ртву А́гнцю Бо́жию принося́, ми́ра гріхи́ на Ся взе́млющему.","Сі́яніє моли́тви сле́зния ма́тере твоєя́ святи́я яви́лся єси́ і плод стори́чний Творцю́ Го́споду ві́рою прине́сл єси́, Августине сла́вне.","Богородичен: Двер Небе́сная нам єси́, Богоро́дице, / є́юже Цар сла́ви к нам вни́де, Єго́ же моли́ спасти́ся нам."]},{"h":"Сідален, глас 7","ps":["Єрети́чеськая злокозненная шата́нія посрами́л єси́, Христо́ву же Це́рков ві́рно упра́вил єси́, ті́мже, в селе́ніїх го́рніх водворя́яся, блаже́нне, свя́те Августине, моли́ся о душа́х на́ших.","Богородичен: Кля́тви дре́внія разоре́ніє і обітова́ній Бо́жиїх всеспасительних ісполне́ніє, Богоро́дице, яви́лася єси́. Ті́мже моли́ся Ро́ждшемуся от Тебе́, да ізба́вить ни от си́ли вра́жия."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть взива́ющи, от сми́сла чи́ста о Го́споді пра́зднующи.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Непреобори́м яви́лся єси́, святи́телю Августине, по Бо́зі Вседержителе во́їнствуя і во всем велі́нія Того́ ісполня́я.","Огра́да тве́рдая церко́вная яви́лся єси́, свя́те, словеси́ і ді́ли ісправля́я пра́вая, Августине, вели́кий учи́телю.","Меч воі́стину боже́ственний на є́ресі яви́лся єси́ і гром, нечести́вия устраша́яй, душі́ же ві́рних сло́вом і́стини укріпля́єши, Августине.","Богородичен: О Благослове́нная, Чи́стая, моли́мтися: моли́ся к Ро́ждшемуся от Тебе́, да ізба́вить душі́ на́ша от іскуше́ній і обстоя́ній."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті душі́ любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Свіщу́ пресві́тлу яви́ тя ми́ру Христо́с, блаже́нне, сві́том неізрече́нним осія́в і святи́тельства пра́вило всім показа́в.","Боже́ственне ді́ло Бо́жиє соверша́я і чи́стим умо́м прикаса́яся чисті́йшим, непоро́чен обрі́лся єси́, Бо́гу слу́жбу творя́; ті́мже і нас сло́вом твої́м освяти́ і научи́ блага́я твори́ти.","Прикровенноє Зако́на Ве́тхаго па́стві твоє́й уясни́л єси́, от Боже́ственних сокро́вищ Ду́ха сказу́я, небоявле́нне Августине.","Богородичен: Тебі́, Соді́теля пло́тію ро́ждшей і кля́тви дре́внія Разрешительнице, восклиця́юще мо́лимся: спаси́ осужде́нія ві́рою Тя блажащия."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Душі́, гла́дом тающия, напита́л єси́ і жаждущия весе́лія боже́ственнаго іспо́лнил єси́, пропові́дуя і віща́я, всехва́льне Августине.","Медото́чния ка́плі доброді́телі вся́кия любому́дренно собра́л єси́ і от них вселе́нную услади́л єси́, о́тче блаже́ннійший.","Благода́тію Боже́ственною осія́н бив, худшая на лу́чшая преміни́л єси́ і сокро́вище некра́домоє обрі́л єси́, святи́телю всехва́льне.","Богородичен: Сло́во Боже́ственноє во чре́ві вмі́щшая і ми́ру всему́ Спасе́ніє ро́ждшая, не премолчи́ за ни моля́ся ко Го́споду."]},{"h":"Кондак, глас 4","ps":["Це́ркве Вселе́нськия сто́лпе непоколеби́мий, на недви́жимім ка́мені ві́ри утвержде́нний, ві́ри правосла́вния учи́телю нелі́ностний і покая́нія пропові́дниче велегла́сний, і́стини возвісти́телю, прехва́льне Августине, святи́телю Христо́в, просвіти́ ни уче́нієм твої́м."]},{"h":"Ікос","ps":["Прему́дрости уста́, цілому́дрія ча́ша, Правосла́вія учи́тель Августин блаже́ннійший всім сія́єть ми́сленні. Прийді́те, уподо́бимся того́ смире́нію, ві́рі же і любві́, і́миже дом Божества́ показа́ся, і в ра́дості та́ко возопії́м: ра́дуйся, прехва́льне Августине, святи́телю Христо́в, просвіти́ ни уче́нієм твої́м."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла а́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увіща́ вопи́ти: благослове́н єси́ Бо́же оте́ць на́ших.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Прему́дрости світлостьми́ осія́н, ті́миже па́ству твою́ облиста́л єси́ і пі́ти Творцю́ всіх подви́гл єси́: благослове́н єси́, Бо́же оте́ць на́ших.","Ум во глубини́ непостижния впери́в і би́сер ра́зума многоці́нний стяжа́в, мир прему́дростію іспо́лнил єси́, взива́я: благослове́н єси́, Бо́же оте́ць на́ших.","Го́рдаго си́лу пресі́кл єси́, бла́же, смире́нієм твої́м, к Бо́гу ра́зумом чи́стим возноси́мий, Єму́ же пі́ти научи́л єси́: благослове́н єси́, Бо́же оте́ць на́ших.","Богородичен: Купину́ Тя огнегорящую Госпо́дь Мойсе́ю в Сина́ї дре́вле прообразова́, Ти бо огнь Божества́ невеще́ственнаго прия́ла єси́, ми́ра спасе́нія нача́ло устро́ївши. Моли́ся ко Святі́й Тро́йці спасе́ніє нам дарова́ти, мир і ве́лію ми́лость."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́, і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти, Тя превозно́сим во вся ві́ки.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Богоприя́тен святи́тель показа́лся єси́, о́тче Августине, Ду́хом Боже́ственним па́ству твою́ просвіща́яй, да взива́ють всі: благослові́те вся діла́ Госпо́дня Го́спода.","Се́рдця, неду́гом є́ресі па́губния уязвленная, благода́тними слове́с твої́х лічба́ми уврачева́л єси́, сего́ ра́ди та́я благода́рні воспі́ша: благослові́те вся діла́ Госпо́дня Го́спода.","Пра́ведниче, я́коже фи́никс в до́му Госпо́дні, о́тче, процві́л єси́ і пра́вди плоди́ прине́сл єси́, і́миже тя чту́щії пита́ються, восклиця́юще: благослові́те вся діла́ Госпо́дня Го́спода.","Богородичен: Глаго́лом благода́тних усте́н Твої́х послі́дующе, ублажа́єм Тя, Присноблаже́нную і взива́єм: благослові́те вся діла́ Госпо́дня Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни а́нгельстії взира́ти; Тобо́ю же, Всечи́стая яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с небе́сними во́ї Тя ублажа́єм.","Приспів: Святи́й блаже́нне Августине, моли́ Бо́га о нас.","Сла́ва твоя́, свя́те, во ві́ки пребива́єть і па́м'ять со всі́ми пра́ведними, с ни́ми же і нам всели́тися моли́, Августине, вели́кий моли́твенниче.","Зарю́ Уті́шителеву, блаже́нне, прия́л єси́, то́ю ни облиста́я і сло́вом Боже́ственним пита́я; воі́стину бо істо́чника непреста́нна благода́ть ми́ру тя показа́, Августине, во ві́ки.","Я́ко со́лнце світоза́рноє ми́ру па́м'ять твоя́ возсія́, о́тче Августине, в приста́нище нем'яте́жноє небе́сноє світоводя́щи ві́рою тя восхваляющия.","Богородичен: Отрокови́це Пречу́дная, пре́жде вік Су́щаго прия́вшая, за кра́йнєє благосе́рдіє Своє́ нам уподобившеєся, і ми́ру Спасе́ніє ро́ждшая, спаси́ ни, ві́рою Тя блажащия."]},{"h":"Світилен","ps":["І́стини ві́дінія ревни́телю, свя́те Августине, є́ресі всегоркия мече́м уст твої́х посі́кл єси́ і, ни́ні на Небесі́х Престо́лу Тро́йці Святи́я предстоя́, прилі́жно о нас моли́ся, ві́рою і любо́вію па́м'ять твою́ соверша́ющих."]}],"notes":[]},{"u":"Канон святителю Павлину Милостивому","e":"Canon to St Paulinus the Merciful","secs":[{"h":"Глас 3. Пісня 1","ps":["Ірмос: Води́ дре́вле ма́нієм Боже́ственним во єди́но со́нмище совокупи́вий, і разділи́вий мо́ре ізра́їльтеським лю́дем, Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Я́ко же ти сам потруди́лся єси́ в писа́нії песен духо́вних, та́ко і ни́ні нас умудри́ воспі́ти твої́ по́двиги, святи́телю.","В житії́ своє́м соблю́л єси́ ві́рность Го́сподеві, ра́бства і нищети́ не убоя́хся, умно́жи у́бо і нам ві́ру, да і не смуща́ється се́рдце на́ше.","Ослабеваєм дерзнове́нієм, упова́нія тве́рдаго не і́мами, на твоє́ же взира́юще ди́вноє житіє́, ду́хом обновля́ємся, святи́телю.","Богородичен: Влади́чице ми́ра, Святи́х блага́я собесі́днице, возглаго́ли сердця́м на́шим утіше́ніє."]},{"h":"Пісня 3","ps":["Ірмос: І́же от несу́щих вся Приведи́й, Сло́вом созида́ємая, соверша́ємая Ду́хом, Вседержи́телю Ви́шній, в любві́ Твоє́й утверди́ мене́.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Ку́пно со святи́телем Павли́ном да почте́ться і супру́га єго́ Тара́сія, я́ко вели́кая жена́ христия́нськая, обрати́вшая му́жа своєго́ ко спасе́нію.","Не імі́я свої́х чад, воспита́л єси́ убо́гих і сиро́т: научи́ і нас о бесприютних ді́тях пещи́ся і разумі́ти ско́рби сиротливих душ.","Посмія́нія друзі́й не убоя́лся єси́, поносивших тя за отрече́ніє от бле́ска мирського, укріпи́ і нас без смуще́нія спаси́тельноє ді́ло Христо́во соверша́ти.","Богородичен: Моли́твами безсі́менно ро́ждшия Тя, Спа́се, поста́ви рабу́ Твоєму́ сло́во Твоє́ і страх Твой, да спасу́ся."]},{"h":"Сідален, глас 7","ps":["Странноприї́мець бил єси́, святи́телю, воззри́ у́бо і на м'я обнищавшего, сокро́вище доброді́телей расточившего, і прийми́ ми́лостиво во вечниі кро́ви, утомленного странствієм земни́м.","Слава, і нині: Ра́дуйся лі́ствице, і́же Іа́ков ви́ді, к Небе́сному Отцю́ нас приводя́щая, Богома́ти Пречи́стая."]},{"h":"Пісня 4","ps":["Ірмос: Положи́л єси́ к нам тве́рдую любо́в, Го́споди, Єдиноро́днаго бо Твоєго́ Си́на за ни на смерть дал єси́. Ті́мже Ті зове́м, благодаря́ще: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Хо́четь враг нас, я́ко пшени́цю, рассеяти, но ти, до́брий деятель Христо́в, собери́ в небесниі жи́тници наслі́діє твоє́.","Я́ко же во дні пліне́нія і про́чих бід бил єси́ уті́шитель па́стви твоєя́, си́це і нас печа́лію помраче́нних просвіти́ наде́ждою на Бо́га.","Преви́ше І́ова воссіял єси́ нището́ю доброво́льною, он бо і на гно́їще свобо́ден преби́сть, ти же во́лею ра́бство прия́л єси́, да Христа́ приобщаєши наві́ки.","Богородичен: Воссіявшая ми́ру вели́коє со́лнце Христа́ сподо́би нас, Влади́чице, животворя́щих і бессмертних луче́й Єго́."]},{"h":"Пісня 5","ps":["Ірмос: К Тебі́ у́треннюю, всіх Творцю́, прейму́щему всяк ум ми́рові, зане́ світ повелі́нія Твоя́, в ни́хже наста́ви м'я.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Мно́гажди отдавал єси́ бі́дним послі́дній хліб із до́му твоєго́: научи́ і нас подражать твоєму́ примі́ру.","Не восхоті́л єси́ радоваться со счастливими, но, па́м'ятуя ско́рби убо́гих страда́льцев землі́, сих участь предпоче́л єси́: нищету́, бесприютность і ра́бство.","В письмах поуча́л єси́ пла́менно о по́льзі моли́тви за усо́пших, ни́ні помо́лимся, святи́телю, о сконча́вшихся близьких на́ших.","Богородичен: О світоно́сная Ді́во! В час ісхо́да моєго́ отве́рзи мі две́рі Небе́снаго Ца́рства, да іді́же Госпо́дь мой, та́мо і аз, слуга́ неключи́мий, вселю́ся."]},{"h":"Пісня 6","ps":["Ірмос: Бе́здна послі́дняя гріхо́в оби́де м'я, і ісчеза́єть дух мой; но простри́й, Влади́ко, висо́кую Твою́ ми́шцю, я́ко Петра́, м'я, Упра́вителю, спаси́.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Ти єси́ супру́жества о Го́споді віне́ць, ти і отрече́нія монашеського о́браз: тім же і мона́си, і мирсті́ї чтим твою́ па́м'ять с любо́вію.","Кто тя досто́йно воспоє́ть, ди́вний Павли́не? Не обріта́єм а́нгельських гла́сов, да восхва́лим челові́ка небе́снаго.","Ни́ні соверши́л єси́ по́двиг твой і зри́ши Бо́га лицом к лицю́: очи́сти і на́ші се́рдця, да убіжі́м от нощі́ сомні́ній і неві́рія.","Богородичен: Влади́чице ми́ра, ослабевшую ду́шу мою́ умудри́ к созерца́нію Боже́ственних виді́ній."]},{"h":"Кондак, глас 8","ps":["Возвіща́л єси́ усе́рдно, святи́телю, о си́лі хода́тайства святи́х за мир, ни́ні пи́санноє тобо́ю ді́лом яви́, я́ко вели́кий уго́дник Бо́жий, возвесели́ се́рдця зову́щих: ра́дуйся, Павли́не, святи́телю ми́лостивий."]},{"h":"Ікос","ps":["А́нгел уті́шитель скорб'я́щих і немощни́х кро́ткий к небесам путеводи́тель бил єси́ в житії́ твоє́м, святи́телю, ду́шу свою́ за спасе́ніє униженних положи́л єси́, тім же ароматом доброді́телей твої́х услаждаєми, велича́єм тя хвале́бно: ра́дуйся, благоуха́нноє ми́ро смире́нія, ра́дуйся, до́брими діла́ми Отця́ прославимий, ра́дуйся, любо́вію ско́рбних согреваяй, ра́дуйся, о́бразе христоподражательного житія́, ра́дуйся, Бо́жию сла́ву жи́зні своє́й проявивий, ра́дуйся, Павли́не, святи́телю ми́лостивий."]},{"h":"Пісня 7","ps":["Ірмос: Я́коже дре́вле благочести́вия три о́троки ороси́л єси́ в пла́мені халде́йстім, сві́тлим Божества́ огне́м і нас озари́, благослове́н єси́, взивающия, Бо́же оте́ць на́ших.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Ти бил єси́, о́тче, садовник іску́сен, твої́ми моли́твами яви́ м'я я́ко цвіт благоуха́нен, насажде́н в садах рая́ пресві́тлаго.","Обрі́т сокро́вище нетлі́нноє Христа́, ти пе́рвіє в гори́ уєдини́лся єси́: вразуми́ і нас безмо́лвіє люби́ти, да в тишині́ ума́ і се́рдця у́зрим Бо́га.","Ти вся позна́нія мирськи́я, всю му́дрость Го́споду посвяти́л єси́, научи́ і нас вся дарова́нія своя́ во сла́ву Єго́ єди́наго обраща́ти.","Богородичен: Влади́чице, Наде́ждо ненаде́жних, не даждь до конця́ поги́бнути ліни́вому рабу́, но си́лою благода́тною ісціли́ расслабленіє во́лі моєя́."]},{"h":"Пісня 8","ps":["Ірмос: Нестерпи́мому огню́ соєдини́вшеся, Богоче́стія предстоя́ще, ю́ноши, пла́менем же неврежде́нні, Боже́ственную піснь поя́ху: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те во вся ві́ки.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Среди́ наше́ствія варварського і нестроє́ній ізве́л єси́ кора́бль па́стви твоєя́ в тишину́ Христо́ву, та́ко і с на́ми сотвори́.","Умоли́ Христа́ Бо́га о Це́ркві, єресьми́, неві́рієм і распрями обуреваємой, даждь па́стирем си́лу і му́дрость пра́во пра́вити сло́во Госпо́дней і́стини.","Вопію́ть к Тебі́ свяще́нних собо́ри і мона́шествующих полки́: на тве́рдом ка́мені ві́ри Христо́вой утверди́ се́рдця, тьмо́ю бід устрашенния.","Богородичен: Світоно́сним омофо́ром Твої́м, Пречи́стая, Це́рков Си́на Твоєго́ всегда́ охраня́й от іскуше́ній і непосильних бід."]},{"h":"Пісня 9","ps":["Ірмос: Но́воє чу́до і Боголі́пноє: діви́чеськую бо двер затворе́нную я́ві прохо́дить Госпо́дь, наг во вхо́ді, і плотоно́сець яви́ся во ісхо́ді Бог, і пребива́єть двер затворе́на. Сію́ неізрече́нно я́ко Богома́тер, велича́єм.","Приспів: Святи́телю о́тче Павли́не, моли́ Бо́га о нас.","Ти єси́ чистоти́ світи́льник і воі́стину друг Бо́жий, істо́ргни нас із бла́та страсте́й і сла́достію духо́вной напита́й.","Ти єси́ врач согрешающим, ти єси́ па́стир прему́дрий, упра́ви на́ше м'яте́жноє житіє́ к оби́телі святи́ні і поко́я ві́чнаго.","Мно́гажди восхвалял єси́ та́йну Святи́я Євхари́стії, пробуди́ в су́єтних душа́х на́ших жа́жду Свята́го Прича́стія.","Богородичен: Преблагослове́нная, Чи́стая, пребу́ди со мно́ю на всяк день же і час, да ра́достен бу́ду, і не впаду́ в сі́ті отча́янія і нече́стія."]},{"h":"Світилен","ps":["Я́ко світи́ло неугасаємоє і по сме́рті показа́лся єси́, святи́телю, благоуха́нієм моще́й твої́х ціле́бних і красото́ю вели́ких чуде́с.","Слава, і нині: Спаси́, Христе́ Бо́же, лю́ди Твоя́, і страну́ осіни́ тишино́ю, за моли́тви Ма́тері Твоєя́ і Павли́на ми́лостиваго."]}],"notes":[]},{"u":"Канон святителю Амвросію, єпископу Медіоланському","e":"Canon to St Ambrose, Bishop of Milan","secs":[{"h":"Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́зними Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Боже́ственними світоли́тії, преподо́бне, облиста́єм, сві́тлоє, і світоно́сноє, і свято́є твоє́ успе́ніє благоче́стно чту́щия твої́ми моли́твами просвіти́.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Сло́во Бо́жиє прему́дрости тебі́ сло́во дарова́, укра́шенноє зна́нієм і́стинним, ієра́рше Амвро́сіє, єрети́чествующих безслове́сноє отража́я зломи́сліє.","Ума́ твоєго́ зри́тельноє, пребога́те, предочи́стив от стра́стния мгли, прия́тно чи́стих блиста́ній Всесвята́го Ду́ха соді́лал єси́, всеблаже́нне.","Всему́дрими і свяще́нними твої́ми догма́ти арієму́дрственную отгна́в па́губу, я́ко па́стир, на зла́ці упа́сл єси́ Правосла́вія, всему́дре, слове́сния твоя́ ві́рою о́вці.","Богородичен: Безсі́менно О́тчею во́лею от Боже́ственнаго Ду́ха Бо́жия зачала́ єси́ Си́на і пло́тію родила́ єси́, із Отця́ безма́терня і нас ра́ди із Тебе́ безо́тча."]},{"h":"Пісня 3","ps":["Ірмос: Не му́дростію, і си́лою, і бога́тством хва́лимся, но Тобо́ю, О́тчею іпоста́сною му́дростію, Христе́: ність бо свят, па́че Тебе́, Человіколю́бче.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Велича́йшу благода́ть от Бо́га приє́м і си́лу, твої́м чу́вственним прикоснове́нієм разли́чния стра́сті, о́тче Амвро́сіє, ісціля́л єси́ приходя́щих к тебі́.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Науче́н, я́ко ієра́рх Боже́ственний, преподо́бне, вся́коє разумі́ніє Писа́нія неві́дущим, о́тче Амвро́сіє, неудобопости́жная я́ві уясни́л єси́.","Тебі́, му́дростію духо́вною сія́ющу, несми́сленно прибли́житися де́рзостно скверні́йшую устре́мльшуюся скорі́йше умертви́л єси́ Боже́ственним приглаго́ланієм.","Богородичен: Род челові́чеський обнови́ла єси́ Єди́на, ро́ждши єстества́ на́шего Соді́теля же і Го́спода, ті́мже Тя сла́вим, Богора́дованная."]},{"h":"Кондак, глас 8","ps":["Ізря́дно сло́во жи́зні стяжа́в, о́тче му́дре, не усумні́ся висоти́ ца́рськия, богонаказа́тельне царя́ обличи́ і умудри́. Тім па́че че́стне почте́ся і люде́й свої́х па́ству к Бо́гу наста́ви. Сего́ ра́ди зове́м ті: ра́дуйся, Амвро́сіє преди́вне."]},{"h":"Сідален, глас 8","ps":["Проро́ка Ілію́ ревнообразу́я і Іоа́нна та́кожде Крести́теля, му́жеськи обличи́л єси́ царя́ беззако́нновавша, ієра́рше; Престо́л Боже́ственне украси́л єси́ і чуде́с мно́жеством мир обогати́л єси́. Ті́мже, і Боже́ственними Писа́нії науче́н, ві́рния утверди́л єси́ і неві́рния обрати́л єси́, ієра́рше Амвро́сіє, моли́ Христа́ Бо́га прегріше́ній оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́.","Богородичен: Помишле́ньми поползо́хся лука́вими, во глубину́ впадо́х гріхо́вную і, стеня́, взива́ю Ті от се́рдця, Пречи́стая: на мні удиви́ бога́тую ми́лость, і Твоєго́ милосе́рдія неізмі́рную пучи́ну, і щедро́т Твої́х неізче́тноє бога́тство, і даждь мі покая́ніє і прегріше́ній проще́ніє, да любо́вію взива́ю Тебі́: моли́ Христа́ Бо́га прегріше́ній оставле́ніє дарова́ти мі: Тя бо наде́жду імі́ю, раб Твой.","Хрестобогородичен: А́гнця, і Па́стиря, і Ізба́вителя А́гниця зря́щи на Кресті́, восклиця́ше, пла́чущи, і, го́рко рида́ющи, вопія́ше: мир у́бо ра́дується, приє́мляй Тобо́ю ізбавле́ніє, утро́ба же Моя́ гори́ть, зря́щи Твоє́ расп'я́тіє, є́же терпи́ши за милосе́рдіє ми́лости. Долготерпіли́ве Го́споди, ми́лости бе́здно і істо́чниче неісчерпа́ємий, умилосе́рдися і да́руй согріше́ній оставле́ніє ві́рою пою́щим Боже́ственния стра́сті Твоя́."]},{"h":"Пісня 4","ps":["Ірмос: Любве́ ра́ди, Ще́дре, Твоєго́ о́браза на Кресті́ Твоє́м стал єси́, і раста́яшася язи́ци: Ти бо єси́, Человіколю́бче, крі́пость моя́ і хвале́ніє.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Ієра́рх показа́лся єси́, пома́зався ми́ром свяще́нства, соверша́я свяще́нники, всім спаси́тельноє да́руя очище́ніє.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Соблю́л єси́ па́ству твою́ от вся́каго вре́да проти́вних, блаже́нне, і А́рієву лесть всю омрачи́л єси́ сія́нієм слове́с твої́х.","Ду́ха си́лою огражде́н, лука́вия отгоня́єши зло́би, всеблаже́нне, ду́хи, не терп'я́щия твоєго́ запреще́нія.","Богородичен: Вся во́лею соді́тельствовавий, соді́тельствується хотя́ от чи́стих Твої́х крове́й, спаса́я ве́дущия Тя, Чи́стую Богома́тер."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой Світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Ум, сія́ющ Сві́том невеще́ственним, стяжа́в, облиста́л єси́ врачева́ній і чуде́с зари́, Амвро́сіє блаже́нне.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Воздви́гл єси́ тебі́ сама́го свяще́нноє жили́ще Ду́ха, разори́л єси́ хра́ми і́дольськия, Амвро́сіє Богодохнове́нне.","Велича́йших доброді́телей світозаре́нієм сія́юща, постиді́шася ца́ріє тебі́ і преді́ла язи́ка твоєго́ не поколеба́ша.","Богородичен: Хоті́нієм все му́дре соді́ловая, хотя́ обнови́ти челові́ки, Ді́во, в Твою́ утро́бу всели́ся."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею Кро́вію.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Рим твоя́ честна́я благохва́лить ісправле́нія: я́ко бо звізда́ світови́дна, всю́ду лучи́ чуде́с твої́х, ієра́рше, іспусти́л єси́, ві́рно удивля́єм.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","У́треневав ко Христу́, та́мо су́щими сві́тлостьми озари́лся єси́ бога́тно, і Сві́та напо́лнился єси́ Боже́ственнійшаго, і просвіща́єши ві́рно чту́щия тя всегда́.","Ті́ло і ду́шу твою́ Бо́гу освяти́в, і прия́тно соді́лал єси́ дарова́ній, о́тче, твоє́ се́рдце, непреста́нно вне́млющеє сла́дкому жела́нію.","Богородичен: Ісціли́ душі́ моєя́, Ді́во, я́зви, осіне́нієм Твої́м Боже́ственним і ум мой просвіти́, омраче́нний лі́ностію і зло́бою врага́ борця́."]},{"h":"Кондак, глас 3","ps":["Боже́ственними догма́ти облиста́я, помрачи́л єси́ А́рієву пре́лесть, священнотаї́нниче і па́стирю Амвро́сіє; чудоді́йствуя же си́лою Ду́ха, стра́сті разли́чния я́ві ісціли́л єси́, о́тче преподо́бне, Христа́ Бо́га моли́, спасти́ся душа́м на́шим."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ Авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем, опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Боже́ственноє віща́ніє твої́х догма́тов, о́тче всему́дре, я́коже мо́лнія, про́йде всю зе́млю і чуде́с показа́ньми, я́ко світ, облиста́, я́же во мра́ці сердца́ просвіща́ющеє.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Законоположе́нієм Спа́са ти послі́дуя, о́тче, да́нний тебі́ тала́нт, я́ко раб блажа́йший, тща́тельно умногосугу́бил єси́, Влади́чнія сподобля́єм ра́дости.","Ізостри́в Богосло́вний твой ум, струї́ свяще́нних догма́тов, я́ко реку́, іспусти́л єси́, напоя́я ві́рних ісполне́ніє, священнотаї́нниче о́тче Амвро́сіє.","Богородичен: Се, Ді́во, во утро́бі Твоє́й зачала́ єси́ Сло́во, Отцю́ собезнача́льно, і пло́тію породила́ єси́ да́рующеє всім воззва́ніє, су́щим із Ада́ма па́дшим, Всенепоро́чная."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р, Данії́л, львов зія́нія в ро́ві затче́; о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Умертви́в у́ди і ме́ртво плотсько́є мудрова́ніє соді́лав, ду́шу оживи́л єси́, преподо́бне, і істо́чник чуде́с істочи́л єси́ умерщвле́нним от страсте́й, жизнь подаю́щи вопію́щим: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Уві́діл єси́ преставле́ніє, му́дре, є́же от тілесе́, Боже́ственним Ду́хом, проро́чеськи бо сіє́ су́щим с тобо́ю сказа́л єси́ і ра́достно на Небеса́, вопія́, восте́кл єси́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Ті́ло, і се́рдце, і ум предочи́стив от страсте́й сміше́нія, огнено́сну лучу́ сви́ше прия́л єси́ Ду́ха, я́коже Боже́ственнії ученици́, вопія́, Амвро́сіє: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Яви́лася єси́ преви́шши Небе́с, Бо́га Небе́снаго поро́ждши, земна́я, Пречи́стая, Небе́сним совоку́пльшаго і позна́ніє Своє́ всім подаю́щаго, вопію́щим: благослові́те, вся діла́ Госпо́дня, Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся — Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Ви́діл єси́, во ізступле́нії бив, ві́чния святи́м, о́тче, лежа́щия по́чести; к ни́мже преше́л єси́, восприє́м твої́х трудо́в, сла́вне, воздая́нія, веселя́ся.","Приспів: Святи́телю о́тче Амвро́сіє, моли́ Бо́га о нас.","Я́ко грозд зрел, Богому́дре, в точи́ліх Го́рніх досто́йно сокро́вищствовался єси́, істоча́я безсме́ртія вино́, Амвро́сіє, і врачева́ній дарова́нія благоче́стно к тебі́ притека́ющим.","Тя, златоза́рний о́тче, Боже́ственнаго Ду́ха світи́льник, світ благочести́вих уче́ній і врачева́ній лучу́ іспуща́ющ і ві́рния просвіща́ющ, велегла́сно ублажа́єм.","Днесві́тлую тя звізду́ Це́рков стяжа́вши, тьми ізбіга́єть вся́кия, всеблаже́нне, льсти і, сві́тлостьми свяще́нних твої́х догма́тов озаря́єма, блажи́ть тя.","Богородичен: Глас Тебі́ вопіє́м, Ді́во, ра́достні Арха́нгелов: ра́дуйся, прокля́тства разріше́ніє лю́тих всіх; ра́дуйся, ізбавле́ніє, земни́я обожи́вшая па́че ума́ Рождество́м Твої́м."]}],"notes":[]},{"u":"Канон святим Петру і Февронії Муромським","e":"Canon to the Holy Peter and Fevronia of Murom","secs":[{"h":"Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Піснь Твоєму́ уго́днику, на землі́ Тебі́ просла́вльшему, Петру́ принести́, Бо́же, да́руй мі, я́ко да Смислода́вця пі́сньми возвели́чу Тя.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Вас, преблаже́ннії, оте́честву ва́шему, я́ко пресві́тлоє со́лнце, Христо́с показа́, чудеси́ всіх озаря́ющеє, ві́рою к вам приходя́щих.","Я́ко о тіле́сних небре́гше, і земна́я, я́ко тлі́нная, возненави́дівше, і сего́ ра́ди ми́ра отре́кшеся, преподо́бних че́сти сподо́бистеся, с ни́миже о ми́рі молі́теся.","Богородичен: Пречи́стая Богоро́дице, ро́ждшая пло́тію присносу́щноє Сло́во Безнача́льнаго Отця́, Присноді́во, Єму́же ни́ні взива́єм: Ізба́вителю Бо́гу на́шему пої́м."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Безпомо́щним бу́ди помо́щник, блаже́нне Пе́тре, і печа́льним ми́лостивноє утіше́ніє, да, твої́ми моли́твами ізбавля́ємі, почита́єм тя.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Я́коже іногда́ змі́я уби́в, коне́чному безві́стію пре́дал єси́, та́ко і ни́ні твоє́ оте́чество борю́щих побіди́, треблаже́нне, да тя прославля́єм.","Виждь уни́ніє, виждь печа́ль, виждь біду́, на ни напа́дающую от проти́вних, ті́мже моли́твою твоє́ю ко Го́споду преміни́, Пе́тре, да благоче́стно тя почита́єм.","Богородичен: Тебі́ всі стяжа́хом, христия́не, прибі́жище і сті́ну і Тебі́ славосло́вим немо́лчно, Безневі́стная."]},{"h":"Сідален, глас 4","ps":["Благослове́нному і світоно́сному торжеству́, я́коже со́лнцю возсія́вшему, Петра́ і Февро́нії, во всем ми́рі, к ни́мже стеце́мся, ві́рнії, і непреста́нно вопіє́м си́це: а́ще і прейдо́сте от землі́, пресла́внії, но нас не отлучи́стеся і та́мо со А́нгели Тро́йце предстоїте́, Ю́же молі́те спасти́ ду́ші на́ша.","Богородичен: Сло́во О́тчеє, Христа́ Бо́га на́шего, от Тебе́ воплоти́вшагося, позна́хом, Богоро́дице Ді́во, Єди́на Чи́стая, Єди́на Благослове́нная. Тім непреста́нно Тя, воспіва́юще, велича́єм."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Я́ко хода́тай і засту́пник оте́честву твоєму́, я́ко сопроти́вних ріши́тель бу́ди, заступа́я лю́ди твоя́, тебі́, Пе́тре, сла́в'ящия.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Я́ко в Небе́сних оби́теліх с преподо́бними і пра́ведними веселя́ся, преблаже́нне Пе́тре ку́пно с Февро́нією, не преста́й моля́ о лю́діх твої́х.","Тебі́ мо́лимся, преблаже́нне, сопроти́вних шата́ніє низложи́ і неду́ги челові́ков облегчи́, я́ко да во гла́сіх хвале́нія тебі́ велича́єм.","Богородичен: Очище́ніє на́шим да́руй прегріше́нієм, я́ко Пребла́г, і умири́ мир Твой, Бо́же, моли́твами ро́ждшия Тя."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма, окая́ннаго? Но обрати́ м'я і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Земля́ освяти́ся, приє́мши честна́я тілеса́ ва́ша, Богоблаже́ннії Пе́тре і Февро́ніє, челові́ци же, приє́млюще ва́ми ісціле́ніє, Христа́ сла́в'ять, і́скренно вас просла́вльшаго.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","А́ще і прейдо́сте от землі́, но к Небе́сним доспі́сте і та́мо со А́нгели Тро́йце предста́сте, Ю́же молі́те спасти́ любо́вію вас почита́ющих, блаже́ннії.","Я́ко зві́зди пресві́тлия і я́ко незаходи́моє со́лнце, стяжа́вше вас, оте́чество ва́ше хва́литься, почита́юще па́м'ять ва́шу пречестну́ю, Пе́тре і Февро́ніє.","Богородичен: Ді́ву поє́м Тя по рождестві́, Богоро́дице, Ти бо пло́тію Бо́га Сло́ва нам родила́ єси́, Єму́же всі си́це зове́м: путі́ на́ша напра́ви, мо́лим Ті ся."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, / і із глубини́ зол возведи́, молю́ся, / к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","О пречестна́я дво́їце! О вели́ції світи́льници! Освяті́те і просла́віте любо́вію вас в пі́сніх сла́в'ящих, чудотво́рці.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Я́ко пресві́тлая дво́їце і я́ко пречестна́я верста́ і благосочета́ніє, яре́м Госпо́день взе́мше, Тому́ от душі́ порабо́тасте.","Я́ко сові́тници до́брії своєму́ житію́, єди́ну мисль во двою́ ті́лу іму́ще, мир чудеси́ просвіща́єте, ті́мже і нас озарі́те моли́твами ва́шими.","Богородичен: Уясня́ють проро́честії гла́си Бо́жию Тя, Ді́во, Роди́тельницю, поє́м же Тя і ми, ви́дяще сбитіє́ честни́х прориця́ній, ді́вству воі́стину і чистоті́ вмісти́лище."]},{"h":"Кондак, глас 8","ps":["Ми́ра сего́ княже́ніє і сла́ву вре́менну помишля́я, сего́ ра́ди благоче́стно в ми́рі пожи́л єси́, Пе́тре, ку́пно і с супру́жницею твоє́ю прему́дрою Февро́нією, ми́лостинею і моли́твами Бо́гу угоди́вше. Ті́мже, і по сме́рті неразлу́чно во гро́бі лежа́ще, ісціле́ніє неви́димо подава́єте, і ни́ні Христу́ молі́теся сохрани́ти град же і лю́ди, і́же вас сла́в'ящих."]},{"h":"Ікос","ps":["Уясни́ язи́к мой, Спа́се, і умири́ се́рдце моє́, разшири́ уста́ моя́ і напо́лни Ду́ха і прему́дрости, да і́миже возглаго́лю і воспою́ си́це Твоя́ чудотво́рці: ра́дуйся, Пе́тре блаже́нне с прехва́льною Февро́нією вку́пі. Ра́дуйтеся, землі́ Українській засту́пниці і князе́м правосла́вним помо́щници. Ра́дуйтеся, оте́честву ва́шему храни́тели і гра́ду на́шему утвержде́ніє. О пречестна́я дво́їце і благо́є сопряже́ніє, Христу́ молі́теся сохрани́ти град і лю́ди, і́же вас сла́в'ящих."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше, о́троци во Вавило́ні іногда́ ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще: отце́в Бо́же, благослове́н єси́.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","В болі́зні к тебі́ прибіга́ющих ізбавля́й, преблаже́нне Пе́тре ку́пно с Февро́нією, Христу́ вопію́щих: оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Всім приста́нище бу́діте, преблаже́ннії, і небу́рноє оти́шіє су́щим во грісі́х, да і ми с ва́ми Христу́ возопіє́м: оте́ць на́ших Бо́же, благослове́н єси́.","Прибі́жище да мі бу́діте в день гні́ва, Богоблаже́ннії, я́ко посреді́ хожду́ сіте́й мно́гих: ті́мже ізба́віте м'я от них, да возмогу́ воспі́ти вас.","Днесь пресла́вная па́м'ять Петра́ і Февро́нії, я́ко со́лнце, возсія́ в ми́рі, в ню́же соше́дшеся, всі воспоє́м си́це: оте́ць на́ших Бо́же, благослове́н єси́.","Богородичен: Ка́пля Богото́чная, от Тебе́ ро́ждшаяся, мир освяти́, Богоро́дице Ді́во: ка́плі мні ми́лости істочи́, освяща́ющия ду́ші і помишле́нія земни́х."]},{"h":"Пісня 8","ps":["Ірмос: Царя́ Небе́снаго, Єго́же пою́ть во́ї А́нгельстії, хвалі́те і превозносі́те во вся ві́ки.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Очи́сти і прости́ согріше́нія на́ша, Безгрі́шне, моли́твами Твої́х уго́дник Петра́ і Февро́нії, да поє́м Тя, Христе́, во ві́ки.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","І́же от се́рдця руко́ю недосто́йною приноси́моє вам хвале́ніє, блаже́ннії, приймі́те і мольбу́ сотворі́те о нас ко Христу́ Бо́гу.","Тро́їчен: Півце́м, Тебі́ пою́щим, Тро́йце Пресвята́я, согріше́нія оста́ви, я́ко Пребла́га, моли́тв ра́ди Петра́ і Февро́нії, да Тя поє́м во ві́ки.","Богородичен: Божества́ сосу́д би́вши, Чи́стая, просвіти́ м'я в повелі́нії Сві́та ходи́ти, Пречи́стая, от чре́ва Твоєго́ возсія́вшаго і просвіти́вшаго ві́рних сердця́."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю Тя іспові́дуєм, спасе́ннії Тобо́ю, Ді́во Чи́стая, с Безпло́тними ли́ки Тя велича́юще.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","От ю́ности ва́шея чи́стую со́вість іму́ще к Бо́гу, сего́ ра́ди, благоче́стно пожи́вше, к Ви́шнім прейдо́сте. Молі́те Христа́ о нас, да вас любо́вію почита́єм.","Приспів: Святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє, молі́те Бо́га о нас.","Я́ко предстоя́ще Святі́й Тро́йці с преподо́бними і пра́ведними, молі́теся, блаже́ннії, ізба́вити нас вся́каго преще́нія і гні́ва, да вас непреста́нно велича́єм.","Лю́діє твої́ мо́лять тя, Богоблаже́нне Пе́тре, ку́пно моли́ Христа́ с прему́дрою Февро́нією, с не́юже в ми́рі богоуго́дно пожи́л єси́, ізба́вити нас от вся́ких зол.","Богородичен: О, чудесе́ вели́каго! Ка́ко вмісти́ся во утро́бу Твою́ Христо́с Бог, ніка́коже вмісти́мий? Єго́же за хва́лящия Тя умоли́, Ді́во, от бід ізба́вити нас і от беззако́нних челові́к всегда́."]},{"h":"Світилен","ps":["І́же благоче́стно пра́зднующим па́м'ять ва́шу, Богоблаже́ннії Пе́тре і Февро́ніє, вку́пі ми́рно пожи́вше і благоче́стно, молі́те Христа́ гріхо́в оставле́ніє дарова́ти рабо́м ва́шим.","Богородичен: Пресвята́я Богоро́дице, упова́ніє на́ше і похвало́, Тя єди́ну ві́дуще, ві́рою покланя́ющеся, мо́лим: ра́дуйся, Неіскусобра́чная Свята́я Марі́є, покро́ве і огражде́ніє на́ше і Помо́щниця су́щим в біда́х. Моли́ Христа́, Си́на Твоєго́, за раби́ Твоя́, на Тя бо наді́ємся."]}],"notes":[]},{"u":"Канон преподобному Дмитрію, ігумену Прилуцькому, Вологодському","e":"Canon to St Demetrius, Abbot of Pryluky, of Vologda","secs":[{"h":"Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь: сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Тебі́ твоєго́, блаже́нне, уче́нія долг принося́ще, возда́нія простира́єм, віне́ць похвала́ми плету́ще: ти же ми́лостив яви́ся, пребога́те: твої́ми мольба́ми благода́ть нам пода́ждь духо́вную.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Всегуби́тельноє стремле́ніє страсте́й, о́тче, ув'яди́л єси́, слове́сним об'я́т Богому́дрієм: благопреби́тен бо бил єси́ і благогла́сен, кро́ток же і смире́н, сло́вом прему́дрости, Дими́тріє, і ра́зума вінча́н.","Священноукраси́л єси́ себе́, о́тче, ра́зумом, і ді́тельним виді́нієм благода́ті, Богоглаго́ливе Дими́тріє, жела́я вінця́ сла́ви Христо́ви, і твою́ наде́жду ізря́дно, преблаже́нне, не погріши́л єси́.","Целому́дріє удержа́л єси́ я́ві, кра́йнюю же кро́тость, і висо́коє, Богоно́се, смире́ніє, і́миже возвиша́єм, трудо́в твої́х ді́йством і виді́нієм ра́дуяся принесе́ся, віне́ць неув'яда́ємий приє́м.","Богородичен: Тва́рей яви́лася єси́, Чи́стая, всіх ви́димих і неви́димих преви́шши, Всенепоро́чная: Зижди́теля бо родила́ єси́, я́коже ізво́ли воплоти́тися во утро́бі Твоє́й. Єго́же со дерзнове́нієм моли́ спасти́ пою́щия Тя."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня, я́ко крин, Го́споди, язи́чеськая неплодя́щая це́рков, прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Просія́л єси́ в житії́ твоє́м, Богоно́се Дими́тріє, я́коже всесві́тлоє со́лнце в ми́рі, і просвіти́ і́же к тебі́ ві́рою і любо́вію приходя́щия і пою́щия тя.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Просвіща́ються конці́ уче́нії твої́ми, преподо́бне: я́коже бо світи́льник просвіти́л єси́, Богоно́се, Це́рков Христо́ву, о не́йже утверди́ся моє́ се́рдце.","Непорабоще́ну соблю́л єси́ ду́шу твою́ страстьми́, і сластьми́ тіле́сними, Богоно́се Дими́тріє всече́стне: ті́мже ни́ні по достоя́нію восхваля́єм тя.","Богородичен: Сказа́ іногда́ сокрове́нноє та́їнство, Отрокови́це, Тебі́ дре́вле Гавриї́л зов'я́ше: ра́дуйся, Бо́жия Пала́то, в Ню́же всели́ся, вся челові́ки обожи́, я́ко Милосе́рд."]},{"h":"Сідален, глас 3","ps":["Ісправле́нія житія́ твоєго́ всім просвіща́єть стопи́, Дими́тріє о́тче, воі́стину ві́рою подо́б'ящим ті ся: ті́мже і́же любо́вію блажа́ть тя всегда́, спаса́й моли́твами твої́ми от вся́кия тісноти́, Христа́ Преблага́го моля́, преподо́бне блаже́нне досточу́дне.","Богородичен: Я́ко невозді́ланная, Ді́во, Лоза́, красні́йшій Грозд прозябла́ єси́, істоча́ющ нам вино́ спасе́нія, всіх веселя́щеє ду́ші же і тілеса́. Ті́мже я́ко вину́ Тя до́брих блажа́ще при́сно, со А́нгелом вопіє́м Ті: ра́дуйся, Благода́тная."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви, не хода́тай, ні А́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Ти, Дими́тріє, і́нокующим бисть віне́ць, не ка́менієм многоці́нним укра́шен, но доброді́телію обложе́н, яви́лся єси́, блаже́нне, Богора́дованноє воі́стину украше́ніє.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Боже́ственную, Богому́дре, поче́л єси́ прему́дрость: ті́мже дарова́нії тя сія́ одари́, сла́ву ві́чную тебі́ хода́тайствовавшу, о́тче Дими́тріє всече́стне.","Сві́тлостію нрав твої́х, і о́брази бла́гости, преподо́бне Дими́тріє, подо́бні пожи́л єси́: ті́мже присту́пен ти всім бисть, всеблаже́нне, і пречу́дне.","Богородичен: Умерщвле́нія плод нам Є́ва принесе́, Ти же Жизнь ро́ждши Іпоста́сную, а́біє іспра́вила єси́ род наш, Богоневі́сто Пречи́стая."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо, Влади́ко, к Світонача́льнику Отцю́ Твоєму́, от но́щі неві́дінія приведе́ніє і́мами.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Стремле́ніє страсте́й безстра́стієм удержа́л єси́, Богоно́се Дими́тріє: виді́нії і дія́нії просвіти́л єси́, о́тче, душе́вноє устроє́ніє.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Умо́м чи́стим і писа́нії духо́вними бесі́довал єси́, Богоглаго́ливе Дими́тріє, виді́нія і дія́нія собра́в бога́тство, о́тче преподо́бне.","Прему́дрости глубину́ іспита́в, Дими́тріє, дости́гл єси́ обрісти́ єли́ко благопотре́бно, і би́сер многоці́нний болі́зньми стяжа́л єси́, преблаже́нне, ра́зума.","Богородичен: Се во чре́ві, Богоро́дице Пречи́стая, Христа́ Бо́га па́че сло́ва імі́ла єси́, я́коже Іса́їя провозгласи́: ви́ше єстества́ Сего́, Богороди́тельнице, родила́ єси́."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Вселе́нній світи́ло пресві́тлоє, о́тче, яви́лся єси́, Дими́тріє, слове́с сві́тлостію просвіща́я ві́рою і любо́вію к тебі́ притека́ющия.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Блаже́нноє житіє́ проше́л єси́, назда́в у́бо чу́вства, вні бил єси́ мирська́го м'яте́жа, і Бо́гу прибли́жился єси́, Дими́тріє.","Я́ко добр, я́ко красе́н віне́ць, і́мже ни́ні вінча́лся єси́, прему́дре Дими́тріє, доброді́тельми вінча́єм, і над страстьми́ ца́рствовав, преізря́дне.","Богородичен: Ви́ше єстества́ родила́ єси́, Ді́во, і ві́чнуєши Ді́ва, я́вльши і́стиннаго Божества́ Си́на і Бо́га Твоєго́ о́брази."]},{"h":"Кондак, глас 8","ps":["От ю́ности, преподо́бне, крест твой взем, Христу́ послі́довал єси́, в моли́твах і поще́ніїх, во бді́ніїх же і злострада́ніїх плоть твою́ ізнуря́я: ті́мже і Всеви́дящеє О́ко твоя́ труди́ ви́дів, чудеси́ тя прославля́єть, і всіх зва́ти тебі́ науча́єть: ра́дуйся, преподо́бне о́тче Дими́тріє, по́стников удобре́ніє."]},{"h":"Ікос","ps":["Боже́ственними доброді́тельми твої́ми себі́, му́дре, украси́л єси́, Спа́су Христу́ жили́ще соді́лав, о́тче му́жественні: я́коже зла́то іскуси́лся єси́ ві́рою к Бо́гу, і наде́ждею і любо́вію обі́ти полага́я, воздержа́нієм пости́вся я́ко безпло́тен, в цілому́дрії і во смире́нії возне́слся єси́. Ті́мже і ми моли́твами твої́ми просві́щшеся, преподо́бне Дими́тріє, вопіє́м ті: ра́дуйся, я́ко із мла́да Бо́гу послужи́л єси́: ра́дуйся, притека́ющим к тебі́ спасе́нія хода́таю: ра́дуйся, христоімени́тим лю́дем похвала́ і утвержде́ніє: ра́дуйся, я́ко твої́ми моли́твами сопроти́внії побіжда́ються: ра́дуйся, я́ко всім прося́щим дає́ши дар, от Го́спода дарова́нний ті ісціле́ній: ра́дуйся, я́ко і чудеси́ тя Бог прославля́єть, і всіх зва́ти тебі́ науча́єть: ра́дуйся, преподо́бне о́тче Дими́тріє, по́стников удобре́ніє."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий благослове́н і препросла́влен.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Благоуха́ють, преподо́бне, твої́х уче́ній словеса́, благода́тію ду́ха сія́юще: Божество́ бо єди́но чтий в Трех Ли́ціх, Сло́ва же воплоще́ніє поя́, благоуха́єши нас, пребога́те.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Ума́ чистото́ю і по́мисла, Богоразу́мія сві́тлостію житіє́ преше́л єси́, чистото́ю же тілесе́, і ді́вства сія́нієм ізря́дно возложе́ніє я́влься Всеви́дцю і Вседержи́телю.","Сло́во твоє́ со́лію растворе́но, і житіє́ твоє́ благода́тію, преблаже́нне, сія́я яви́ся, пречу́дне: ті́мже во ви́шнія оби́телі ра́дуяся всели́лся єси́, Христу́ со дерзнове́нієм ни́ні предстоя́.","Богородичен: Управля́ющи, Пречи́стая, моє́ житіє́, к Твоєму́ всети́хому приста́нищу напра́ви, Бо́га ро́ждши, благи́х істо́чника, всім подаю́ща ві́рним нетлі́нія благода́ті."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, бо́жиїм велі́нієм, халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Віне́ць благолі́пен Христо́с Живода́вець на верх твой положи́ тезоімені́те Дими́тріє: і́бо дія́ньми просія́л єси́, і виді́нії яви́лся єси́ зови́й: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Все преше́д чу́вство, преблаже́нне, уму́ пе́рвому прибли́жился єси́ душі́ твоєя́ чистото́ю, житія́ же сві́тлостію, вінцено́сче Дими́тріє, зови́й: благослові́те, вся діла́ Госпо́дня, Го́спода.","Жела́нієм зі́льним, преблаже́нне, ізслі́дил єси́ Богоно́снаго Се́ргія вели́каго житіє́ Боже́ственноє, жи́зні сві́тлостію поревнова́л єси́, прехва́льне, бив у́бо і собесі́дник сего́ ізря́ден воі́стину.","Богородичен: Ум безстра́стен во утро́бі Твоє́й соєдиня́ється челові́чеському уму́, Пречи́стая, пло́ті же дебельство́м под лі́том бив літ преви́шшій. Тім Тя, Богоро́дице, ві́рою і любо́вію сла́вим."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная. Тім Всепі́тую Богоро́дицю велича́єм.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Пречестни́й Дими́тріє, ни́ні чи́сто услажда́яся і пи́щу приє́мля па́че у́мния, іді́же собо́ри святи́х о́крест Го́спода лику́ють, блаже́нне, і́же тя ни́ні чту́щия хода́тайствуя к себі́ привлеци́.","Приспів: Преподо́бне о́тче Дими́тріє, моли́ Бо́га о нас.","Преше́л єси́ ра́дуяся жела́нієм в рай к єди́ному воі́стину блаже́нству, к пребо́льшей добро́ті, і к жи́зні воі́стину нестарі́ющейся, і Сві́ту Невече́рнему, Богоно́се о́тче Дими́тріє.","Я́ко Со́лнце просія́л єси́ в мона́шеських собо́ріх, от млади́х ногте́й освяще́н бил єси́, я́коже зарю́ іспуща́я доброді́телі твоєго́ житія́, пресла́дкий Дими́тріє, Богоно́се о́тче преподо́бне.","Богородичен: Разумі́вше іздале́ча прозорли́вима очи́ма проро́ци, тя я́ві провозвісти́ша хотя́щую Ма́тер би́ти Вседі́телю Влади́ці всіх: тім тя, всепі́тая, Богоро́дицю іспові́дуєм."]},{"h":"Світилен","ps":["Мирська́го пристра́стія я́ко от скве́рни уклони́лся єси́, і а́лчбою плоть ув'яди́л єси́, о́тче, і небе́сною сла́вою со А́нгели обогати́лся єси́: ті́мже непреста́нно моли́ о нас Христа́ Бо́га, преподо́бне Дими́тріє.","Богородичен: Тя предста́тельницю і́мами всі грі́шнії о Пресвята́я Ді́во! Ти благопремі́нна сотвори́ Си́на Твоєго́ Ма́терніми Твої́ми моли́твами."]}],"notes":[]},{"u":"Канон святим Царственним страстотерпцям","e":"Canon to the Holy Royal Passion-Bearers","secs":[{"h":"Пісня 1","ps":["Ірмос: Волно́ю морсько́ю Скри́вшаго дре́вле гони́теля мучи́теля под земле́ю скри́ша спасе́нних о́троци; но ми, я́ко отрокови́ці, Го́сподеві пої́м, сла́вно бо просла́вися.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Вінцено́сче Нико́лає, вку́пі с му́ченичеськими ли́ки, цари́цею, ча́ди і слуга́ми, предстоя́ще у Престо́ла Христо́ва, просвіще́ніє нам да́руйте, озаря́ющеє душ на́ших омраче́ніє і нечу́вствіє, я́ко да восхва́лим ра́достно ва́шу блаже́нную па́м'ять.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Ни́ні прорече́ніє Саро́вськаго ста́рця, я́ко просла́вльшаго м'я просла́вить Бог, іспо́лнися, просла́ви бо Це́рков Українськая ца́рственнаго страстоте́рпця. Ті́мже вку́пі с преподо́бним мо́литься, во є́же стяжа́ти нам благода́ть Свята́го Ду́ха.","Се́рдце царе́во в руці́ Бо́жієй, глаго́леть Госпо́дь. Ти же, і́стинний пома́занниче і слуго́ Госпо́день, благогові́йні рекл єси́: не то́кмо жизнь моя́, но і путіє́ страни́ Українськия в руці́ Госпо́дній суть.","Богородичен: Ти єси́ крі́пость на́ша, Ти єси́ похвала́ і ра́дованіє, Предста́тельниця Непобіди́мая і Покро́в держа́вний страни́ Українськия, Пресвята́я Богоро́дице, с ца́рственними страстоте́рпці і новому́ченики моли́ спасти́ раби́ Твоя́."]},{"h":"Пісня 3","ps":["Ірмос: Тебі́, на вода́х Пові́сившаго всю зе́млю неодержи́мо, твар ви́дівши на Ло́бнім ви́сима, у́жасом мно́гим содрога́шеся, ність Свят, ра́зві Тебі́, Го́споди, взива́ющи.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Поруга́ніє і разоре́ніє землі́ своєя́ от безбо́жних ви́дя, благочести́вий царю́, пла́кася із глубини́ серде́чния, я́ко проро́к Ієреми́я, го́рці стеня́ і моля́ся за лю́ди согреши́вшия: Ми́лостиве Го́споди, не оста́ви їх, оста́вльших м'я.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","На землі́ алка́л і жа́ждал єси́ пра́вди Бо́жия, за ню́же ду́шу кро́тці положи́л єси́, пра́ведне Нико́лає, оба́че в Го́рнем Ца́рствії наси́тился єси́, іді́же пребива́єши во ві́ки.","Врачева́нія і чудеса́ то́чіте, святі́ї страстоте́рпці, лю́дем, ві́рою к вам притека́ющим, ті́мже печа́ль на́шу на ра́дость преложі́те моли́твами ва́шими.","Богородичен: Прибі́жище, Ви́шшій Покро́в Тя і́мами, Благослове́нная Ма́ти Бо́жия, Твоє́ю по́мощію сохрани́ і заступи́ нас, Всепі́тая."]},{"h":"Сідален, глас 4","ps":["Єгда́ мно́зі от сро́дник на́ших отступи́ша от Бо́га, отврати́шася Бо́жиїх за́повідей і воста́ша на Го́спода і пома́занника Єго́, тогда́ гнів Бо́жий на зе́млю Українськую приї́де, ізся́че люби́ мно́гих, пролія́ся кров бра́тій на́ших, расточи́шася лю́діє Українськії по всему́ лицю́ землі́, хра́ми на́ші поруга́нію преда́шася, гла́ди, наше́ствія іноплеме́нник постиго́ша ни, і би́хом в посмія́ніє язи́ков. Ми же, разумі́юще сіє́, с сокруше́нієм се́рдця в покая́нії зове́м: прости́ і поми́луй нас, Го́споди, по вели́цій ми́лості Твоє́й, очи́сти беззако́нія на́ша і пода́ждь стра́ждущей страні́ Українській предста́тельством ца́рственних страстоте́рпець проще́ніє гріхо́в, мир і ве́лію ми́лость.","Богородичен: Умоли́, Милосе́рдая Ма́ти Сві́та, Си́на Твоєго́ і Бо́га на́шего о є́же возста́вити держа́ву на́шу Правосла́вную, сохрани́ти ю в ми́рі і благоде́нствії, ізба́вити ни от междоусо́бния бра́ні, укріпи́ти Святу́ю Це́рков і огради́ти ю от неві́рія, раско́ла і єресе́й."]},{"h":"Пісня 4","ps":["Ірмос: На Кресті́ Твоє́ Боже́ственноє істоща́ніє прови́дя, Авваку́м, ужа́сся, вопія́ше: Ти си́льних пресі́кл єси́ держа́ву, Бла́же, приобща́яся су́щим во а́ді, я́ко Всеси́лен.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Нището́ю духо́вною обогати́лся єси́, свя́те Нико́лає, і сотвори́ тя Госпо́дь досто́йна не то́кмо земна́го, но і Небе́снаго Ца́рствія.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Ско́рбію обдержи́м бисть, вінцено́сче Нико́лає, зря осліпле́ніє наро́да твоєго́, отре́кшагося от Царя́ Небе́снаго, та́кожде і земна́го.","Му́жественні возложи́в упова́ніє на Бо́га в многострада́льнім земні́м служе́нії твоє́м, я́коже І́ов іногда́, стори́цею воздая́ніє прия́л єси́ на Небесі́х, іді́же ни́ні наслажда́єшися, ца́рственний му́чениче.","Богородичен: Милосе́рдія две́рі, Благослове́нная Богоро́дице, отве́рзи нам, да ізба́вимся от бід і озлобле́нія на́шего, во є́же пі́ти Тебі́ непреста́нно: Ти єси́ спасе́ніє ро́да христия́нськаго."]},{"h":"Пісня 5","ps":["Ірмос: Богоявле́нія Твоєго́, Христе́, к нам ми́лостивно би́вшаго, Іса́їя, Світ ви́дів Невече́рній, із но́щі у́треневав, взива́ше: воскре́снуть ме́ртвії, і воста́нуть су́щії во гробі́х, і всі земноро́днії возра́дуються.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Миротво́рець яви́лся єси́, царю́ Нико́лає святи́й, неся́ мир ми́ру, спаса́я і защища́я ти́сящи во Оте́честві твоє́м і в іни́х страна́х, сего́ ра́ди син Бо́жий, по сло́ву Госпо́дню, наре́клся єси́.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Ізгна́ніє, поноше́ніє, гоне́ніє і всяк глаго́л ло́жний, на ви рече́нний, претерпі́сте, святі́ї ца́рственнії му́ченици. Ра́дуйтеся у́бо і веселі́теся, я́ко мзду ва́шу на Небесі́ прия́сте.","Служи́теліє беззако́нія та́йнаго, віне́ць терно́вний спле́тше, возложи́ша на тя, ца́рственная главо́, оба́че де́рзостная діла́ їх погибо́ша я́ві.","Богородичен: В ти́ну гріхо́во впа́ли єсьми́, і лю́ті потопи́ ни бу́ря прегріше́ній. Но, я́ко ро́ждшая Спа́са, Влади́чице, при́зри на ни, раби́ Твоя́, і ізба́ви от страсте́й душетлі́нних."]},{"h":"Пісня 6","ps":["Ірмос: Ять бисть, но не удержа́н в пе́рсіх ки́тових Іо́на: Твой бо о́браз нося́, страда́вшаго і погребе́нію да́вшагося, я́ко от черто́га, от зві́ря ізи́де; приглаша́ше же кустоді́ї: храня́щії су́єтная і ло́жная, ми́лость сію́ оста́вили єсте́.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Всім правосла́вним засту́пник бил єси́, богоізбра́нний Нико́лає, наро́дом Слове́нським защи́ту благу́ю явля́яй і, я́ко брат бра́ту, помога́яй.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","О си́ні ві́рний Святи́я Це́ркве! Ти ревни́тель прославле́нія святи́х яви́лся єси́, хра́мов созида́тель, святи́х оби́телей благоукраси́тель, Святи́я Землі́ і Гори́ Афо́нськия благотвори́тель, просвіще́нія правосла́внаго попечи́тель і мона́шества покрови́тель.","В житії́ ва́шем і в ді́ліх любве́ о́браз христия́ном би́сте, боговінча́ннії ца́ріє Нико́лає і Алекса́ндро, полага́сте бо во главу́ у́гла Ка́мень, Христа́, Бо́га на́шего.","Богородичен: К Тебі́ прибіга́єм, Цари́це Держа́вній, ві́рних покро́ве, на Тя наде́жду возлага́єм спасе́нія на́шего, Пресвята́я Влади́чице Богоро́дице, не пре́зри нас."]},{"h":"Кондак, глас 8","ps":["Ізбра́ннії Царе́м ца́рствующих і Го́сподем госпо́дствующих от ро́да царе́й Українських, благові́рнії му́ченици, му́ки душе́вния і смерть тіле́сную за Христа́ приі́мшії і вінці́ Небе́сними увінча́вшіїся, к вам, я́ко покрови́телем на́шим ми́лостивим, с любо́вію благода́рні вопіє́м: ра́дуйтеся, ца́рственнії страстоте́рпці, за Україну Святую пред Бо́гом усе́рднії моли́твенниці."]},{"h":"Ікос","ps":["Сла́вою і бога́тством благоче́стія сія́ющії, багряни́цею многоці́нною і вінце́м украше́ннії, ми́лостію і пра́вдою в житії́ просія́вшії, ві́ру, наде́жду і любо́в к Бо́гу до конця́ яви́ли єсте́. К вам, я́ко покрови́телем на́шим ми́лостивим, с любо́вію благода́рні вопіє́м: ра́дуйтеся, ца́рственнії страстоте́рпці, за Україну Святую пред Бо́гом усе́рднії моли́твенниці."]},{"h":"Пісня 7","ps":["Ірмос: Неізрече́нноє чу́до, в пещі́ Ізба́вивий преподо́бния о́троки із пла́мене во Гро́бі мертв, бездиха́нен полага́ється во спасе́ніє нас, пою́щих: Ізба́вителю, Бо́же, благослове́н єси́.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Я́ко при́сних ва́ших, неду́жних во́їнов чадолю́бне посеща́сте, ца́рственнії му́ченици, і с любо́вію їх утеша́сте, міста́ же їх упокоє́нія слеза́ми ва́шими ороша́сте.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Ви єсте́ о́браз супру́жества доброді́тельнаго і діте́й воспита́нія благочести́ваго, святі́ї ца́ріє Нико́лає і Алекса́ндро. Дом ваш я́ко цвітни́к духо́вний соді́лавше, на Небесі́х ни́ні вку́пі со ча́ди лику́єте.","На висоті́ сла́ви челові́чеськія пребива́я, о Небе́сних при́сно помишля́л єси́, царю́ Нико́лає, а́може устреми́ся душа́ твоя́ свята́я.","Богородичен: Всесвята́я Влади́чице, оживи́ ум наш, умерщвле́нний страстьми́ мно́гими, і укріпи́ ни богоуго́дная твори́ти, да велича́єм Тя, я́ко Засту́пницю ро́да христия́нськаго."]},{"h":"Пісня 8","ps":["Ірмос: Ужасни́ся, боя́йся, Не́бо, і да подви́жаться основа́нія землі́: се бо в мертвеці́х вміня́ється во Ви́шніх Живи́й і во Гроб мал странноприє́млеться. Єго́же, о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Єгда́ уго́дниці Бо́жії предреко́ша вам путь му́ченичеський, я́коже Па́влу проро́к Ага́в, ви, ца́рственнії страстоте́рпці, не уклони́стеся ні одесну́ю, ні ошу́юю, но му́жественні проідо́сте єго́, взира́юще на Соверши́теля ві́ри Ісу́са Христа́.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Во страда́ніїх ва́ших, страстоте́рпці святі́ї, не отверго́стеся Путі́, І́стини і Живота́, Христа́ Бо́га на́шего, не устраши́стеся богобо́рцев, но в терпі́нії ше́ствовасте ца́рським путе́м в жизнь ві́чную.","Уви́ нам, оте́чеськия заві́ти попра́вшим, от обі́та ві́рности ца́рському ро́ду, Це́рковію Свято́ю благослове́нному, отсту́пльшим і та́ко от путі́ Бо́жия отлучи́вшимся. Прості́ нас, Го́споди, за вся сія́ соді́янная і поми́луй моли́твами святи́х страстоте́рпець.","Богородичен: Засту́пницю на́шу Тя ві́ми, Богоро́дице, непреста́нно бо о нас мо́лишися, во є́же пока́ятися і іспра́витися нам, упова́ніє і прибі́жище душ на́ших."]},{"h":"Пісня 9","ps":["Ірмос: Не рида́й Мене́, Ма́ти, зря́щи во Гро́бі, Єго́же во чре́ві без сі́мене зачала́ єси́ Си́на: воста́ну бо, і просла́влюся, і вознесу́ со сла́вою непреста́нно, я́ко Бог, ві́рою і любо́вію Тя велича́ющия.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Да воскреснеть Україна Свята́я моли́твами ца́рственних страстоте́рпець і новому́ченик Твої́х, Го́споди, і да расточа́ться всі вразі́ єя́ вско́рі, і от лиця́ єя́ да біжа́ть всі ненави́дящії ю от ни́ні і до ві́ка.","Приспів: Святі́ї ца́рственнії страстоте́рпці, молі́те Бо́га о нас.","Все упова́ніє на Го́спода возложи́ держа́вний цар наш. Та́кожде і ми со упова́нієм Го́споду помо́лимся, да укріпи́ть Он моли́твами Богоро́диці і ца́рственнаго страстоте́рпця страну́ на́шу в Правосла́вії і спасе́ть ду́ші на́ша.","Я́ко досто́йноє пі́ніє приймі́те, святі́ї страстоте́рпці, ма́лоє моле́ніє сіє́ і, я́коже Христо́с прия́т вдови́ці дві ле́пті, не возгнуша́йтеся нас, окая́нних, страстьми́ обурева́ємих, убо́гих чти́телей і служи́телей ва́ших.","Богородичен: Держа́вним Твої́м покро́вом, Чи́стая, раби́ Твоя́ сохрани́ вся невреди́ми: Тя бо єди́ну і́мами прибі́жище в ну́ждах, утіше́ніє в ско́рбіх і побі́ду во бранеіх на́ших."]},{"h":"Світилен","ps":["Невече́рнему Сві́ту предстоя́ще, страстоте́рпці святі́ї ца́рственнії, с му́ченичеськими ли́ки, во іспита́ніїх не оставля́йте ни моли́твами ва́шими.","Слава, і нині: Ро́ждшая Світ Незаходи́мий, просвіща́ющий сідя́щих во тьмі неві́дінія і пре́лести, озари́ і нас, грі́шних, сві́том Си́на Твоєго́."]}],"notes":[]},{"u":"Канон святителю Никиті Печерському, єпископу Новгородському","e":"Canon to St Nikita of the Caves, Bishop of Novgorod","secs":[{"h":"Глас 3. Пісня 1","ps":["Ірмос: Су́шу глубороди́тельную зе́млю со́лнце наше́ствова іногда́: я́ко стіна́ бо, огусте́ обапо́ли вода́ лю́дем пешомореходя́щим і богоуго́дно пою́щим: пої́м Го́сподеві, сла́вно бо просла́вися.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","А́гнче непоро́чний, Бо́жий Сло́ве, отве́рзи моя́ недосто́йная уста́, да возмогу́ воспі́ти святи́теля Ники́ту, Твоєго́ уго́дника.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Болі́зньми по́стничеськими ду́шу просвіти́в, преподо́бне, я́ко чи́сту же́ртву Христу́ предста́вил єси́, ра́дуяся, поя́: сла́вно бо просла́вися.","Воздержа́нієм ті́ло ду́ху порабо́тил єси́, ду́шу же равноа́нгельну сотвори́л єси́. Помина́й ві́рою чту́щия тя, поя́ Бо́гу: сла́вно бо просла́вися.","Богородичен: Господороди́тельнице Влади́чице Марі́є, моли́, Єго́же родила́ єси́, Бо́га і Царя́ на́шего, да ми́лостив бу́деть нам в день Су́дний."]},{"h":"Пісня 3","ps":["Ірмос: Непло́дная душе́ і безча́дная, стяжи́ плод благосла́вний, веселя́щися, возопи́й: утверди́хся Тобо́ю, Бо́же, ність свят, ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Ді́латель бив за́повідей Госпо́дніх, непреста́нно в них поуча́яся, о́тче Ники́то, сего́ ра́ди вшел єси́ в небе́сная, вопія́ ра́достно: ність свят і ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Єгда́, зави́дів тебі́, прелука́вий хотя́ше зап'я́ти от доброді́телей, сопротивоста́в, преподо́бне, без ві́сти того́ сотвори́л єси́, Христу́ вопія́: ність свят і ність пра́веден, па́че Тебі́, Го́споди.","Житіє́м доброді́тельним Бо́гу угоди́л єси́, велія́ра посрами́в, і Христу́ возопи́л єси́: ність свят і ність пра́веден, па́че Тебі́, Го́споди.","Богородичен: Зачала́ єси́ О́тчеє Сло́во Іпоста́сноє, Єго́же моли́, Богоро́дице, ізба́вити от бід раби́ Твоя́, воі́стину призива́ющия Тя."]},{"h":"Сідален, глас 1","ps":["Я́ко сад присноцвіту́щ, лю́ди твоя́ сотвори́л єси́, сія́ во благоче́стії возрасти́в, умно́жил єси́, і от сего́ ві́рен раб і ді́латель виногра́да Христо́ва показа́лся єси́, і трудо́м возме́здіє досто́йно восприя́л єси́, святи́телю, моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша.","Богородичен: Всіх Творця́, Бо́га же і Соді́теля, Всенепоро́чная Чи́стая, Ду́хом Боже́ственним в ложесна́х Твої́х заче́нши, без істлі́нія родила́ єси́. Єго́же сла́в'яще, Тя воспіва́єм, Ді́во, я́ко пала́ту Царя́ всіх і ми́ра заступле́ніє."]},{"h":"Пісня 4","ps":["Ірмос: Положи́л єси́ к нам тве́рдую любо́в, Го́споди: Єдиноро́днаго бо Твоєго́ Си́на за ни на смерть дал єси́. Ті́мже Ті зове́м, благодаря́ще: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Зако́ном оте́чеським послі́дуя і сих житіє́ подража́я, непреста́нно Христу́ взива́л єси́: сла́ва си́лі Твоє́й.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Із мла́да Христа́ возлюби́л єси́, сего́ ра́ди я́ко рачи́теля Своєго́ возлюби́ тя, к Нему́же вопіє́ши: сла́ва си́лі Твоє́й.","Ісполня́я зако́ни боже́ственния, преіспо́лнился єси́ дарова́ній боже́ственних, святи́телю Ники́то, ві́рно взива́єши: сла́ва си́лі Твоє́й, Го́споди.","Богородичен: Кади́льнице всезлата́я, Марі́є Всенепоро́чная, Христа́ моли́, Єго́же родила́ єси́, ізба́витися нам от бід і огня́ ві́чнующаго."]},{"h":"Пісня 5","ps":["Ірмос: К Тебі́ у́тренюю, всіх Творцю́, прейму́щему всяк ум ми́рові: зане́ світ повелі́нія Твоя́, в ни́хже наста́ви м'я.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Лук врага́ сокруши́л єси́, і брань єго́ до конця́ разори́л єси́, і соверше́нія доброді́телей, преподо́бне, дости́гл єси́.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Моли́твою возше́л єси́ на небе́сная, іді́же с ли́ки оте́ць пребива́я, весели́шися. Помина́й, преподо́бне, па́м'ять твою́ сві́тло торжеству́ющия.","Неізрече́нних та́їн Христо́вих служи́тель би́ти сподо́бился єси́ і, сія́ принося́ Бо́гу, за мир прилі́жно моли́лся єси́.","Богородичен: Упова́ніє і наде́жда на́ша Ти єси́, Пречи́стая Влади́чице, спаси́ лю́ди Твоя́, моля́щіяся і і́м'я Твоє́ призива́ющия."]},{"h":"Пісня 6","ps":["Ірмос: Бе́здна послі́дняя гріхо́в оби́де м'я, і ісчеза́єть дух мой, но простри́й, Влади́ко, висо́кую Твою́ ми́шцю, я́ко Петра́, м'я, Упра́вителю, спаси́.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Предизбра́н бив Боже́ственною благода́тію, во є́же па́ствити ста́до христоімени́то, ти же, преподо́бне, я́ко па́стир і́стинен, прилі́жно о ста́ді попече́ніє імі́л єси́.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Разу́мні разсужда́я, ча́да твоя́ і ча́сто наказу́я духо́вними словеси́, да пребу́дуть тве́рдо соблюда́юще ві́ру правосла́вную.","Святи́тельства че́стію почте́н, прилі́жно моле́ніє за лю́ди твоя́ приноси́л єси́: да ми́лостива Бо́га обря́щуть в день Су́дний.","Богородичен: Ти єси́, Пречи́стая Богоро́дице, прибі́жище на́ше і утвержде́ніє, моли́ Си́на Твоєго́ і Бо́га на́шего пода́ти нам спасе́ніє і гріхо́в оставле́ніє."]},{"h":"Кондак, глас 6","ps":["Архієре́йства са́ном почти́вся і чи́сті Чисті́йшему предстоя́, прилі́жно моле́ніє за лю́ди твоя́ приноси́л єси́, я́ко і дождь моли́твою свел єси́, овогда́ же і гра́да запале́нія угаси́л єси́. І ни́ні, святи́телю Ники́то, моли́ Христа́ Бо́га спасти́ лю́ди твоя́ моля́щіяся, да всі вопіє́м ті: ра́дуйся, святи́телю о́тче преди́вний."]},{"h":"Ікос","ps":["Кто не почуди́ться, кто не просла́вить неізслі́димую і несказа́нную глубину́ милосе́рдія Твоєго́, Христе́ Бо́же? Я́ко просла́вил єси́ в послі́днем ро́де уго́дника Твоєго́, святи́теля Ники́ту, єго́же обріто́шася честни́я мо́щі ці́ли і неразруши́ми. Єму́же рече́м: єгда́ во пло́ті бил єси́, преподо́бне, ді́ланії боже́ственними ду́шу предочи́стил єси́, святи́тельства па́ству восприї́м, сосу́д ізбра́н Боже́ственнаго Ду́ха показа́лся єси́ і ста́до твоє́ до конця́ во ві́рі утверди́л єси́. Тім ра́дуйся, о́тче преди́вний."]},{"h":"Пісня 7","ps":["Ірмос: Тріє́ о́троци в пещі́, Тро́йцю прообрази́вше, преще́ніє о́гненноє попра́ша і, пою́ще, вопія́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Уясня́ють, воспіва́юще, а́нгельстії чи́ни па́м'ять твою́, Ники́то святи́телю, і ми, земні́ї, уми́льно вопіє́м: іспроси́ нам оставле́ніє согріше́ній і благи́х наслажде́ніє.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Фарао́на ми́сленнаго побіди́л єси́, от Христа́ дерзнове́ніє приї́м, і ве́ліє ра́дованіє святи́м а́нгелом сотвори́л єси́, поя́: оте́ць на́ших Бо́же, благослове́н єси́.","Херуви́му подо́б'яся, легко́ на висоту́ возше́л єси́ і ни́ні со безпло́тними водворя́єшися, Христу́ вопія́: оте́ць на́ших Бо́же, благослове́н єси́.","Богородичен: От утро́би Твоєя́ про́йде у́мноє, Богоро́дице, Со́лнце, Сего́ моли́, я́ко Си́на Твоєго́ і Го́спода, пода́ти нам скорбе́й разріше́ніє і болі́зней облегче́ніє, да ра́достно от душі́ вопіє́м Христу́: отце́в на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Веще́ственнаго огня́ пла́мень невеще́ственним ув'яди́ша богозри́мії о́троци і поя́ху: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Лю́дем Українським, іспроси́, Ники́то святи́телю, мир, здра́віє, спасе́ніє і на враги́ одолі́ніє, да в ра́дості душе́вній возопіє́м: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Чу́вственния стра́сті побіди́в, чистото́ю, я́ко со́лнце, возсія́л єси́, чи́сто житіє́ до конця́ сохрани́л єси́ і Бо́гу тім угоди́л єси́. Єму́же вопіє́м: благослові́те, вся діла́ Госпо́дня, Го́спода.","Шум пра́зднующих сли́шати, святи́телю, сподо́бился єси́: шу́їяго стоя́нія ізба́ви м'я і страсте́й треволне́нія і к приста́нищу покая́нія наста́ви м'я, да тя сла́влю во вся ві́ки.","Богородичен: Ще́драго і человіколюби́ваго Бо́га роди́ти, Богоро́дице, сподо́билася єси́, Того́ моли́, Неіскусобра́чная Отрокови́це, низпосла́ти нам, ві́рним, ве́лію ми́лость."]},{"h":"Пісня 9","ps":["Ірмос: В зако́ні сі́ні і писа́ній о́браз ви́дим, ві́рнії: всяк му́жеський пол, ложесна́ разверза́я, свят Бо́гу. Тім перворожде́нноє Сло́во Отця́ Безнача́льна, Си́на, первородя́щася Ма́терію неіскусому́жно, велича́єм.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Мо́ре жите́йськоє препли́во воздержа́нієм, дости́гл єси́ широти́ ра́йськия, іді́же со а́нгели при́сно весели́шися.","Приспів: Святи́телю, о́тче Ники́то, моли́ Бо́га о нас.","Ра́ка моще́й твої́х, святи́телю, дража́йши сапфи́ра показа́ся, чудотвори́ва бо бі і ісціле́нія істоча́ющи. Єя́же облобиза́юще с ві́рою, приходя́щії ра́достно от душі́ вопію́ть: сон че́стен пред Го́сподем смерть преподо́бних Єго́.","Крестоно́сно предстої́ши престо́лу Вседержи́теля, сла́вою осіява́єм Сві́та Присносу́щнаго. Моли́ся, Ники́то святи́телю, о чту́щих ві́рно па́м'ять твою́.","Богородичен: Лук сокруши́ся лука́ваго одолі́нієм Си́на Твоєго́ і Бо́га на́шего, чу́дна побі́да, Богоро́дице, і ди́вно одолі́ніє соді́яся, Влади́чице, во спасе́ніє душ на́ших."]},{"h":"Світилен","ps":["Плотська́я мудрова́нія ду́ху повину́л єси́ і, я́ко зла́то, огне́м іскуси́вся, прия́телище бил єси́ Ду́ху Пресвято́му, о́тче Ники́то святи́телю.","Богородичен: Тя пі́сньми ублажа́єм, Ді́во, Бо́га бо роди́вши, на руку́ носи́ла єси́, Того́ моли́ за ду́ші на́ша."]}],"notes":[]}];
export default D;
